    ['??? Warmachine (S)'] = { zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) E-7', note = 'Involved in Quests:\n* Gifts of the Griffon\n* Wrath of the Griffon\n* Perils of the Griffon\n* Bonds That Never Die\n\nNotes:\n* This machine has Engineer Bistillot inside, a member of the Young Griffons. *The present version is only related by name. They are not the same Warmachine.' },
    ['1st Gold Musketeer'] = { type = 'Campaign Battle ally NPC', zones = { 'Bastok (S)', 'Battle', 'Rolanberry Fields (S), Pashhow Marshlands (S), Grauberg (S) Bastok Markets (S)' }, location = 'Rolanberry Fields (S), Pashhow Marshlands (S), Grauberg (S) Bastok Markets (S)', note = 'Notes:\nFollows Elivira. Uses Marksmanship weaponskills.' },
    ['1st Iron Musketeer'] = { type = 'Campaign Battle ally NPC', zones = { 'Bastok (S)', 'Battle', 'Rolanberry Fields (S), Pashhow Marshlands (S), North Gustaberg (S)' }, location = 'Rolanberry Fields (S), Pashhow Marshlands (S), North Gustaberg (S)', note = 'Notes:\n*  Appears during Offensive Campaign Battles in Rolanberry and Pashhow, following Bartholomaus. They will cure themselves and Bartholomaus, as well as use tier III black magic on their targets. *They are among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once Bastok regains most territory in their cordon.' },
    ['1st Legion Aidman'] = { type = 'Campaign Battle ally NPC', zones = { 'Bastok (S)', 'Battle', 'Belfry' }, location = 'Belfry', note = 'Notes:\n* Spawned by an Allied Belfry erected by the Republican Army of Bastok. Participates in offensive Campaign Battles. A maximum of 5 reinforcements will appear, and they will continually respawn unless the belfry is demolished. *They will immediately charge to the Fortifications and attack any defenders they encounter. *Capable of casting a few spells such as Diaga II, Dia II, Banish III, Banishga III, Poisona and Holy which they will use very often. *They fight with Hand-to-Hand damage and are capable of using the following weaponskills: Combo, Spinning Attack, One Inch Punch, Raging Fists and Backhand Blow. "1st Legion" probably indicates they are part of Legatus Berger\'s 1st Division/Legion.' },
    ['1st Legion Mercenary'] = { type = 'Campaign Battle NPC', zones = { 'Bastok (S)', 'Battle', 'Belfry' }, location = 'Belfry', note = 'Notes:\n* Spawned by an Allied Armored Belfry erected by the Republican Army of Bastok. Participates in offensive Campaign Battles. A maximum of 5 reinforcements will appear, and they will continually respawn unless the belfry is demolished. *They will immediately charge to the Fortifications and attack any defenders they encounter.' },
    ['1st Legion Reiter'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)Crawlers\' Nest (S)', 'Battle' }, location = 'Bastok Markets (S)Crawlers\' Nest (S)', note = 'Notes:\n* Appears in Campaign Battles in Bastok Markets (S) and Crawlers\' Nest (S), following Else. They will cure themselves, as well as Else. *"1st Legion" probably indicates they are the cavalry of Legatus Berger\'s 1st Division/Legion.' },
    ['1st Legionnaire'] = { type = 'Campaign Battle ally NPC', zones = { 'Bastok (S)', 'Battle', 'Grauberg (S)' }, location = 'Grauberg (S)', note = 'Notes:\n* Appears during Campaign Battles in North Gustaberg and Grauberg, following Maximilian. Uses Marksmanship weaponskills. *They are among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once Bastok regains most territory in their cordon.' },
    ['2nd Legion Grenadier'] = { zones = { 'Bastok (S)', 'Battle', 'Rolanberry Fields (S)' }, location = 'Rolanberry Fields (S)', note = 'Notes:\n* Appears in Campaign Battles at Rolanberry Fields, following Striking Bull. *"2nd Legion" probably indicates they are the heavy infantry of Legatus Eichberg\'s 2nd Division/Legion.' },
    ['2nd Legion Scout'] = { type = 'Campaign Battle ally NPC', zones = { 'Bastok', 'Battle', 'Grauberg (S)' }, location = 'Grauberg (S)', note = 'Notes:\n* Appears during Campaign Battles in Grauberg, following Adelheid. Casts Protect IV and Shell III on themselves and other NPC units; will also cast Helix spells on the enemy. Despite being Scholars, they wield a polearm and use Penta Thrust fairly often. *"2nd Legion" probably indicates they are part of Legatus Eichberg\'s 2nd Division/Legion.' },
    ['2nd Legionnaire'] = { type = 'Campaign Battle ally NPC', zones = { 'Bastok (S)', 'Battle', 'North Gustaberg (S)' }, location = 'North Gustaberg (S)', note = 'Notes:\nParticipates in offensive Campaign Battles in North Gustaberg (S). Casts Dark Knight spells (such as Absorb-TP), but uses polearm weaponskills at least up to Skewer.' },
    ['3rd Legionnaire'] = { type = 'Campaign Ally', zones = { 'Bastok (S)', 'Battle', 'North Gustaberg (S) during Campaign' }, location = 'North Gustaberg (S) during Campaign' },
    ['4th Legionnaire'] = { type = 'Campaign Battle NPC', zones = { 'Bastok (S)', 'Varies' }, location = 'Varies', note = 'Notes:\n* Appears during Campaign Battles as part of the Fourth Division Centurion unit. *In areas under allied control, they will deliver supplies to the fortifications and warp out. *In areas under beastman control, they will attempt to bomb the fortifications. *They will attempt to construct an Allied Belfry in offensive Campaign battles when Bastok\'s technological level allows.' },
