    ['Abby Jalunshi'] = { type = 'MogHouse Watcher', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods F-8', note = 'Notes:\nChecking Abby_Jalunshi will start a conversation with her about Mog Houses. She give you 2 options to start- :: *Nothing in General :: *Ask for an explanation on Mog houses. If you choose the "Nothing in General option, she will just say: "Oh Well, Your Loss" and turn away. If you choose the Other option she says: "A mogHouse is your own personal apartment room provided for your convienience. Within your MogHouse you can store items, change jobs, and heal up any HP or MP' },
    ['Abd-al-Raziq'] = { type = 'Guild Master', zones = { 'Bastok', 'Bastok Mines' }, location = 'Bastok Mines L-7', note = 'Involved in Quests:\n* Lost Chick\n\nInvolved in Missions:\n* That Which Curdles Blood\n\nNotes:\n:*Sign you up for the Alchemy Guild :*Accept the items you need to turn in, to go up in rank for the Alchemy Guild.' },
    ['Abda-Lurabda'] = { type = 'Puppet Name Changer', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate I-7 - Automaton Shop', note = 'Involved in Missions:\n* Aht Urhgan Mission 9: Undersea Scouting\n\nNotes:\n* Tarutaru working hard to be the best Puppet Scientist. *Speaking with him as Puppetmaster will allow you to obtain the option to change your puppetname for 9800 gil. For a complete list of names, see Automaton.' },
