    ['Afdeen'] = { type = 'Abdhaljs Isle-Purgonorgo Officer;NPC', zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno H-9', note = 'Notes:\nA student of the great mage Abdhaljs, he handles transport to and the use of Abdhaljs Isle-Purgonorgo (where Brenner is played). He (as well as the Marshal behind him) will handle all Brenner-related affairs, including distribution of the Brenner Bluebook & Brenner Blackbook.' },
