    ['Ailbeche'] = { type = 'Quest Giver NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria J-9', note = 'Starts Quests:\n* Father and Son\n* Sharpening the Sword\n* A Boy\'s Dream\n\nInvolved in Quests:\n* Under Oath\n* Son and Father\n\nNotes:\nThis NPC is involved in the storyline of the Paladin' },
    ['Ailee'] = { zones = { 'Norg' }, location = 'Norg H-8' },
    ['Ailevia'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria I-9', note = 'Involved in Quests:\n* Adventurer Coupon\n\nNotes:\nOffers Directions Around Town: :This is Southern San d\'Oria. I know a thing or two about these streets. Would you like to learn about this area? :*"I\'m interested.": To the north stands Victory Arch. Carved from its two mighty pillars are statues that represent the two orders: the Temple Knights and the Royal Knights. Northern San d\'Oria lies beyond, where you\'ll find Chateau d\'Oraguille, the cathedral, and the consulates of our allies. West is Pikeman\'s Way, where you\'ll find shops, grocers, and the Tanners\' Guild. Across from the stalls is the Westgate, which leads outside. East is Cavalry Way, where you\'ll find armor and weapon shops as well as a tavern. The residential area lies at the end. :*"No, thanks." :*Trade and Adventurer Coupon to obtain 50 gil' },
    ['Aishah'] = { zones = { 'Bastok', 'Port Bastok' }, location = 'Port Bastok F-7' },
