    ['Aivedoir'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria F-6', note = 'Notes:\n"That\'s Funny. I could have sworn she asked me to meet her here..."' },
    ['Ajahkeem'] = { zones = { 'Jeuno', 'Ru\'Lude Gardens' }, location = 'Ru\'Lude Gardens G-9 Located near to Rendezvous Point', note = 'Notes:\n* Exchanges fellow points for items for yourself and your fellow. *To gain access to fellow points, equip your Signal Pearl and speak to Luto Mewrilah in Upper Jeuno (G-8) for a cutscene. *Go to G-9 in Ru\'Lude Gardens, next to the Rendezvous Point, and speak with Ajahkeem for a second cutscene. This may not trigger until some level of bond between zero and the amount required for Past Reflections is obtained{{verification' },
    ['Aja-Panja'] = { zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods H-12', note = 'Notes:\nUpon checking Aja Panja you will recieve the following diologue: ::* If you want to learn how to craft bone into something useful, then you should study with us here at the Boneworker\'s Guild!' },
    ['Ajen-Myoojen'] = { zones = { 'Windurst', 'Windurst Waters map = North|F-4' }, location = 'Windurst Waters map = North|F-4' },
    ['Ajen-Myoojen (S)'] = { zones = { 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) F-4', note = 'Notes:\n"Hold on there, mister-wister!/missie-wissie! Do you know what\'s waiting on the other side of this gate for tenderific morsels like you, huh? Oh, you do now, do you? Well, it\'s your funeral..."' },
    ['Ajido-Marujido'] = { type = 'Cutscene NPC', zones = { 'Battle', 'Cutscene', 'Heavens Tower', 'Windurst' }, location = 'Heavens Tower', note = 'Involved in Quests:\n* I Can Hear a Rainbow\n* Wonder Wands\n\nInvolved in Missions:\n* Windurst Mission 1-1: The Horutoto Ruins Experiment\n* Windurst Mission 2-1: Lost for Words\n* Windurst Mission 3-1: To Each His Own Right\n* Windurst Mission 3-2: Written in the Stars\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Windurst Mission 6-1: Full Moon Fountain\n* Windurst Mission 8-2: The Jester Who\'d Be King\n* Windurst Mission 9-1: Doll of the Dead\n* Windurst Mission 9-2: Moon Reading\n\nNotes:\nBiography: Ajido-Marujido is the "rogue" Minister of Windurst\'s Orastery, the Ministry of Windurst that oversees the use of magic and the training of mages. He is also the son of the creator of the Cardians and the former Minister of the Manustery Zonpa-Zippa, and is the brother of current Manustery Minister Apururu. Although a very powerful mage and a well-respected public figure, he is always getting himself or a random adventurer into trouble in his pursuit for the truth about Windurst and its past. Although labeled as unpredictable and a rogue, he cares deeply about the future of Windurst and its well-being, even more so than his reputation and his political career. He is introduced to us as a "Child Genius" student in one of the early Wings of the Goddess missions. Even then he has a flair for getting himself, and you, into trouble. He later becomes one of Shantotto\'s pupils prior to his role of minister of the Orastery Battle NPC: Ajido-Marujido fights alongside the party during the battlefield event at Full Moon Fountain for Windurst Mission 9-2: Moon Reading. He fights in the second round of the battle, versus Vyala and Tatzlwurm. Ajido-Marujido must be kept alive, because if he falls the battle will be considered a loss; and since he has low HP and grabs enmity very easily with his powerful spells, it\'s important to keep the heat off him. Ajido can cast all ancient magic, uses both Chainspell and Manafont, teleports around the arena, and has an unusual hand-to-hand attack style similar to Mammets.' },
    ['Ajido-Marujido (A)'] = { zones = { 'Abyssea', 'Abyssea - Altepa' }, location = 'Abyssea - Altepa K-5' },
    ['Ajido-Marujido (S)'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Windurst (S)' }, note = 'Involved in Quests:\n* The Tigress Stirs\n* The Tigress Strikes\n* Knot Quite There\n* Sins of the Mothers\n* Howl from the Heavens' },
    ['Ajimo-Majimo, W.W.'] = { type = 'Conquest Overseer', zones = { 'The Sanctuary of Zi\'Tah', 'Windurst' }, location = 'The Sanctuary of Zi\'Tah H-9', note = 'Notes:\nAppears, when Li\'Telor is under weekly conquest-control by Windurst ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Li\'Telor Supplies for finishing Supply Quest :*Accepts Garrison starting item Hound Fang Sack ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Ajithaam'] = { zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno F-5', note = 'Starts Quests:\n* Lure of the Wildcat (Jeuno)\n\nNotes:\nTeleportation Service: :Available to registered mercenaries upon completion of Lure of the Wildcat (Jeuno). :Teleports you to Aht Urhgan Whitegate (I-12) if you trade him 300g.' },
