    ['Akane, I.M. (Meriphataud Mountains)'] = { type = 'Conquest Overseer - Bastok Outpost Conquest Guard', zones = { 'Bastok', 'Meriphataud Mountains' }, location = 'Meriphataud Mountains E-5', note = 'Notes:\nAppears, when Aragoneu is under weekly conquest-control by Bastok ;Notes for characters only with Bastok as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Aragoneu Supplies for finishing Supply Quest :*Accepts Garrison starting item Thirteen-Knot Quipus ;Notes for characters only without Bastok as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil)' },
