    ['Akta'] = { zones = { 'Jeuno', 'Ru\'Lude Gardens' }, location = 'Ru\'Lude Gardens H-10', note = 'Notes:\nDialog: A mighty fine palace, this is. Why, it\'s like a castle in the clouds! I\'m so glad I came all this way to see it.Oh, now where\'d the wife head off to? I suppose she\'ll show up if I stay put here.' },
