    ['Albinie'] = { type = 'Standard Merchant NPC', zones = { 'Located on the airship dock in Port San d\'Oria at', 'San d\'Oria' }, location = 'Located on the airship dock in Port San d\'Oria at H-6; only accessible with an Airship pass.' },
    ['Albiona'] = { zones = { 'Jeuno', 'Ru\'Lude Gardens' }, location = 'Ru\'Lude Gardens H-9', note = 'Involved in Quests:\n* Lure of the Wildcat (Jeuno)\n\nNotes:\nDialog: In the past, there was a terrible war. My father once told me how the earth, swept by furious winds, was soaked in the blood of the fallen. I heard his tales every time he drowned his sorrows in drink. Now his stories are etched in my mind.' },
