    ['Allied Armored Belfry'] = { type = 'Campaign Battle ally NPC', zones = { 'Jeuno (S)', 'Varies' }, location = 'Varies', note = 'Notes:\n* Set up by members of the Allied Forces of Altana in an enemy area when technology levels reach an unknown threshold. The groups that set them up are involved with supplies/sabotage. :*Spawns reinforcements that attack fortifications, depending on which force installed it: ::*Bastokan Forces: 1st Legion Mercenary ::*San d\'Orian Forces: Royal Esquire ::*Windurstian Forces: Cardian Prototype ::*Northland Forces: Scylla Brigade Elite :*Reinforcements spawn every 30-60 seconds. :*Every so often a group of support NPCs will enter the battle and repair the Allied Belfry, restoring a portion of its HP. *Cannot be cured.' },
    ['Allied Belfry'] = { type = 'Campaign Battle ally NPC', zones = { 'Jeuno (S)', 'Varies' }, location = 'Varies', note = 'Notes:\n* Set up by members of the Allied Forces of Altana in an enemy area when technology levels reach an unknown threshold. The groups that set them up are involved with supplies/sabotage. :*Spawns reinforcements that attack fortifications, depending on which force installed it: ::*Bastokan Forces: 1st Legion Aidman ::*San d\'Orian Forces: Royal Banneret ::*Windurstian Forces: Wildcat Vanguard ::*Northland Forces: Scylla Brigade Officer :*Reinforcements spawn every 30-60 seconds. :*Every so often a group of NPC\'s will enter the battle and cure the Allied Belfry, restoring a portion of its HP. *Cannot be cured.' },
    ['Allied Ensign'] = { zones = { '*North Gustaberg (S)' }, location = '*North Gustaberg (S) (K-8) *West Sarutabaruta (S) (I-9) *East Ronfaure (S) (G-5)', note = 'Notes:\n* Used in Campaign' },
    ['Allied Mantelet'] = { type = 'Campaign Battle ally NPC', zones = { 'Battle', 'Varies' }, location = 'Varies', note = 'Notes:\n* Constructed in Allied Forces-controlled areas by their respective engineer units (4th Legionnaires, Gold Badger Esquires, and Piscean Casters).{{verification' },
    ['Almid'] = { type = 'Quest NPC', zones = { 'Bastok', 'Cutscene', 'Cutscenes' }, location = 'Cutscenes', note = 'Involved in Quests:\n* Vegetable Vegetable Frustration\n\nNotes:\nOne of the men killed in the Palborough Mines accident 20 years ago.' },
    ['Alois'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks J-8', note = 'Involved in Quests:\n* Faded Promises\n\nInvolved in Missions:\n* Bastok Mission 2-2: Wading Beasts\n* Bastok Mission 9-1: The Salt of the Earth' },
    ['Aloysius, I.M.'] = { type = 'Campaign NPC', zones = { 'Bastok (S)', 'La Vaule (S)' }, location = 'La Vaule (S)', note = 'Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok has control of La Vaule (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation. *Campaign Sword in front of name during Campaign.' },
    ['Alphollon C Meriard'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria L-6, in the Manuscript Room in the Cathedral', note = 'Notes:\nRemoves the curse from cursed equipment and food when given the item along with the corresponding abjuration.' },
    ['Alphonimile'] = { type = 'Cutscene', zones = { 'Cutscene', 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S)', note = 'Involved in Quests:\n* Gifts of the Griffon\n* Perils of the Griffon\n* In a Haze of Glory\n* The Price of Valor\n* Blood of Heroes\n\nNotes:\nThe father of Excenmille.' },
    ['Alphonserme'] = { zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin G-8' },
    ['Alrauverat'] = { type = 'Conquest Overseer - Jeuno Conquest Guard', zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno F-11', note = 'Notes:\n;Notes for all characters: :*Casts Signet :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts traded Crystals for filling up the Mission-Rank bar of the character\'s appropriate Nation (the red bar at the character\'s profile) :*Sells items for Conquest Points of the character\'s appropriate Nation (Items for Bastok / Items for San d\'Oria / Items for Windurst) at certain conditions. It will be also possible to get some items of other Nations at the guards, if your current Allegiance ranks higher at the weekly Conquest results (for further information see under the items articles) :*Explains the Conquest system by choosing some available questions. For further information see Conquest Overseer.' },
    ['Alrauverat (A)'] = { zones = { 'Abyssea', 'Abyssea - Attohwa' }, location = 'Abyssea - Attohwa H-8', note = 'Notes:\n* Used to get down from the Field Encampment (or the player can jump the ledge which is quicker). Simply talk to him, then he will teleport you below the ledge to Red Ghost.' },
    ['Alreage, R.K.'] = { type = 'Campaign NPC', zones = { 'San d\'Oria (S)', 'Sauromugue Champaign (S)' }, location = 'Sauromugue Champaign (S), (H-7)', note = 'Notes:\n* San d\'Oria affiliated Campaign Arbiter. Present when San d\'Oria (S) has control of Sauromugue Champaign (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Altair'] = { zones = { 'Bastok', 'Cutscene', 'Jeuno', 'Ru\'Lude Gardens' }, location = 'Ru\'Lude Gardens H-10', note = 'Involved in Missions:\n* Bastok Mission 3-3: Jeuno\n* Bastok Mission 4-1: Magicite' },
    ['Altana'] = { type = 'Cutscene NPC', zones = { 'Cutscene' }, note = 'Involved in Missions:\n* *{{Information Needed\n\nNotes:\nAltana is the Dawn Goddess and creator of Vana\'diel. It is said that she created the Zilart, but once they were destroyed, she cried five tears down on the world that resulted in the creation of the five races: Hume, Elvaan, Mithra, Tarutaru and Galka. The Twilight god Promathia resented this, and created evil monsters that would seek to destroy Altana\'s creations. Promathia also cursed each of the five races with one negative trait each, for example, the Elvaan became arrogant. Altana is often mentioned and is the central character for the religion in Vana\'diel, represented by the San d\'Orian Cathedral. During the Crystal War, all four nations joined forces under the name of The Allied Forces of Altana.' },
    ['Altennia'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'San d\'Oria (S)', 'Southern San d\'Oria (S) cutscenes' }, location = 'Southern San d\'Oria (S) cutscenes', note = 'Involved in Quests:\n* Gifts of the Griffon\n* Claws of the Griffon\n* Wrath of the Griffon\n* Perils of the Griffon\n\nNotes:\nAltennia is a young squire who looks after the Young Griffons, and is normally the only adult they allow in on their meetings. She is the sister of Halver.' },
    ['Altiret'] = { type = 'Quest Giver NPC', zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria I-8', note = 'Starts Quests:\n* The Pickpocket' },
    ['Alystair'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Jeuno (S)' }, note = 'Involved in Missions:\n* Cavernous Maws (WOTG01)\n* A Nation on the Brink (WOTG14)\n\nNotes:\n* He is a Corporal of the Ducal Knights of the Grand Duchy of Jeuno during the Crystal War. *His supervisor is Sergeant Barnabas under the leadership of Captain Lysander.' },
