    ['Angelica'] = { type = 'Quest NPC', zones = { 'Windurst', 'Windurst Waters map = North|F-10 "Rarab Tail Hostelry" "2? floor = Hostelry room #1"' }, location = 'Windurst Waters map = North|F-10 "Rarab Tail Hostelry" "2? floor = Hostelry room #1"', note = 'Starts Quests:\n* A Pose by Any Other Name\n\nInvolved in Quests:\n* A Question of Taste\n* Picture Perfect\n* Starlight Celebration 2008' },
    ['Angieurol'] = { zones = { 'Tavnazian Safehold' }, location = 'Tavnazian Safehold G-8' },
    ['Angry Bull'] = { type = 'Great War Recaller NPC', zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets H-11', note = 'Notes:\nDialogue: I remember 20 years ago when I was in charge of protecting Galkan Bridge from the beastmen. For a large part of the Crystal War, we had her blocked off on both sides. The government said it was to keep enemy spies from infiltrating Bastok\'s central areas. However, there was rumor that it was to prevent Galka from coming over on this side of the river and rioting. It would be a lie if I told you it wasn\'t hard for me, a Galka, to work against my brothers like that. I still have nightmares about the time I had to force back groups of refugees trying to escape the flames that engulfed their homes in the mines district. And now I\'m back here patrolling the bridge as I did long ago. Perhaps destiny has a tighter grip on us than I thought...' },
    ['Angry Bull (S)'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) H-10', note = 'Notes:\n"The Galkan Bridge is currently closed to prevent infiltration by beastman spies."' },
    ['Angry Goat'] = { zones = { 'Rabao' }, location = 'Rabao G-11' },
    ['Anguenet'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'Carpenters\' Landing', 'San d\'Oria' }, location = 'Carpenters\' Landing J-10', note = 'Starts Quests:\n* Mithran Delicacies\n\nInvolved in Quests:\n* Tea with a Tonberry?' },
    ['Anguysh'] = { type = 'Adventurer\'s Assistant', zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets I-9' },
    ['Anguysh (A)'] = { zones = { 'Abyssea', 'Abyssea - Misareaux' }, location = 'Abyssea - Misareaux (K-7)' },
    ['Anieuvansand'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria I-7' },
    ['Anilla'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria J-8', note = 'Involved in Quests:\n* Lure of the Wildcat (San d\'Oria)\n\nNotes:\nDialogue: If quest "Lure of the Wildcat (San d\'Oria)" is active: Anilla: The other day I saw a man wandering around town wearing the most unusual clothing. Is there some fesitval I am not aware of? Matildie: How could you possibly not have heard? The Near Eastern folk are recruiting soldiers on a massive scale to quell some war that is raging with the beastmen. Anilla: You cannot be serious! Do you mean to tell me that another frightful Crystal War once more threatens our fair home? Matildie: There is no need to be so dramatic, Anilla. The Near East is not quite so near as to warrant an immediate descent into panic and despair. The only people this news pertains to are those action-hungry adventurers. Anilla: Speaking of which, I had one of those unruly brutes burst into my home while I was dusting, and proceed to boast about some badge he\'d received... Matildie: Simply unforgivable. If one must brag of some possession so badly, one should at least observe the common courtesy of knocking...' },
    ['Anillah'] = { type = 'Synthesis Image Support NPC :*Weaver\'s Guild', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods G-12', note = 'Notes:\nAnillah is one of two workers who provides free synthesis support for clothcrafting in Windurst. Speaking with her will raise your clothcrafting skill ever so slightly, and give you a better chance at successful synths. After speaking with her however, you may not ask any other NPC for synthesis support until the one she has given you has worn away. Anillah is also in charge of the low-level recipe list; if you ask her about recipes, she will tell you any recipe that is below your current skill level.' },
    ['Anini'] = { zones = { 'Windurst', 'Windurst Walls' }, location = 'Windurst Walls H-5' },
    ['Anja-Enja'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'Windurst', 'Windurst Waters' }, location = 'Windurst Waters F-12', note = 'Notes:\nOffers Directions Around Town: :Hiya! Are you lost or something? If you\'re in trouble, Anja-Enja\'s here to helpy-welpy! :*"Nothing right now.": Well, if you ever need help, feel free to ask one of us guards. Helping out people in need is the calling of us guards in Windurst Waters\'s "North Winds" troupey-woupey. :*"Where are we?": This is the Windurst Waters district. Just north of here are the Opistery, the Aurastery, and a general goods store. South of here are the Rhinostery and the hatter\'s. :*"How to leave town.": The quickest way to leave town from here is Odin\'s Gate, which takes you out to West Sarutabaruta. Head north and pass through the archway of the Opistery\'s Library of Magic. Then go over the bridge until you get to the northern gatehouse. (That\'s where we guards of Windurst Waters meet, you know?) Head through the gate and you\'ll find yourself outside in West Sarutabaruta. :*"Where\'s the residential area?": Windurst\'s residential area is northeast of here. To get there, first head north and cross the bridge to the east that leads to the Aurastery and Windurst Walls. On the way, you\'ll come across a Cardian automaton guard. Turn right when you see him and you\'ll easily find your way there.' },
    ['Annabelle'] = { type = 'Campaign Evaluator', zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) F-8', note = 'Notes:\n* Annabelle provides evaluations for players aligned with the Fighting Fourth.' },
