    ['Aphmau'] = { type = 'Cutscene NPC', zones = { 'Al Zahbi', 'Cutscene', 'Imperial Ward' }, location = 'Imperial Ward', note = 'Involved in Quests:\n* Saga of the Skyserpent\n* Soothing Waters\n\nStarts Missions:\n* Aht Urhgan Mission 29: Puppet in Peril\n* Aht Urhgan Mission 35: Legacy of the Lost\n\nInvolved in Missions:\n* Aht Urhgan Mission 11: Imperial Schemes\n* Aht Urhgan Mission 12: Royal Puppeteer\n* Aht Urhgan Mission 18: Passing Glory\n* Aht Urhgan Mission 19: Sweets for the Soul\n* Aht Urhgan Mission 20: Teahouse Tumult\n* Aht Urhgan Mission 21: Finders Keepers\n* Aht Urhgan Mission 23: Social Graces\n* Aht Urhgan Mission 28: Bastion of Knowledge\n* Aht Urhgan Mission 30: Prevalence of Pirates\n* Aht Urhgan Mission 32: In the Blood\n* Aht Urhgan Mission 34: Testing the Waters\n* Aht Urhgan Mission 35: Legacy of the Lost\n\nNotes:\nA royal puppetmaster residing in the Imperial Ward, with her automaton companions Ovjang and Mnejing. Aphmau is not all she seems, her true self being revealed in Aht Urhgan Mission 32: In the Blood.' },
    ['Apolliane'] = { type = 'Quest NPC', zones = { 'Adoulin', 'Morimar Basalt Fields' }, location = 'Morimar Basalt Fields K-10', note = 'Starts Quests:\n* A Stone\'s Throw Away' },
    ['Apollyon Furnace'] = { zones = { 'Apollyon' }, location = 'Apollyon', note = 'Notes:\n* Accepts trades of pieces of {{Cl|Reforged Artifact Armor +3' },
    ['Apollyon Operator'] = { zones = { 'Apollyon' }, location = 'Apollyon', note = 'Notes:\n* Gives various explanations for the content flow within {{Cl|Limbus|Apollyon' },
    ['Appollonia'] = { type = 'Weather Reporter NPC', zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno G-6', note = 'Notes:\nChecks weather for the following locations: :*Valkurm Dunes :*Jugner Forest :*Batallia Downs :*Pashhow Marshlands :*Rolanberry Fields :*Meriphataud Mountains :*Sauromugue Champaign :*The Sanctuary of Zi\'Tah :*Qufim Island :*Jeuno' },
    ['Apstaule'] = { zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria H-10, on top of the Auction House', note = 'Involved in Quests:\n* The Brugaire Consortium' },
    ['Apururu'] = { zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods H-9', note = 'Starts Quests:\n* Can Cardians Cry?\n* Trust: Ajido-Marujido\n\nInvolved in Quests:\n* Making Amens!\n* Legendary Plan B\n* The Kind Cardian\n\nInvolved in Missions:\n* Windurst Mission 1-1: The Horutoto Ruins Experiment\n* Windurst Mission 1-2: The Heart of the Matter\n* Windurst Mission 6-2: Saintly Invitation\n* Windurst Mission 8-2: The Jester Who\'d Be King\n* Windurst Mission 9-1: Doll of the Dead\n* Windurst Mission 9-2: Moon Reading\n* A Crystalline Prophecy (Mission)\n\nNotes:\nApururu is current Minister of Windurst\'s Manustery, the Ministry of Windurst that is in charge of the creation, training, and maintenance of all Cardians. She is also the daughter of former Manustery Minister Zonpa-Zippa and the sister of current Orastery Minister Ajido-Marujido. She is constantly at odds with her brother over his recklessness, fearing that he may be getting in over his head. Her words, however, usually fall upon deaf ears.' },
    ['Apururu (A)'] = { zones = { 'Abyssea', 'H-12 Abyssea - Tahrongi' }, location = 'H-12 Abyssea - Tahrongi', note = 'Starts Quests:\n* His Box, His Beloved\n* When Good Cardians Go Bad' },
    ['Aquarian Caster'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Various', 'Windurst (S)' }, location = 'Various', note = 'Notes:\n* Leader of the Aquarian Casters is Kayeel-Payeel. *Squadron appears in various locations either fortifying or in Campaign Battles. *They are among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once Windurst regains most territory in their cordon. *Constantly recast Blaze Spikes. In battle, will cast various high-level black magic including Poisonga II.' },
    ['Aquila'] = { type = 'Cutscene NPC', zones = { 'Cutscene' }, note = 'Involved in Missions:\n* WOTG07: Purple, The New Black\n* WOTG08: In the Name of the Father\n* WOTG09: Dancers in Distress\n* WOTG15: Crossroads of Time\n* WOTG19: Betrayal at Beaucedine\n* WOTG25: The Will of the World\n* WOTG26: Fate in Haze\n* WOTG37: Darkness Descends\n\nNotes:\nOne of the Spitewardens of Lady Lilith, the leader of the "Cryptscale Protectorate" appears to be a human fomor. He acts very childish and frequently rubs Haudrale the wrong way....' },
    ['Aquillina'] = { type = 'Quest Giver', zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets K-9', note = 'Starts Quests:\n* A Flash in the Pan' },
