    ['Arpevion, T.K.'] = { type = 'Conquest Overseer - San d\'Oria National Conquest Guard', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria L-10', note = 'Notes:\n;Notes for characters only with San d\'Oria as current Allegiance: :*Casts Signet :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts traded Crystals for filling up the San d\'Oria Mission-Rank bar (the red bar at the character\'s profile) :*Sells items for Conquest Points (Items for San d\'Oria) at certain conditions. It will be also possible to get some items of other Nations (Items for Bastok / Items for Windurst) at the guards, if your current Allegiance ranks higher at the weekly Conquest results (for further information see under the items articles) :*Starts Supply Run Missions and offers a list of already delivered supplies :*Starts an Expeditionary Force by giving an E.F. region insignia to you :*Explains the Conquest system by choosing some available questions. ;Notes for characters only without San d\'Oria as current Allegiance: :*Doesn\'t offer any function For further information see Conquest Overseer.' },
    ['Arquil'] = { zones = { 'Tavnazian Safehold' }, location = 'Tavnazian Safehold J-9 upper level' },
