    ['Ayame'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks K-7, on the top level in the Cannonry', note = 'Starts Quests:\n* A Question of Faith\n* Out of the Depths\n* Return to the Depths\n* True Strength (MNK AF3)\n\nInvolved in Quests:\n* Faded Promises\n* Lure of the Wildcat (Bastok)\n* Trust: Bastok\n\nInvolved in Missions:\n* Bastok Mission 2-1: The Crystal Line\n* Bastok Mission 3-1: The Four Musketeers\n* Bastok Mission 6-2: The Pirates\' Cove\n* Bastok Mission 9-2: Where Two Paths Converge\n* Promathia Mission 1-3: The Mothercrystals\n* Promathia Mission 3-1: Call of the Wyrmking\n* Aht Urhgan Mission 38: Stirrings of War\n* A Crystalline Prophecy (Mission)\n\nNotes:\n* A member of the Mythril Musketeers. She is "Number 4". Plays a key role in multiple Bastok Missions.' },
    ['Ayame (A)'] = { zones = { 'Abyssea', 'Abyssea - Konschtat' }, location = 'Abyssea - Konschtat', note = 'Starts Quests:\n* Hope Blooms on the Battlefield\n* Rose on the Heath\n* Reports your progress towards finishing Abyssea - Konschtat\'s objectives.\n* =Goals completed=\n* Completing all quests: 8,000 Cruor.\n* Obtaining all Abyssite: 10,000 Cruor\n* Obtaining all Atma: 12,000 Cruor' },
    ['Aymeric, T.K.'] = { type = 'Campaign NPC', zones = { 'Castle Zvahl Baileys (S)', 'San d\'Oria (S)' }, location = 'Castle Zvahl Baileys (S)', note = 'Notes:\n* San d\'Oria affiliated Campaign Arbiter. Present when San d\'Oria has control of Castle Zvahl Baileys (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation. *Campaign Sword in front of name during Campaign.' },
