    ['Barnabas'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Jeuno (S)' }, note = 'Involved in Missions:\n* Cavernous Maws (WOTG01)\n* Borne by the Wind (WOTG11)\n* A Nation on the Brink (WOTG14)\n* Crossroads of Time (WOTG15)\n\nNotes:\n* A Sergeant of the Ducal Knights of the Grand Duchy of Jeuno during the Crystal War. *His supervisor is Captain Lysander. *One of his subordinates is Corporal Alystair.' },
    ['Barnett, C.A.'] = { type = 'Campaign NPC', zones = { 'Jeuno (S)', 'Pashhow Marshlands (S)' }, location = 'Pashhow Marshlands (S) K-4', note = 'Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of Pashhow Marshlands (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Bartabaq'] = { type = 'Outpost Vendor', zones = { 'Oldton Movalpolos' }, location = 'Oldton Movalpolos F-10', note = 'Notes:\nAppears, when Movalpolos is under weekly conquest-control by one of the three nations. - "Welkome to my vorder shop!" - "Kome vack again sometime!" Bartabaq is not a typical Outpost Vendor. She only sells items, which normally are sold by Regional Vendors of Movalpolos. The prices are dependent on the current Allegiance Rank. :*Sells and buys items to and from characters. :*All items, which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader\'s current Allegiance. Updated 7/13/2010: Gives text about willing to buy evolith items from weak nationed adventurers. For further information see Outpost Vendor. Note: If all 3 nations are in a tie for control of this area this npc will not appear. A single nation (not beastmen) must control it.' },
    ['Bartholomaus'] = { type = 'Campaign Battle Ally NPC', zones = { 'Bastok (S)', 'Bastok Markets (S)', 'Battle' }, location = 'Bastok Markets (S) L-8', note = 'Notes:\n:* Can appear in all Campaign Battles for Bastok (S) as the leader of the 1st Iron Musketeers. :*Bartholomaus is among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once Bastok regains most territory in their cordon. :* Uses Circle Blade for 200-600 damage, Vorpal Blade for 1400-3200 damage, Swift Blade for 900-1700, and his own unique AoE Weapon Skill called Glory Slash for 600-1300. :* Uses Mighty Strikes (can use more than once) and Warcry (every couple minutes). :* Talk: The Republic was formed with the blood and sweat of the people. The flames of freedom must continue to light our furnaces of strength. The waters of civilization must continue to turn our wheels of ingenuity! :* Battle Cry: You barbarians will regret the day you set foot on Bastokan soil!' },
    ['Bartholomaus Krueger'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) L-8', note = 'Involved in Quests:\n* Quelling The Storm\n* Honor Under Fire\n* Beneath the Mask\n\nNotes:\n"The republic was formed with the blood and sweat of the people. The flames of freedom must continue to light our furnaces of strength. The waters of civilization must continue to turn our wheels of ingenuity!"' },
    ['Bartolomeo'] = { zones = { 'Bastok', 'Port Bastok' }, location = 'Port Bastok F-7|Air Travel Agency', note = 'Involved in Quests:\n* Guest of HauteurWelcome to Bastok' },
    ['Barton, C.A.'] = { type = 'Campaign NPC', zones = { 'Castle Zvahl Keep (S)', 'Jeuno (S)' }, location = 'Castle Zvahl Keep (S) I-8', note = 'Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of Castle Zvahl Keep (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Bashraf'] = { zones = { 'Al Zahbi', 'Cutscene', 'Cutscenes only' }, location = 'Cutscenes only', note = 'Involved in Quests:\n* Give Peace a Chance\n* Three Men and a Closet\n\nNotes:\n* Friends with Foudeel and Wahboud; the three are seen during the Three Men and a Closet quest cutscenes. *Appears during the Sunbreeze Festival event Fantastic Fraulein Mumor 2010 to heckle Mumor and Uka. *If you are raising a chocobo, starting at the adolescent stage you will meet them on a walk in Tahrongi Canyon, La Theine Plateau, or Konschtat Highlands where they are raising a chocobo together. They will challenge you to a friendly competition.' },
