    ['Baya Hiramayuh'] = { type = 'Adventurer\'s Assistant', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate H-12, on the pier of Port Al Zahbi', note = 'Notes:\nTells you when the next ferry to and from Mhaura will arrive and depart.' },
    ['Beadurinc'] = { type = 'Guild Craftsman NPC :*Smithing Guild', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria E-6' },
    ['Bearer of Darkness'] = { type = 'Cutscene NPC', zones = { 'Cut Scenes Only', 'Windurst' }, location = 'Cut Scenes Only', note = 'Involved in Quests:\n* Sin Hunting\n* Wings of the Goddess Windurst Missionquest 9: The Forbidden Path\n\nInvolved in Missions:\n* Magicite (Bastok)\n* Magicite (San d\'Oria)\n* Magicite (Windurst)\n* Windurst Mission 8-1 Vain\n* Windurst Mission 9-1 Doll of the Dead\n* Windurst Mission 9-2 Moon Reading\n\nNotes:\nAn enigmatic creature of powerful dark magic, but when attacked, its blood shines a pure white that turns to shimmering dust on the ground. It has a strange habit of appearing at bodies of water during the full moon and seems to have an obsession with the Star Sibyl.' },
    ['Beastman Ensign'] = { zones = { '*Grauberg (S)', 'Beastman Confederate' }, location = '*Grauberg (S) (G-12) *Vunkerl Inlet (S) (J-7) *Fort Karugo-Narugo (S) (H-8)', note = 'Notes:\n* Used in Campaign Ops.' },
