    ['Belgidiveau'] = { type = 'Quest Giver NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria G-8', note = 'Starts Quests:\n* Trouble at the Sluice\n\nNotes:\n"These sluice gates divide Northern San d\'Oria into two parts: the Parade Grounds, and Laborman\'s Way." "Laborman\'s Way is much lower than the rest of the city. So to prevent flooding, we use these sluice gates to adjust the water for the entire district!"' },
    ['Belgidiveau (A)'] = { type = 'Quest NPC', zones = { 'Abyssea', 'Abyssea - Vunkerl' }, location = 'Abyssea - Vunkerl F-4 - Located by base camp near Wards.', note = 'Starts Quests:\n* A Ward to End All Wards' },
