    ['Benjamin'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) F-9', note = 'Notes:\n"The Allied Forces of Altana have been formed collectively by Jeuno and the three nations to combat the Beastmen Confederate. We\'ve no business in an alliance with Windurst, if you ask me. Those Windurstians are not to be trusted. Am I the only one who remembers the Elshimo Campaign!?"' },
    ['Berangere'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate L-9', note = 'Notes:\nTrades completed astrarium from Nyzul Isle Uncharted Area Survey for armor.' },
    ['Berengein'] = { zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) L-6' },
    ['Berghent'] = { type = 'Quest Giver NPC', zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin J-9', note = 'Starts Quests:\n* Flavors of Our Lives' },
    ['Beriphaule'] = { type = 'Immigration NPC NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria C-9', note = 'Notes:\nCost to Change Allegiance When San d\'Oria is in: *1st Place in Conquest - 40,000g *2nd Place in Conquest - 12,000g *3rd Place in Conquest - 4,000g Notes: *When changing allegiance, you retain all conquest points. *If this is the first time you\'ve switched to this nation, you are reset to Rank 1. *If you decide later to return to your previous Nation, you will get your previous Rank back. *Any rewards for missions done in other nations are retained when you switch (i.e. you will keep your Airship Pass, etc.) *All outpost teleports are no longer lost; you will not need to redo the supply quests if you return to your previous nation. :*This only applies to outpost data that was saved to the game on and after the 6/9/2008 patch. Any outpost data saved prior will have to be quested again. GMs have clarified that the reason for this inconvenience is due to previous "thematic" deletions of outpost data from completed supply missions at the time of the allegiance change. Example: A player was allied with San d\'Oria with all outposts complete and changed to Bastok on 5/1/08 and then obtained all outposts again. That player then changes allegiance to Windurst on 6/20/08. All outpost data for San d\'Oria is lost but all outpost data for Bastok is saved.' },
    ['Bernahn'] = { zones = { 'Al Zahbi', 'Cutscenes only' }, location = 'Cutscenes only', note = 'Involved in Quests:\n* Led Astray' },
    ['Bernal'] = { zones = { 'Davoi' }, location = 'Davoi J-8', note = 'Notes:\n* Located on a platform only accessible through Monastic Cavern, just across from Sedal-Godjal.' },
    ['Bernegeois'] = { type = 'Standard Merchant', zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin G-8 at Caf? des Larmes', note = 'Involved in Quests:\n* All the Way to the Bank' },
    ['Bernhard'] = { zones = { 'Bastok', 'Cutscene', 'Cutscenes' }, location = 'Cutscenes', note = 'Involved in Quests:\n* Lost in Translocation\n* A Jeweler\'s Lament\n\nInvolved in Missions:\n* The Fighting Fourth\n\nNotes:\n* Bernhard is a member of Decurion Roderich\'s decury which is a unit of Centurion Gerbhardt\'s century.' },
    ['Berstrogus'] = { zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin E-9' },
    ['Bertenont'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria E-4', note = 'Involved in Quests:\n* Lure of the Wildcat (San d\'Oria)\n* Her Memories: The Faux Pas\n\nNotes:\nDialogue: At night, the starry sky here is a sight to behold! If it weren\'t for all those chimneys, it\'d be a finer sight still! If quest "Lure of the Wildcat (San d\'Oria)" is active: Oh my, I thought a shooting star had crossed my vision for a moment there. I believe I just made a wish on your badge, madam. It comes from the Near East, you say? Such a captivating shine it has. I wonder if the stars in that nation burn as brightly as they do here? Perhaps I shall go and see for myself...' },
    ['Besieged/Besieged Allies'] = { zones = { 'Battle' } },
