    ['Bhoy Yhupplo'] = { type = 'Assault Mission Giver NPC: Ilrusi Atoll', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate L-9/10, in the Commisions Agency', note = 'Notes:\nOffers various Assault Missions for an I.D tag. Sells items for accumulated Assault points (stage-specific). Offers Assault Missions:: :*Golden Salvage Mercenary Rank PSC and above :*Lamia No.13 Mercenary Rank PFC and above :*Extermination Mercenary Rank SP and above :*Demolition Duty Mercenary Rank LC and above :*Searat Salvation Mercenary Rank C and above :*Apkallu Seizure Mercenary Rank S and above :*Lost and Found Mercenary Rank SM and above :*Deserter Mercenary Rank CS and above :*Desperately Seeking Cephalopods Mercenary Rank SL and above :*Bellerophon\'s Bliss Mercenary Rank FL' },
    ['Bhoyu Halpatacco'] = { zones = { 'Kazham' }, location = 'Kazham G-7', note = 'Notes:\nOutbound NPC to talk to for boarding the Kazham-Jeuno Airship.' },
    ['Bhukka Sahbeo'] = { zones = { 'Kazham' }, location = 'Kazham G-7', note = 'Notes:\n"You are like new seeds, carried in by the warrrm sea breeze. We hope that your dreams grrrow under our shining sun."' },
    ['Bibokk-Molbukk'] = { zones = { 'Tavnazian Safehold' }, location = 'Tavnazian Safehold H-8' },
    ['Big Harvest'] = { zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets H-6' },
    ['Big Harvest (A)'] = { zones = { 'Abyssea', 'Abyssea - Misareaux' }, location = 'Abyssea - Misareaux K-7' },
    ['Biggorf'] = { zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets H-10', note = 'Involved in Quests:\n* The Bare Bones' },
    ['Biggorf (A)'] = { zones = { 'Abyssea', 'Abyssea - Altepa' }, location = 'Abyssea - Altepa', note = 'Involved in Quests:\n* Slacking Subordinates' },
    ['Biggorf (S)'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) H-10', note = 'Involved in Quests:\n* Light in the Darkness\n* Quelling The Storm\n\nNotes:\n"The Galkan Bridge should be reopened immediately. I don\'t know what the president could be thinking. He claims to have roots in the miner\'s faction, but just what does he think of the Galka in the mining district? It is times like this when I wish that Talekeeper Raogrimm were still around to carry us through. It has been almost ten years since Raogrimm disappeared in the wintry cold of the north. We can only pray that he is still alive...somewhere."' },
    ['Bihoro-Guhoro'] = { zones = { 'Mhaura' }, location = 'Mhaura G-9', note = 'Involved in Quests:\n* Riding on the Clouds\n\nNotes:\nDescribed in Riding on the Clouds as, "A guy who knows a lot about pirates for somebody that\'s never met one."' },
    ['Bikho Ronpotteh'] = { type = 'Special Event NPC', zones = { 'Windurst', 'Windurst Waters (North)' }, location = 'Windurst Waters (North)', note = 'Notes:\nOne of The Dark Lilies of the Harvest Festival event held each October since 2004. Bikho\'s Story:: This...was a secret place... A place...that nobody knew... The purrrfect spot... An enchanted spot... So many fish... They would just jump.... onto the hook... To fill...my empty belly... To help..my strrruggling mother... I would fish...and fish...and fish... We were poor...I had no other choice... Even so...those days were fun... But I hated being poor... I delved...into forbidden magic... I\'m sorry...Mother... The day...I left home... I wanted...wanted to tell you...' },
    ['Bilp'] = { zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin E-8', note = 'Involved in Quests:\n* Scaredy-Cats' },
