    ['Boronene'] = { type = 'Residence Renter', zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst M-4', note = 'Notes:\n"This is the gateway to Windurst\'s residential ares. Inside, there are Mog Houses available for use by Windurst." *Ask for an explanation of Mog Houses. "A Mog House is you own personal apartment room, provided for you convenience. In you Mog House, you can carry out such activities as storing items, changing jobs, and healing HP and MP. Why don\'taru head up to your Mog House and rest your little body-wody?" *Nothing in particular. "Well then, bye-bye and ta-taru!"' },
    ['Bostillette'] = { zones = { 'Cutscene', 'San d\'Oria' }, note = 'Starts Quests:\n* Face of the Future' },
    ['Bottomless Gorge'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) F-8', note = 'Notes:\n"This is the Freidrich Battery. It bears the name of President Freidrich, our great leader during the First Battle of Konschtat. The battery has been reinforced with the finest Bastokan artillery to repel the siege of the beasthordes."' },
