    ['Brian'] = { type = 'Harvest Festival NPC (Dark Lilies subevent)', zones = { 'Bastok', 'Bastok Markets', 'Special Event' }, location = 'Bastok Markets G-9', note = 'Notes:\n* Begins the Dark Lilies subevent for the Harvest Festival.' },
    ['Bricorsant'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria H-8', note = 'Notes:\n* This NPC will display a map of San d\'Oria.' },
    ['Brifalien'] = { zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria H-8', note = 'Involved in Quests:\n* Riding on the Clouds\n\nNotes:\n*  Dialogue: Hey! Salute when you speak to me! I am second captain of the Royal Knights Youth Division! Don\'t make me use my nirvana slash on you! Maybe we could use you. You\'d be just a private...but there is plenty of opportunity for advancement. * Described in Riding on the Clouds as, "A second knight who specializes in the nirvana slash."' },
    ['Bright Moon'] = { type = 'Outpost Vendor', zones = { 'Cape Teriggan', 'Outland' }, location = 'Cape Teriggan G-8', note = 'Notes:\nAppears when Vollbow is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader\'s current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. :Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil' },
    ['Brita'] = { zones = { 'Bastok', 'Port Bastok' }, location = 'Port Bastok J-7' },
    ['Brugaire'] = { zones = { 'Cutscene', 'Cutscene Only', 'Outland' }, location = 'Cutscene Only', note = 'Involved in Quests:\n* Chasing Quotas (cutscene only)\n* Souls in Shadow (cutscene only)\n\nNotes:\nInvolved in various aspects of the shipping industry of Vana\'diel, including smuggling. Some dock workers and port laborers are known to be indebted to him to make weekly payments; to what end is unknown. Well respected by heads of each of the three nations, as well as in the far-off hidden port town of Norg. It\'s said, behind closed doors, that he is allowed to continue to run his many operations, both legit and shady, without any checks by city officials so long as he keeps things running \'smoothly\' in the ports keeping trade and transportation both efficient and safe.' },
    ['Brugaire (A)'] = { zones = { 'Abyssea', 'Abyssea - Grauberg' }, location = 'Abyssea - Grauberg L-6', note = 'Starts Quests:\n* Brugaire\'s Ambition' },
    ['Brujeel'] = { zones = { 'Al Zahbi', 'Mamool Ja Training Grounds' }, location = 'Mamool Ja Training Grounds', note = 'Involved in Missions:\n* Imperial Agent Rescue' },
