    ['Brutus'] = { type = 'Quest Giver NPC', zones = { 'Jeuno', 'Upper Jeuno Chocobo Stables' }, location = 'Upper Jeuno Chocobo Stables (G-7)', note = 'Starts Quests:\n* Chocobo on the Loose!\n* Chocobo\'s Wounds\n* Save My Son\n* Wings of Gold\n* Scattered into Shadow\n* Axe the Competition\n\nInvolved in Quests:\n* A Chocobo\'s Tale\n* The Flying Machine of Eld' },
