    ['Bubchu-Bibinchu, W.W.'] = { type = 'Conquest Overseer - Windurst Outpost Conquest Guard', zones = { 'Jugner Forest', 'Outland', 'Windurst' }, location = 'Jugner Forest I-8', note = 'Notes:\nAppears, when Norvallen is under weekly conquest-control by Windurst ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Norvallen Supplies for finishing Supply Quest :*Accepts Garrison starting item Jade Cryptex ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Bubupp'] = { zones = { 'Kazham' }, location = 'Kazham I-8', note = 'Involved in Quests:\n* The Opo-opo and I\n\nNotes:\n*  Accepts the Giant Fish Bones for The Opo-opo and I.' },
