    ['Calliope, I.M.'] = { type = 'Conquest Overseer', zones = { 'Bastok', 'The Sanctuary of Zi\'Tah' }, location = 'The Sanctuary of Zi\'Tah H-9', note = 'Notes:\nAppears, when Li\'Telor is under weekly conquest-control by Bastok ;Notes for characters only with Bastok as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts Li\'Telor Supplies for finishing Supply Quest :*Accepts Garrison starting item Hound Fang Sack ;Notes for characters only without Bastok as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Callisto'] = { location = '(F-6) Grauberg (S)(Fay Spring) * Unlike most Pixies, Callisto does not roam.', note = 'Involved in Quests:\n* Succor to the Sidhe' },
    ['Callort'] = { zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria I-8', note = 'Notes:\nDialogue: Airships fly between our kingdom and the Grand Duchy of Jeuno to the east. I\'ll never forget the first day I saw one of those ships fly... Jeuno\'s history is short, but quickly did that village of Hume fishermen grow into what it is today. When their archduke came to power, he excavated the ruins nearby. The knowledge they found there made them as mighty as San d\'Oria, by any reckoning. But once a fisherman, always a fisherman, I say. \'Tis the Elvaan of San d\'Oria that will rule Vana\'diel, mark my words!' },
    ['Callort (A)'] = { zones = { 'Abyssea', 'E-4 Abyssea - La Theine' }, location = 'E-4 Abyssea - La Theine' },
    ['Calovour'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria M-6, in main hall of the Cathedral', note = 'Involved in Quests:\n* Unexpected Treasure' },
    ['Camereine'] = { type = 'Chocobo Renter', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria I-11, in Chocobo Stables', note = 'Starts Quests:\n* A Chocobo Riding Game (San d\'Oria)\n\nNotes:\nYou can rent a Chocobo from this NPC. :*The higher your level, the higher the price. :*The more people that are renting Chocobos, the higher the price.', icon = 'ChocoboRenter.png' },
    ['Camille'] = { zones = { 'Jeuno', 'Wajaom Woodlands' }, location = 'Wajaom Woodlands M-7', note = 'Starts Quests:\n* Aht Urhgan Assault\n* Subterranean Skirmish\n\nNotes:\nProvides players with assistance with Voidwatch operations. *Ask a bunch of questions. *Participate in Voidwatch Ops. *Request debriefing. *Request Voidstone. *Check Voidstone stock. *Request reward issuance. - Can purchase the following: **Cobalt Cell: 3,000 Cruor **Rubicund Cell: 3,000 Cruor **Xanthous Cell: 3,000 Cruor **Periapt of Emergence: 50,000 Cruor **Periapt of Guidance: 150,000 Cruor **Periapt of Percipience: 150,000 Cruor **Periapt of Sapience: 50,000 Cruor **Periapt of Clarity: 50,000 Cruor **Beguiling Petrifact: 330,000 Cruor **Seductive Petrifact: 330,000 Cruor **Maddening Petrifact: 330,000 Cruor Can also convert any Voiddust into a Voidstone as long as the player has no Voidstones in their possession, currently.' },
