    ['Cardian Prototype'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Belfry', 'Windurst (S)' }, location = 'Belfry', note = 'Notes:\n* Spawned by an Allied Armored Belfry erected by the Federal Forces of Windurst. Participates in offensive Campaign Battles. A maximum of 5 reinforcements will appear, and they will continually respawn unless the belfry is demolished. *They will immediately charge to the Fortifications and attack any defenders they encounter.' },
