    ['Cauzeriste'] = { type = 'Guild Merchant (Woodworking)', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria E-3', note = 'Notes:\n:Open: Always :No longer closed on Firesday. :No longer shares stock with Chaupire.' },
    ['Cavalgrinne'] = { type = 'Auction House Representative', zones = { 'Rabao' }, location = 'Rabao K-7' },
    ['Cayu Pensharhumi'] = { zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods I-10', note = 'Involved in Quests:\n* Lure of the Wildcat (Windurst)\n\nNotes:\nDialog: Arrrgh... I\'m soo borrred! I wish something would happen to get my hot Mithran blood running again! How I envy adventurerrrs like you. What I\'d give to be able to head out into East Sarutabaruta and blow up some balloons forrr a bit of stress relief!' },
    ['Cecilia'] = { type = 'Event NPC', zones = { 'Northern San d\'Oria', 'Special Event' }, location = 'Northern San d\'Oria F-5 / Bastok Markets (G-8) / Windurst Waters North (F-9)', note = 'Notes:\nCecilia is the lead dancer of the Dancing Trio Cream Puff. She is capable of draining the life force of others through her dance moves, causing paralysis. left|thumb|Cecilia during the 2012 festival' },
    ['Ceciliotte'] = { type = 'Inventor\'s Coalition Reward Bayld Vendor NPC', zones = { 'Western Adoulin' }, location = 'Western Adoulin J-9' },
