    ['Chapa-Cha'] = { zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst L-4', note = 'Notes:\n"Beyond this gateway is the Windurst residential area, where you can stay in a Mog House or Rent-a-Room. If you need to hear an explanation, that\'s Boronene job. So pluck up the courage, and ask Boroene over there for all you need to knowy-wowy."' },
    ['Chapal-Afal, W.W.'] = { type = 'Conquest Overseer - Windurst Foreign Conquest Guard', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria H-9, in the Windurstian Consulate', note = 'Notes:\n;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts traded Crystals for filling up the Windurst Mission-Rank bar (the red bar at the character\'s profile) :*Sells items for Conquest Points (Items for Windurst) at certain conditions. It will be also possible to get some items of other Nations (Items for Bastok / Items for San d\'Oria) at the guards, if your current Allegiance ranks higher at the weekly Conquest results (for further information see under the items articles) :*Explains the Conquest system by choosing some available questions. ;Notes for characters only without Windurst as current Allegiance: :*Doesn\'t offer any function For further information see Conquest Overseer.' },
