    ['Charmealaut'] = { type = 'Special Event Coordinator NPC, Special Event Merchant NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria D-8 and (J-9)', note = 'Notes:\nThis NPC was a Smilemaker for the 2004 Starlight Celebration event Fellowship of the Red Hat, and then a Smilebringer for Starlight Celebration 2006 event. In 2004 he was located at (D-8); in 2006 he was located in (J-9).' },
