    ['Chatarre'] = { zones = { 'San d\'Oria', 'West Ronfaure' }, location = 'West Ronfaure H-5, in the Watchtower accessed through Northern San d\'Oria (C-7)' },
    ['Chatnachoq'] = { type = 'Moblin Maze Mongers NPC', zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno H-9', note = 'Notes:\n* Item exchange NPC for the Moblin Maze Mongers and Goldagrik\'s secretary. Players trade Moblin Marbles obtained through player mazes for additional Maze Tabulas, Maze Vouchers, Maze Runes, and even equipment. *Unwanted Maze Runes may be traded to Chatnachoq for 4-8 marbles.' },
