    ['Chefroucauld, T.K.'] = { type = 'Campaign NPC', zones = { 'Crawlers\' Nest (S)', 'San d\'Oria (S)' }, location = 'Crawlers\' Nest (S) K-8', note = 'Notes:\n* San d\'Oria affiliated Campaign Arbiter. Present when San d\'Oria (S) has control of Crawlers\' Nest (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Chegourt, R.K.'] = { type = 'Conquest Overseer', zones = { 'Meriphataud Mountains', 'San d\'Oria' }, location = 'Meriphataud Mountains E-5', note = 'Notes:\nAppears, when Aragoneu is under weekly conquest-control by San d\'Oria ;Notes for characters only with San d\'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Aragoneu Supplies for finishing Supply Quest :*Accepts Garrison starting item Thirteen-Knot Quipus ;Notes for characters only without San d\'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Cheh Raihah'] = { zones = { ':*In San d\'Oria: Southern San d\'Oria', 'Bastok', 'San d\'Oria', 'Windurst' }, location = ':*In San d\'Oria: Southern San d\'Oria (I-9) :*In Windurst: Windurst Woods (H-10) :*In Bastok: Port Bastok (K-8)', note = 'Notes:\nAppears in the capital city of the nation ranked first in conquest (does not show up when there is a tie for first)' },
