    ['Chemioue'] = { type = 'Quest Giver', zones = { 'Tavnazian Safehold' }, location = 'Tavnazian Safehold J-6, 3rd Floor', note = 'Starts Quests:\n* Petals for Parelbriaux\n\nInvolved in Quests:\n* In Search of the Truth\n* Knocking on Forbidden Doors\n\nNotes:\n* Two women and one shy man in love. Can this situation be solved? Who makes the first step? - Speak with Chemioue!' },
