    ['Chepelle'] = { zones = { 'Cutscene' }, location = 'Cutscene', note = 'Involved in Quests:\n* Hitting the Marquisate\n\nInvolved in Missions:\n* The Doll Whisperer (The Voracious Resurgence 2-5)\n\nNotes:\nMember of Atarefaunet\'s Band' },
    ['Cherlodeau'] = { zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria H-8', note = 'Involved in Quests:\n* Lure of the Wildcat (San d\'Oria)\n\nNotes:\nDialogue: If quest "Lure of the Wildcat (San d\'Oria)" is active: Hmph, thinking of becoming a mercenary, are you? Let me give you some advice: The beastmen of the Near East are far more savage than the fiends of Ronfaure. I would avoid those lands until I was sure of my strength. They care not who they kill--in that respect, they are much like the Orcs. In war, survival is key. Picking your battles in also a valid strategy. Artinien: That\'s called "Knowing your enemy," that is! Brifalien: Yeah! "Knowing your anemone!"' },
    ['Chero-Machero'] = { type = 'Mission NPC', zones = { 'Adoulin', 'Cutscene', 'Eastern Adoulin (Residence)' }, location = 'Eastern Adoulin (Residence)', note = 'Involved in Missions:\n* Meeting of the Minds\n* The Leafkin Monarch' },
    ['Cherukiki'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Tavnazian Safehold' }, note = 'Involved in Missions:\n* Promathia Mission 2-1: An Invitation West\n* Promathia Mission 2-2: The Lost City\n* Promathia Mission 2-3: Distant Beliefs\n* Promathia Mission 2-5: Ancient Vows\n* The Road Forks: The Road Forks\n* Promathia Mission 4-2: The Savage\n* Promathia Mission 5-2: Desires of Emptiness\n* Promathia Mission 5-3: Three Paths\n* Past Sins (Louverance Path)\n* Promathia Mission 6-2: A Place to Return\n* Promathia Mission 6-3: More Questions than Answers\n* Promathia Mission 6-4: One to be Feared\n* Promathia Mission 7-1: Chains and Bonds\n* Promathia Mission 7-3: Fire in the Eyes of Men\n* Promathia Mission 7-4: Calm Before the Storm\n* Promathia Mission 7-5: The Warrior\'s Path\n* Promathia Mission 8-1: The Garden of Antiquity\n* Promathia Mission 8-3: When Angels Fall\n* Promathia Mission 8-4: Dawn\n\nNotes:\nCherukiki is the youngest of the Chebukki siblings; you first meet them in the opening cutscene of Chapter 2 of the Chains of Promathia Missions.' },
