    ['Coderiant'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria F-8', note = 'Involved in Quests:\n* Lost Chick\n\nNotes:\nOffers Directions Around Town: :Are you lost? I know this neighborhood well. Which way are you going? :*"Left.": There on Pikeman\'s Way you can find a grocer, sundries and the Tanners\' Guild. At the end lies the mansion of Count Caffaule. :*"Right.": Go up those stairs for Watchdog Alley. Homes of townsfolk line the street.' },
    ['Coelestrox'] = { zones = { 'Reisenjima - Ethereal Ingress #10' }, location = 'Reisenjima - Ethereal Ingress #10', note = 'Starts Quests:\n* Reforged Artifact Armor +2\n* Reforged Artifact Armor +3\n\nNotes:\n* Only offers to upgrade Reforged Artifact Armor +1 to +2 if the player has participated at least once in Omen *Only offers to upgrade Reforged Artifact Armor +2 to +3 if the player has participated at least once in a 5th floor boss fight inside Omen *Ethereal Ingress #10 inside Reisenjima is only accessible after completing Rhapsodies of Vanadiel missions and receiving both {{KeyItem' },
