    ['Curilla'] = { type = 'Quest Giver NPC', zones = { 'Chateau d\'Oraguille', 'San d\'Oria' }, location = 'Chateau d\'Oraguille I-9 Temple Knight Qtrs', note = 'Starts Quests:\n* The General\'s Secret\n* Enveloped in Darkness\n* Peace for the Spirit\n* Old Wounds\n\nInvolved in Quests:\n* Lure of the Wildcat (San d\'Oria)\n* Trust: San d\'Oria\n\nInvolved in Missions:\n* Aht Urhgan Mission 5: Confessions of Royalty\n* The Heir to the Light\n\nNotes:\nCurilla V Mecru is the leader of the Temple Knights and bravest warrior within the military, and receives all the benefits of it - especially being a woman. The side of her face has been scarred due to an accident while sparring with Prince Trion. While understanding it wasn\'t on purpose, she still hides her face for shame and believing herself to be ugly. However, there is talk that a member of the royal family has seen past that, to her real beauty.' },
    ['Curilla (A)'] = { zones = { 'Abyssea', 'E-3 Abyssea - La Theine' }, location = 'E-3 Abyssea - La Theine', note = 'Starts Quests:\n* An Eye for Revenge' },
    ['Curio Vendor Moogle'] = { type = 'Rhapsodies of Vana\'diel Merchant', zones = { '*Port San d\'Oria' }, location = '*Port San d\'Oria J-9 *Port Bastok K-13 *Port Windurst M-4', note = 'Notes:\nAcquisition of permanent Rhapsody key items from Rhapsodies of Vana\'diel Missions increases the Curio Vendor Moogle\'s inventory.' },
    ['Curtis'] = { type = 'Promenade Assistant', zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit I-10, Eastern Promenade', note = 'Notes:\n* Sign players\' birds up for entry in Adventurer Races.' },
    ['Cynthia'] = { type = 'Cutscene NPC', zones = { 'Adoulin', 'Eastern Adoulin (Residence)' }, location = 'Eastern Adoulin (Residence)', note = 'Involved in Missions:\n* Balamor, the Deathborne Xol\n* Sugarcoated Salvation' },
    ['Cyphaireau'] = { type = 'Guide', zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit G-9, Bastok Area', note = 'Notes:\n* Guides (warps) player to different areas in the Chocobo Circuit.' },
    ['Cyranda'] = { type = 'Map Vendor', zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) G-10' },
    ['Cyranuce'] = { type = 'Cutscene', zones = { 'Cutscene', 'Ghelsba Outpost', 'San d\'Oria' }, location = 'Ghelsba Outpost', note = 'Involved in Quests:\n* The Holy Crest\n\nNotes:\n* A former member of the Young Griffons, Cyranuce was a close friend of Rahal. He was the first Elvaan to take up the arts of the Dragoon since Erpalacion. However according to rumours he has been confined within the Bostaunieux Oubliette.' },
    ['Cyranuce (S)'] = { type = 'Cutscene', zones = { 'Cutscene', 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S)', note = 'Starts Quests:\n* Bonds That Never Die\n\nInvolved in Quests:\n* Perils of the Griffon\n* In a Haze of Glory\n\nNotes:\n* A member of the Knights of the Swiftwing Griffons, Cyranuce is a friend of Rahal.' },
    ['Cyril'] = { type = 'Abyssea Support', zones = { 'Abyssea', 'Chocobo Circuit' }, location = 'Chocobo Circuit H-8', note = 'Notes:\n* Allows you to view your cruor balance. *Unlike most Abyssea teleporters, he is unable to relay the status of resistance in Scars of Abyssea areas. *Can teleport you to any Abyssean Cavernous Maw for 200 Cruor. **He only gives you the option to teleport to a maw if you have watched the cutscene and flagged the associated quest after examining it for the first time. Note that you must talk to Joachim after receiving the cutscene at your first Scars of Abyssea maw to receive cutscenes from examining the other maws; you will simply be allowed into the other zones without a cutscene nor teleport access from Horst. You must also be in possession of at least one Traverser Stone to receive a cutscene at its corresponding Cavernous Maw. |' },
    ['D. Shantotto'] = { type = 'Quest NPC', zones = { 'Windurst' }, note = 'Involved in Missions:\n* A Shantotto Ascension\n* Burgeoning Dread\n* That Which Curdles Blood\n* Sugar-coated Directive\n* Project: Shantottofication' },
