    ['Dabhuh'] = { type = 'Quest Giver', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate K-11 - on the lower level near "The Pit"', note = 'Starts Quests:\n* Such Sweet Sorrow' },
