    ['Dancing Thunder, L.C.'] = { type = 'Campaign NPC', zones = { 'Bastok (S)', 'Sauromugue Champaign (S)' }, location = 'Sauromugue Champaign (S) H-7', note = 'Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of Sauromugue Champaign (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Dancing Wolf'] = { zones = { 'Rabao' }, location = 'Rabao G-7', note = 'Involved in Missions:\n* Bastok Mission 9-1: The Salt of the Earth' },
    ['Dangueubert'] = { zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin H-11', note = 'Involved in Quests:\n* A Certain Substitute Patrolman' },
    ['Danngogg'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria K-10, in the Bastokan Consul' },
    ['Danngogg (A)'] = { zones = { 'Abyssea', 'E-4 Abyssea - La Theine' }, location = 'E-4 Abyssea - La Theine' },
    ['Dannion'] = { type = 'Quest NPC', zones = { 'Metalworks (?-?)' }, location = 'Metalworks (?-?)', note = 'Notes:\nAppears in Cut-Scene during a run at Bait and Switch when the Pocket watch is selected to begin the quest. Quotes: After triggering the first switch: "That Salim is a slave driver! I don\'t think I\'ll have a free moment for the rest of my life! He harrassed me somethings awful about setting up that trap in the temple of the goddess. It\'s not like anyone would find out, anyway! I think times like that prove he\'s a lot more cowardly than he tries to act!" After triggering the second switch: "Why do I have to search for some thief, anyway? I\'m a merchant, for cryin\' out loud! I think that guy just can\'t get his facts straight. He keeps asking me to do all these things that are completely unrelated to my job. Geesh..." After triggering the third switch: "Salim is asking for more gold again! He should think about other people for once. Anyway, if I don\'t hurry and meet today\'s quota, he\'ll string me up!" At this Point Dannion goes away for the time being, but returns once you have finished triggering all the switches and have hit the ??? in the Temple of the Goddess. "Whew, I met today\'s quota on time somehow. Salim should be happy with this. I can\'t go on like this everyday, though, especially with these inflated prices. Next time I\'ll try and talk to Salim about it."' },
    ['Dantie-Corantie'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Windurst', 'Windurst Waters South at the Rhinostery' }, location = 'Windurst Waters South at the Rhinostery', note = 'Involved in Quests:\n* Healing Herbs' },
