    ['Darumomo, W.W.'] = { type = 'Conquest Overseer', zones = { 'West Sarutabaruta', 'Windurst' }, location = 'West Sarutabaruta K-4', note = 'Notes:\nAppears, when Sarutabaruta is under weekly conquest-control by Windurst. ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Sarutabaruta Supplies for finishing Supply Quest ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Daruru, W.W.'] = { type = 'Conquest Overseer', zones = { 'Meriphataud Mountains', 'Windurst' }, location = 'Meriphataud Mountains F-12', note = 'Notes:\nAppears, when Aragoneu is under weekly conquest-control by Windurst. ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Aragoneu Supplies for finishing Supply Quest ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Darvylle'] = { zones = { 'Cutscene', 'San d\'Oria (S)' }, note = 'Involved in Quests:\n* Gifts of the Griffon\n* Wrath of the Griffon\n\nNotes:\nA member of the The Temple Knights.' },
    ['Daswil'] = { type = 'Assault Mamool Ja Training Grounds NPC', zones = { 'Al Zahbi', 'Mamool Ja Staging Point (Bhaflau Thickets' }, location = 'Mamool Ja Staging Point (Bhaflau Thickets H-10)', note = 'Starts Quests:\n* Beginnings\n\nInvolved in Missions:\n* Immortal Sentries\n\nNotes:\n* Speak with him to receive an Assault Armband for assault missions in Mamool Ja Training Grounds. Quote: "It\'s as I told you--mortals were meant to seek power." "But do not drown in its embrace" "Blue magic is the power of the beast within." "As mortals, we can only control a small portion of this strength." "If you forget this fact, and open the floodgates..." "Your very self will be washed away..." "Remember these words as the beast gnaws at your heart."' },
