    ['Doumina'] = { zones = { 'Chateau d\'Oraguille', 'San d\'Oria' }, location = 'Chateau d\'Oraguille H-8' },
    ['Dragatama'] = { zones = { 'Special Event', 'West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi\'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island / Xarcabard (roaming)' }, location = 'West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi\'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island / Xarcabard (roaming)', note = 'Notes:\nVery receptive to Shell Bugs.' },
    ['Drahbah'] = { type = 'Appraiser NPC', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate F-6', note = 'Notes:\n* Takes {{Gil Icon' },
