    ['Eleonore'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) H-9', note = 'Notes:\n"I\'m not quite sure why, but whenever I see a comet like that, it just puts a flutter in my chest."' },
    ['Elesca'] = { type = 'Map Vendor', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria I-8' },
    ['Elfriede'] = { zones = { 'Selbina' }, location = 'Selbina J-9', note = 'Involved in Quests:\n* The Tenshodo Showdown' },
    ['Elijah'] = { type = 'Adventurers\' Mutual Aid Network NPC', zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno G-6', note = 'Starts Quests:\n* Records of Eminence: RoE Quests 4\n\nNotes:\nSpeak with Elijah to unlock Peculiar Foes Records of Eminence objectives based on your progress in The Voracious Resurgence Missions. Players who have completed all Voracious Resurgence Missions may now receive five Voracious Psyches after completing all 15 Peculiar Foe Records of Eminence Objectives. This reward may be gained once every Monthly Version Update.' },
    ['Eliot'] = { type = 'Auction House Representative', zones = { 'Tavnazian Safehold' }, location = 'Tavnazian Safehold F-10 Middle-Floor', note = 'Notes:\n* Auction House services will not be available until after completing Darkness Named.' },
    ['Elivira'] = { type = 'Campaign Battle Ally NPC', zones = { 'Bastok (S)', 'Bastok Markets (S)', 'Battle' }, location = 'Bastok Markets (S) G-10', note = 'Notes:\n:*Gold Musketeer Captain of the Department of Mining during the Crystal War. :*Shares her unique face-type with Mythril Musketeer Captain Klara. :* Can appear in all Campaign Battles for Bastok (S) as the leader of the 1st Gold Musketeers. :* Uses Split Shot for 200+ damage, Slug Shot for 1200-1400 damage, Heavy Shot for 800+ damage, and the Relic Weapon Skill Coronach for 800-1100 damage. She Weapon Skills frequently, usually attempting to self-Skillchain. :* Talk: The Metalworks\' strategies are too timid for my taste. The beastmen are nothing but dominoes, waiting to be toppled. A swift, aggressive assault is the only way to victory. :* Battle Cry: A swift end is the only mercy you\'ll receive from me, fiends!' },
    ['Elivira Gogol'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) G-10', note = 'Notes:\n* Gold Musketeer Captain of the Department of Mining during the Crystal War. *Shares her unique face-type with Mythril Musketeer Captain Klara. "The Metalworks\' strategies are too timid for my taste. The beastmen are nothing but dominoes, waiting to be toppled. A swift, aggressive assault is the only way to victory."' },
    ['Elki'] = { type = 'Quest Giver', zones = { 'Bastok', 'Bastok Mines' }, location = 'Bastok Mines H-5', note = 'Involved in Quests:\n* Hearts of Mythril\n* The Eleventh\'s Hour' },
