    ['Elmric'] = { zones = { 'Adoulin', 'Ceizak Battlegrounds' }, location = 'Ceizak Battlegrounds K-7', note = 'Starts Quests:\n* Grind to Sawdust\n\nInvolved in Missions:\n* Evil Entities' },
    ['Elnonde'] = { zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) K-9', note = 'Involved in Quests:\n* Gifts of the Griffon' },
    ['Elpido-Copido'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Jeuno (S)', 'Windurst (S)' }, location = 'Jeuno (S)', note = 'Involved in Missions:\n* A Nation on the Brink (WOTG14)\n\nNotes:\n* Appers in cutscenes as the leader of the Cancerian War Warlocks, sent as reinforcements during the Battle of Jeuno. *The Cancerian and Geminian War Warlock units were able to get to Jeuno safety due to the diversionary force in the quest A Feast for Gnats.' },
    ['Else'] = { type = 'Campaign Battle Ally NPC', zones = { 'Bastok (S)', 'Bastok Markets (S)', 'Battle' }, location = 'Bastok Markets (S) E-11', note = 'Notes:\n:* Appears during Campaign Battles in Crawlers\' Nest (S) as the leader of the 1st Legion Reiters :* Can cast Cure IV, Paralyze II, Slow II, Bindga, Stone III, and Blizzard III. :* Uses Penta Thrust, Skewer, and Impulse Drive. :* Her attacks have additional Effect: Petrification. :* Uses Chainspell. :* Uses Oppresive Embrace :* Talk: Have you ever stopped to ponder what that comet might truly portend? I\'d like to believe it is a message of hope--that soon this age of darkness will come to a close... :* Battle Cry: This is your last chance. Throw down your weapons and your life will be spared. If you refuse...' },
    ['Elysia'] = { type = 'Quest Giver NPC', zones = { 'Tavnazian Safehold' }, location = 'Tavnazian Safehold G-10', note = 'Starts Quests:\n* Unforgiven' },
