    ['Emila'] = { zones = { 'Mhaura' }, location = 'Mhaura G-9', note = 'Involved in Quests:\n* Mhaura Fortune' },
    ['Emila, R.K.'] = { type = 'Conquest Overseer', zones = { 'San d\'Oria', 'Yhoator Jungle' }, location = 'Yhoator Jungle H-6', note = 'Notes:\nAppears, when Elshimo Uplands is under weekly conquest-control by San d\'Oria. ;Notes for characters only with San d\'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Elshimo Uplands Supplies for finishing Supply Quest ;Notes for characters only without San d\'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Emilia'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria I-10, in the Jeunoan Consul' },
    ['Emitt'] = { type = 'Conquest Overseer - Jeuno Conquest Guard', zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno F-5', note = 'Notes:\n;Notes for all characters: :*Casts Signet :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts traded Crystals for filling up the Mission-Rank bar of the character\'s appropriate Nation (the red bar at the character\'s profile) :*Sells items for Conquest Points of the character\'s appropriate Nation (Items for Bastok / Items for San d\'Oria / Items for Windurst) at certain conditions. It will be also possible to get some items of other Nations at the guards, if your current Allegiance ranks higher at the weekly Conquest results (for further information see under the items articles) :*Explains the Conquest system by choosing some available questions. For further information see Conquest Overseer.' },
    ['Emjook-Renook'] = { zones = { 'Adoulin', 'Yorcia Weald' }, location = 'Yorcia Weald J-8', note = 'Starts Quests:\n* The Secret to Success\n* Sick and Tired' },
