    ['Emmerich'] = { zones = { 'Bastok', 'Grauberg (S)' }, location = 'Grauberg (S) E-12' },
    ['Emoussine'] = { type = 'Chocobo Renter NPC', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria I-11, in Chocobo Stables', note = 'Starts Quests:\n* A Chocobo Riding Game (San d\'Oria)\n\nNotes:\nYou can rent a Chocobo from this NPC. :*The higher your level, the higher the price. :*The more people that are renting Chocobos, the higher the price.' },
    ['Emporox'] = { zones = { 'Reisenjima' }, location = 'Reisenjima', note = 'Notes:\nShe exchanges merits (up to 75 at a time) for an equal number of Potpourri currency. It costs 100 merits for her to open the shop to you. Sells various items for Potpourri. Items available depend upon which items you have given her that she wishes you to collect.' },
