    ['Erisa'] = { type = 'Cutscene NPC', zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin I-8 upon checking Door: Research Chamber at (J-8)', note = 'Starts Quests:\n* Keep Your Bloomers On, Erisa' },
    ['Erlene'] = { type = 'Quest Giver', zones = { 'Bastok (S)', 'The Eldieme Necropolis (S)' }, location = 'The Eldieme Necropolis (S) J-8 (via Batallia Downs (S) (J-10) entrance)', note = 'Starts Quests:\n* A Little Knowledge\n* On Sabbatical\n* Downward Helix\n* Seeing Blood-red\n\nNotes:\n* Professor Erlene is an instructor of the Schultz School of Martial Theory, serving on the Operations Staff at the Eldieme Necropolis during the war. *Speak to her as a level 5+ Scholar to learn Embrava and Kaustra.' },
    ['Erminold'] = { zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin J-10', note = 'Involved in Missions:\n* A Curse from the Past' },
    ['Ernestine'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)', 'Cutscene' }, location = 'Bastok Markets (S)', note = 'Involved in Quests:\n* Burden of Suspicion' },
    ['Ernst'] = { type = 'Abyssea Support', zones = { 'Abyssea', 'Port Bastok' }, location = 'Port Bastok K-11', note = 'Notes:\n* Allows you to view your cruor balance. *Informs you the status of the resistance in Scars of Abyssea areas. *Can teleport you to any Abyssean Cavernous Maw for 200 Cruor. **He only gives you the option to teleport to a maw if you have watched the cutscene and flagged the associated quest after examining it for the first time. Note that you must talk to Joachim after receiving the cutscene at your first Scars of Abyssea maw to receive cutscenes from examining the other maws; you will simply be allowed into the other zones without a cutscene nor teleport access from Horst. You must also be in possession of at least one Traverser Stone to receive a cutscene at its corresponding Cavernous Maw. |' },
    ['Eron-Tomaron'] = { type = 'Traveling Bard', zones = { 'Kazham' }, location = 'Kazham G-7', note = 'Notes:\n* Will change your Title for a fee or can give you a random title for free. *For a full list of titles, which you can get with this NPC, see Titles.' },
