    ['Erudite Moogle'] = { type = 'Event NPC', zones = { 'Cutscene', 'Outland', 'Southern San d\'Oria, Bastok Markets, Windurst Waters' }, location = 'Southern San d\'Oria, Bastok Markets, Windurst Waters', note = 'Starts Quests:\n* Adventurer Appreciation Campaign 2013' },
    ['Esca'] = { type = 'Quest NPC', zones = { 'West Ronfaure' }, location = 'West Ronfaure F-6', note = 'Involved in Quests:\n* The Pickpocket\n* Chasing Quotas\n\nNotes:\n* According to Professor Emanritan, this is a typical Elvaan name for a female.' },
    ['Esha\'ntarl'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Jeuno', 'Ru\'Lude Gardens' }, location = 'Ru\'Lude Gardens', note = 'Starts Quests:\n* Storms of Fate\n* Shadows of the Departed\n* Apocalypse Nigh\n\nInvolved in Missions:\n* Promathia Mission 2-5: Ancient Vows\n* Promathia Mission 3-2: Vessel Without a Captain\n* Promathia Mission 5-3: Three Paths\n* The Pursuit of Paradise (Tenzen\'s Path)\n* Promathia Mission 6-2: A Place to Return\n* Promathia Mission 6-3: More Questions than Answers\n* Promathia Mission 6-4: One to be Feared\n* Promathia Mission 7-2: Flames in the Darkness\n* Promathia Mission 8-4: Dawn\n\nNotes:\n* Zilart woman featured frequently in the Chains of Promathia Missions cutscenes. *Member of the Armathrwn Society.' },
    ['Esha\'ntarl (A)'] = { type = 'Cutscene NPC', zones = { 'Abyssea', 'Cutscene', 'Hall of the Gods (Cutscenes only)' }, location = 'Hall of the Gods (Cutscenes only)', note = 'Starts Quests:\n* Emissaries of God\n* Beneath a Blood-red Sky\n\nInvolved in Quests:\n* A Sea Dog\'s Summons\n* Death and Rebirth\n* Meanwhile, Back on Abyssea' },
    ['Esmallegue'] = { zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria I-11', note = 'Notes:\nOffers Information on San d\'Oria\'s Military: Greetings, adventurer. San d\'Oria is grateful for your services. I am Royal Squire Esmallegue. Grand Knight Depardal has left his post as sentry in the Outlands. For now he has been enlisted as a member of the city\'s defense force. As I\'m sure you are already aware, San d\'Oria\'s military is divided into two branches, the Royal Knights and the Temple Knights. In times of peace, we Royal Knights are charged with the defense of the nation, while the Temple Knights are responsible for maintaining the public order. However, in times of war the Temple Knights are given the role of supervising our ranks. Unfortunately, this is a source of some conflict. Despite being united under one kingdom, there is a strong sense of rivalry between the two armies. It has been said that during the Great War there were many areas of contention between us. If you have not yet entered a Cavernous Maw you will first get the following dialogue: You there, adventurer! I wonder have you heard of the so-called "Cavernous Maws"? I don\'t know if it\'s true or not, but some say that it was the wicked rituals of Orcish mesmerizers on the stones that caused them to assume that wretched form.' },
