    ['Explorer Moogle'] = { type = 'Event NPC', zones = { '*Ru\'Lude Gardens', 'Jeuno' }, location = '*Ru\'Lude Gardens H-9 *Bastok Mines K-8 *Northern San d\'Oria L-10 *Port Windurst L-4 *Selbina H-7 *Mhaura H-8', note = 'Notes:\n* The Explorer Moogle in Ru\'Lude Gardens provides information on Mog Tablets, including a list of those that have been recovered, as well as currently active "Super Kupowers." *Explorer Moogles in Bastok, Windurst, San d\'Oria, Selbina, and Mhaura are only present when Thrifty Transit is in effect. *The Explorer Moogle in Ru\'Lude Gardens does not teleport players, even during Thrifty Transit. *You must be level 20 or higher to warp.' },
    ['Eya Bhithroh'] = { type = 'Weather Reporter', zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst M-7 Behind the left counter inside the departures entrance for the Air Travel Agency', note = 'Notes:\nChecks weather for the following locations: :* East Sarutabaruta :* West Sarutabaruta :* Tahrongi Canyon :* Buburimu Peninsula :* Meriphataud Mountains' },
