    ['Fablinix'] = { type = 'Event NPC', zones = { 'Outland', 'Special Event' }, note = 'Notes:\nFablinix or "Fab" is a Goblin whose diaries are chronicled in A Little Goblin\'s Adventure. He appears in many Special Events, but rarely serves a major role.' },
