    ['Falzum'] = { type = 'Cutscene', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi', 'Cutscene' }, location = 'Aht Urhgan Whitegate', note = 'Involved in Quests:\n* Promotion: Lance Corporal\n* Promotion: Second Lieutenant\n* Promotion: First Lieutenant\n\nInvolved in Missions:\n* Aht Urhgan Mission 4: Knight of Gold\n* Aht Urhgan Mission 22: Shield of Diplomacy\n\nNotes:\n* A fearful and somewhat inept mercenary employed at Salaheem\'s Sentinels.' },
    ['Falzuuk'] = { type = 'Imperial Gate Guard', zones = { 'Al Zahbi' }, location = 'Al Zahbi G-6', note = 'Notes:\n:*Casts Sanction on registered mercenaries (w/ Sanction Enhancements) :*Recharges Chariot Band, Emperor Band, or Empress Band. :*Sells items for Imperial Standing at appropriate rank. :*Explains Sanction, Imperial Standing, and Besieged system by choosing some available questions.' },
    ['Famad'] = { type = 'Assault Mission Giver NPC: Lebros Cavern', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate L-9/10, in the Commisions Agency', note = 'Notes:\nOffers various Assault Missions for an I.D tag. Sells items for accumulated Assault points (stage-specific). Offers Assault Missions:: :*Excavation Duty Mercenary Rank PSC and above :*Lebros Supplies Mercenary Rank PFC and above :*Troll Fugitives Mercenary Rank SP and above :*Evade and Escape Mercenary Rank LC and above :*Siegemaster Assassination Mercenary Rank C and above :*Apkallu Breeding Mercenary Rank S and above :*Wamoura Farm Raid Mercenary Rank SM and above :*Egg Conservation Mercenary Rank CS and above :*Operation: Black Pearl Mercenary Rank SL and above :*Better Than One Mercenary Rank FL' },
    ['Famatar'] = { type = 'Imperial Gate Guard', zones = { 'Al Zahbi' }, location = 'Al Zahbi F-7', note = 'Notes:\n:*Casts Sanction on registered mercenaries (w/ Sanction Enhancements) :*Recharges Chariot Band, Emperor Band, or Empress Band. :*Sells items for Imperial Standing at appropriate rank. :*Explains Sanction, Imperial Standing, and Besieged system by choosing some available questions.' },
    ['Fandango'] = { type = 'Event NPC', zones = { 'Special Event', 'Windurst Walls' }, location = 'Windurst Walls H-10' },
    ['Fantarviont'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria F-7', note = 'Notes:\n"In the war twenty years ago, San d\'Orian knights crushed the Shadow Lord and his hordes. We sealed off the Northlands from whence he came. "Eh? Windurst and Bastok? They could barely protect their gates! If it weren\'t for the valor of our knights, all would have fallen into shadow!"' },
    ['Fardimant X Boncourge'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Phomiuna Aqueducts', 'Tavnazian Safehold' }, location = 'Phomiuna Aqueducts', note = 'Involved in Quests:\n* Knocking on Forbidden Doors\n\nNotes:\nThere is some discrepancy in this NPC\'s biographical data between the Japanese version and all other versions. The Japanese dialogue for the quest "Knocking on Forbidden Doors" refers to him by first name only, and he is referred to by first name only in the zone object name files. Furthermore, the Japanese dialogue says that he has been in the aqueducts for twenty years, while the English dialogue says that it is over two hundred! The latter is probably a translation error, since Chemioue mentions Fardimant retired there after the Great War.' },
    ['Fariel'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks I-8' },
    ['Fariel (A)'] = { type = 'Quest NPC', zones = { 'Abyssea', 'Abyssea - Misareaux' }, location = 'Abyssea - Misareaux G-8', note = 'Involved in Quests:\n* Missing in Action' },
    ['Fariska Lokhmi'] = { type = 'Map Marker', zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin G-9 (Just outside the Scouts\' Coalition)', note = 'Notes:\nMarks one\'s town map with the locations of various NPCs important to adventures: *Home Points *Item Depository *Melody Mistrels *Weather Reporters *Traveling Bards *Reputation *Immigration *Armor Depository *Teleportation *Pursuivant *Gold World Pass Vendor In addition to Eastern and Western Adoulin NPCs, she will also mark Bivouac waypoints you\'ve activated in: *Ceizak Battlegrounds *Yahse Hunting Grounds *Foret de Hennetiel *Morimar Basalt Fields' },
    ['Fari-Wari'] = { type = 'Quest Giver', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate K-12', note = 'Starts Quests:\n* Saga of the Skyserpent\n* Ode to the Serpents\n* Soothing Waters\n* Embers of His Past\n\nNotes:\n* Tarutaru bard found near the Shararat Teahouse counter.' },
    ['Farmaoquaix'] = { type = 'Special Event Coordinator NPC', zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria G-6', note = 'Notes:\nAppeared during the 2004 Starlight Celebration event.' },
    ['Farouel'] = { zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) K-7', note = 'Involved in Missions:\n* WOTG21: Proof of Valor' },
    ['Farso-Dafarso'] = { zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin G-8', note = 'Notes:\n*  For 10 bayld, he casts Quickening at +12% Movement Speed, or +25% if the Couriers\' Coalition possesses the Signboard edification. It will overwrite Flee and Quickening obtained from other methods. Movement effect stacks with gear, but not Mazurka. Wears off if the player: ** Changes job or subjob. ** Uses Flee or any item, enchantment, or ability that also gives Quickening (e.g. Sprinter\'s Shoes, Chocobo Jig). ** Zones anywhere but Western Adoulin, Eastern Adoulin, the Adoulin Rent-a-Room, and Mog Garden. Warp, Waypoints, and Home Point warps are fine so long as it\'s within the city. *** Only verified with Rala Waterways, Ceizak Battlegrounds, and Bastok Mines HP2. It\'s possible but unlikely a glitch or oversight might allow other locations{{Verification' },
    ['Fatimah'] = { type = 'Recipe Giver', zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets H-8' },
    ['Fauceille'] = { zones = { 'Sauromugue Champaign (S)' }, location = 'Sauromugue Champaign (S) F-6' },
    ['Faulpie'] = { type = 'Leathercraft Guild Master NPC', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria E-8', note = 'Involved in Quests:\n* An Understanding Overlord?\n\nInvolved in Missions:\n* That Which Curdles Blood\n\nNotes:\nThis NPC will: :*Sign you up for the Leathercraft Guild :*Accept the items you need to turn in, to go up in rank for the Leathercraft Guild.' },
    ['Faurbellant'] = { type = 'Quest NPC', zones = { 'La Theine Plateau', 'San d\'Oria' }, location = 'La Theine Plateau K-8', note = 'Involved in Quests:\n* Gates to Paradise\n\nNotes:\n* Located at the east wall of the Crag of Holla, in between the two prongs.' },
    ['Faurie'] = { zones = { 'Chateau d\'Oraguille', 'San d\'Oria' }, location = 'Chateau d\'Oraguille I-9' },
    ['Faursel'] = { type = 'Quest Giver NPC', zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno J-8, Inside Neptune\'s Spire', note = 'Starts Quests:\n* The Road to Aht Urhgan' },
    ['Faustin'] = { type = 'Regional Vendor', zones = { 'Bastok', 'Bastok Mines' }, location = 'Bastok Mines J-9' },
    ['Fayeewah'] = { type = 'Standard Merchant', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate K-12, in Shararat Teahouse' },
    ['Fearless Fismar'] = { type = 'Cutscene NPC', zones = { 'Adoulin', 'Cutscene', 'Rala Waterways' }, location = 'Rala Waterways', note = 'Involved in Quests:\n* Raptor Rapture\n\nNotes:\nAfter completing Raptor Rapture, it\'s possible to watch Fearless Fismar, Tenacious Tirrod, and Vicious Vorahal fight in the Rala Waterways arena.' },
    ['Feathered Foe'] = { zones = { 'Everbloom Hollow' }, location = 'Everbloom Hollow', note = 'Notes:\n* Multiple varieties of birds will appear over time and roam the area during Aquatic Depopulation Team. (Birds and Rocs) *Will consume any fish you have in your possession if you stray too close to them before disappearing.' },
    ['Febrenard C Brunnaut'] = { zones = { 'Battle', 'San d\'Oria (S)', 'Southern San d\'Oria (S) or The Eldieme Necropolis (S)' }, location = 'Southern San d\'Oria (S) or The Eldieme Necropolis (S)', note = 'Notes:\n* Appears in campaign battles, as commander of the Temple Knights. *Spams Holy and Banish III when engaged in battle. *Possesses an innate and powerful Enlight effect on his melee attacks. *Uses various Sword weaponskills, and Shield Bash which does very high damage. **Febrenard seems to favor using Shining Blade and Seraph Blade. *Battle Cry: Altana! Let your divine light guide us to victory! *Casts Protectra V and Shellra V on himself, which will carry over to nearby players. *Casts Cure V on himself.' },
    ['Federation Dispenser'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Varies', 'Windurst (S)' }, location = 'Varies', note = 'Notes:\n* Appears during an offensive campaign against Beastman territories. Up to 3 dispensers may be present at a time. *Distributes temporary items to players allied with Windurst in the battle. *Upon the depletion of their stock, these distributors will temporarily return to headquarters in order to replenish their stores. *They will take defensive action against aggressors, but during that time they will be unable to dispense items. Should they become incapacitated in the course of battle, a replacement will be dispatched after a certain amount of time has elapsed. *Item availability and quantity is directly influenced by each nation\'s skill and production levels.' },
    ['Federation Garrison'] = { type = 'Battle NPC', zones = { 'Battle', 'Ghoyu\'s Reverie', 'Windurst' }, location = 'Ghoyu\'s Reverie', note = 'Involved in Missions:\n* Granite Rose I (Windurst)\n* Granite Rose II (Windurst)' },
    ['Federation Infantry'] = { type = 'Battle NPC', zones = { 'Battle', 'Ghoyu\'s Reverie', 'Windurst' }, location = 'Ghoyu\'s Reverie', note = 'Involved in Missions:\n* Brave Dawn I (Windurst)\n* Brave Dawn II (Windurst)\n\nNotes:\n* Weapon changes depending on mission, but always has /WHM and casts Cure III on self.' },
    ['Fekko-Krakko'] = { zones = { 'Fort Karugo-Narugo (S)' }, location = 'Fort Karugo-Narugo (S) K-6' },
    ['Feldrautte I Rouhent'] = { zones = { 'Battle', 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) B-7', note = 'Notes:\nAppears during Campaign Battles as the leader of the Norvallen Knights. Appears to be a Staff-wielding Paladin/Monk, as he has been seen using Counterstance. *Talk: "The kingdom\'s defeat at Jugner still stings. To avenge the souls of those lost on that fateful day, we must join hands and take up arms as one." *Feldrautte has extremely high HP and attack strength. *Feldrautte often counters enemy hits with his own. *Uses Counterstance to increase his counter rate. *Casts Protect IV, Shell IV and Cure IV. *Uses Invincible *Often uses the weaponskill Full Swing, dealing extreme damage. Does use other weaponskills. *Battle Cry: "For the king!"' },
    ['Felicia, C.A.'] = { type = 'Campaign NPC', zones = { 'Vunkerl Inlet (S)' }, location = 'Vunkerl Inlet (S) H-10', note = 'Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of Vunkerl Inlet (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Felicific Buffalo'] = { type = 'Event NPC', zones = { 'North Gustaberg, South Gustaberg, East Ronfaure, West Ronfaure, East Sarutabaruta, West Sarutabaruta', 'Special Event' }, location = 'North Gustaberg, South Gustaberg, East Ronfaure, West Ronfaure, East Sarutabaruta, West Sarutabaruta', note = 'Notes:\nA buffalo found roaming in the areas outside of all three starting cities which is followed by two to three Rancher NPCs. Rancher NPCs mention the opening of the Buffalo Bonanza Ranch in Jeuno.' },
