    ['Ferchinne'] = { type = 'Quest Starter NPC', zones = { 'Tavnazian Safehold', 'Tavnazian Safehold (First Floor' }, location = 'Tavnazian Safehold (First Floor G-9)', note = 'Starts Quests:\n* Fly High' },
