    ['Flige'] = { type = 'Chocobo Circuit Grandstand Attendant', zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit G-11 Al Zahbi box seating', note = 'Notes:\n* Will allow adventures back into the main circuit complex from the grandstand area.' },
    ['Flit'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Various cutscenes, the Ashu Talif' }, location = 'Various cutscenes, the Ashu Talif', note = 'Involved in Missions:\n* Aht Urhgan Mission 15: The Black Coffin\n* Aht Urhgan Mission 22: Shield of Diplomacy\n* Aht Urhgan Mission 29: Puppet in Peril\n* Aht Urhgan Mission 30: Prevalence of Pirates\n* Aht Urhgan Mission 35: Legacy of the Lost\n* Aht Urhgan Mission 36: Gaze of the Saboteur\n* Aht Urhgan Mission 37: Path of Blood\n* The Battle of Xarcabard\n\nNotes:\n* A crafty imp in the employ of Prince Luzaf. *At the side of the Shadow Lord during the Crystal War.' },
