    ['Fouagine'] = { zones = { '3rd floor in Tavnazian Safehold at', 'Tavnazian Safehold' }, location = '3rd floor in Tavnazian Safehold at (I-8)', note = 'Involved in Quests:\n* In Search of the Truth' },
    ['Foudeel'] = { zones = { 'Al Zahbi', 'Cutscene' }, note = 'Involved in Quests:\n* Give Peace a Chance\n* Three Men and a Closet\n\nNotes:\n* Friends with Bashraf and Wahboud; the three are seen during the Three Men and a Closet quest cutscenes. *Appears during the Sunbreeze Festival event Fantastic Fraulein Mumor 2010 to heckle Mumor and Uka. *If you are raising a chocobo, starting at the adolescent stage you will meet them on a walk in Tahrongi Canyon, La Theine Plateau, or Konschtat Highlands where they are raising a chocobo together. They will challenge you to a friendly competition. *There is a chance he will jockey for their chocobo during official races. If he does, Sakura, translated through Markovich, comments, "It\'s rumored that Foudeel often spends weeks planning out strategies for each of his two-minute races."' },
    ['Foulneporde'] = { type = 'Chocobo Circuit Grandstand Attendant', zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit J-8, Al\'Zahbi Area', note = 'Notes:\n* For either 50 gil, or a Chocobo Circuit grandstand pass, he will allow you into the grandstands to view the current race.' },
