    ['Fourth Spitewarden'] = { zones = { 'Cutscene', 'Throne Room (S), Walk of Echoes' }, location = 'Throne Room (S), Walk of Echoes', note = 'Involved in Missions:\n* Darkness Descends\n* When Wills Collide\n\nNotes:\nBears the appearance of your character. This is your character in Lady Lilith\'s future.' },
    ['Fouvia'] = { type = 'Wyvern Name Changer', zones = { 'Norg' }, location = 'Norg F-7', note = 'Notes:\nSpeaking with her with your main job set as Dragoon you get the option to change your Wyvern\'s name for 9800 gil. For a complete list of names see Dragoon Wyvern.' },
    ['Framaraix, T.K.'] = { type = 'Campaign NPC', zones = { 'La Vaule (S)', 'San d\'Oria (S)' }, location = 'La Vaule (S)', note = 'Notes:\n* San d\'Oria affiliated Campaign Arbiter. Present when San d\'Oria has control of La Vaule (S) *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Francmage'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'San d\'Oria', 'Various cutscenes' }, location = 'Various cutscenes', note = 'Involved in Quests:\n* Signed in Blood\n* Tea with a Tonberry?\n\nInvolved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n\nNotes:\nBefore the outbreak of the Crystal War, Francmage was the head of the Knights Mistalle, a noble San d\'Orian family who owned the territory within Carpenters\' Landing. He was sent along with Mythril Musketeers Ulrich, Raogrimm and Cornelia to investigate the northlands in cooperation with Yow Rabntah and Iru-Kuiru of Windurst.' },
    ['Franziska'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks K-8, behind President\'s Office', note = 'Involved in Quests:\n* Bastok Mission 7-2: On My Way\n\nNotes:\n* Talking to NPC is the same as checking Cornelia\'s room. She will trigger a brief cutscene showing Cornelia running out on her studies. *If you complete the quests Beauty and the Galka, Fallen Comrades, and Rivals, and have completed On My Way, it will trigger the cutscene titled "Cornelia\'s Plea." This will only occur once.' },
    ['Fremilla'] = { type = 'Cutscene NPC', zones = { 'Adoulin', 'Castle Adoulin', 'Cutscene' }, location = 'Castle Adoulin', note = 'Involved in Missions:\n* August\'s Heirloom\n* Wildcat with a Gold Pelt' },
