    ['Fridolin'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) E-8', note = 'Notes:\nWill allow those who originally aligned to Bastok\'s campaign and later switched to other nations\' campaign to return to Bastok for a price of 300 AN and the two highest campaign medals. Recompleting The Fighting Fourth is not required, or even possible.' },
