    ['Geruru, W.W.'] = { type = 'Conquest Overseer - Windurst Outland Conquest Guard', zones = { 'Jugner Forest', 'Outland', 'Windurst' }, location = 'Jugner Forest L-5', note = 'Notes:\nAppears, when Norvallen is under weekly conquest-control by Windurst ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Norvallen Supplies for finishing Supply Quest ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Gerwitz'] = { zones = { 'La Theine Plateau', 'Outland' }, location = 'La Theine Plateau', note = 'Involved in Quests:\n* Dark Puppet\n\nNotes:\nA Bastokan blacksmith in life, Gerwitz now haunts Ordelle\'s Caves as a ghost. He can be met in La Theine Plateau at the end of the quest Dark Puppet.' },
