    ['Ghebi Damomohe'] = { type = 'Standard Merchant', zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno I-7, In Neptune\'s Spire', note = 'Starts Quests:\n* Tenshodo Membership\n* Chips\n\nInvolved in Missions:\n* Promathia Mission 3-5: Darkness Named\n\nNotes:\n*  Tenshodo member. * Always open. *Item pricing is based on Norg/Tenshodo reputation, rather than Jeuno reputation. * Provides key items needed for the following ENM\'s: ** Test Your Mite' },
    ['Ghemi Sinterilo'] = { type = 'Standard Merchant', zones = { 'Kazham' }, location = 'Kazham G-7', note = 'Notes:\n* Ghemi is on the dock, on the same side as the Airship. Note: she may be spoken to from the walkway below, thus avoiding the 200 gil Airship Fee. Sells:: *Pamamas 72 - 83 *Kazham Pineapple 54 - 62 *Mithran Tomato 36 - 41 *Kazham Peppers 54 - 62 *Cinnamon 236 - 270 *Kukuru Bean 109 - 124 *Elshimo Coconut 156 - 158 *Elshimo Pachira Fruit 154 - 166 *Kazham Waystone 9,100 - 9,200 *Aquilaria Log - 2,877' },
    ['Ghemp'] = { type = 'Guild Master', zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks E-7', note = 'Notes:\n:*Signs you up for the Smithing Guild :*Accepts the items you need to turn in, to go up in rank for the Smithing Guild.' },
