    ['Ghyo Molkot'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Windurst (S)' }, note = 'Involved in Quests:\n* The Tigress Stirs\n* The Tigress Strikes\n* A Manifest Problem\n* Manifest Destiny\n* At Journey\'s End\n\nNotes:\nAppears during cutscenes as the leader of the Olzhiryan Volunteer Army...Mithra aka "Terrible Tigresses" of the Mithra Mercenaries during the Crystal War.' },
    ['Giancario'] = { type = 'Chocobobet Center Clerk', zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit J-8, Al Zahbi Area', note = 'Notes:\n* Takes bets for the chocobo races.' },
    ['Giaunne'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria I-9', note = 'Involved in Quests:\n* Lure of the Wildcat (San d\'Oria)\n\nNotes:\nDialogue: You\'ve been to the cathedral, have you not? Did you not find it magnificent? All things are touched by the light of judgment. Ah, but it is hard to express faith in something so crude as words. If quest "Lure of the Wildcat (San d\'Oria)" is active: Such blasphemy in our Goddess-blessed nation... Is that not a symbol of those heathens? The people of Aht Urhgan put their faith in false gods. You should be ashamed of yourself.' },
