    ['Gordias'] = { zones = { 'Windurst', 'Windurst Waters map = North|F-9' }, location = 'Windurst Waters map = North|F-9', note = 'Notes:\nDialog: "Ahhh, I\'m sooo full! I just ate ten servings! Hahaha... Are you impressed? Well, that there resturant sells only Tarutaru-sized servings. Ten servings is quite an easy amount to stomach."' },
