    ['Grumblix'] = { type = 'Past Event Watcher NPC', zones = { 'Cutscene', 'Outland', 'See Goblin Footprint' }, location = 'See Goblin Footprint', note = 'Notes:\nIf you come across a Goblin Footprint in the depths of Promyvion, you may hear voices. If so, you can trade any item to the Footprint to have Grumblix will appear and replay cutscenes for you. Any items traded (for example, 1 gil), will not be lost.' },
