    ['Guddal, I.M.'] = { type = 'Conquest Overseer', zones = { 'Bastok', 'Yhoator Jungle' }, location = 'Yhoator Jungle H-6', note = 'Notes:\nAppears, when Elshimo Uplands is under weekly conquest-control by Bastok. ;Notes for characters only with Bastok as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts Elshimo Uplands Supplies for finishing Supply Quest ;Notes for characters only without Bastok as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Gueriette'] = { type = 'Outpost Vendor', zones = { 'Beaucedine Glacier', 'Outland' }, location = 'Beaucedine Glacier H-9', note = 'Notes:\nAppears when Fauregandi is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader\'s current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil' },
    ['Guhyun'] = { zones = { 'Nashmau' }, location = 'Nashmau H-8 - 2nd Floor' },
    ['Guilberdrier'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria F-3', note = 'Involved in Quests:\n* Flyers for Regine\n* Exit the Gambler' },
    ['Guilberien'] = { type = 'Mission NPC', zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin J-4 (Cutscene)', note = 'Involved in Missions:\n* Melvien de Malecroix' },
    ['Guilboire'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria D-7', note = 'Notes:\nthumb|100px|MonstersOffers Information on Monster Relationships: :Hrmm... Good eyes, friend. I thought my presence unknown, but you found me. You are fortunate... For my knowledge of the enemy, culled from many years on the battlefield, can be yours. Look at the tattered diagram? :*"Yes.": Good. Curiosity is a virtue! Look at my diagram, and listen well, for I shall say this but once. This is the law of relations: Beasts bare their fangs at dim-witted lizards, while the lizards must turn to the vapid vermin for their sup. The multitude of vermin crop plantoids close to the ground, while the long-lived plantoids draw nourishment from the corpses of beasts with their roots. Birds that wing the skies carry aquans to their graves, while water-wise aquans suck the shapeless form of amorphs dry. The silent, shapless amorphs slip into the nests of birds and feed on their feathery brood. And this is the law of oppositions: The cursed undead shun the pseudo-life of the arcana, while the arcana avoid the undead. The immortal dragons shun the death-bringing demons, while the demon spellweavers avoid dragons, against whom their magic is useless. All of this is different from the regular divisions of life, based upon my own experience and observation. Sharpen your senses, and watch your enemies closely. Soon a world of understanding will open before you. :*"No.": "Know they enemy, know thyself. A hundred battles, a hundred victories." A great general of antiquity spoke these words.' },
    ['Guilboire (A)'] = { zones = { 'Abyssea', 'Abyssea - Uleguerand Third Outpost' }, location = 'Abyssea - Uleguerand Third Outpost', note = 'Starts Quests:\n* Frozen Flame Redux' },
