    ['Guilloud'] = { zones = { 'Carpenters\' Landing', 'San d\'Oria' }, location = 'Carpenters\' Landing H-10, Near the waters edge', note = 'Involved in Missions:\n* The Road Forks: The Road Forks' },
    ['Guinavie'] = { type = 'Chocobo Renter', zones = { 'Rabao' }, location = 'Rabao G-10', icon = 'ChocoboRenter.png' },
    ['Gulemont'] = { type = 'Quest Giver NPC', zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria G-7, in the Rusty Anchor Pub', note = 'Starts Quests:\n* The Dismayed Customer\n\nNotes:\nDialogue: It\'s been twenty years since the Great War, and the king is old. His little princes have grown into men, now... Yet I hear they bicker over which will be king. A sadder fate has never befell a kingdom, if it\'s true. Who knows? And they were such good brothers in their youth.' },
    ['Gulemont (A)'] = { type = 'Reputation NPC', zones = { 'Abyssea', 'Abyssea - Vunkerl' }, location = 'Abyssea - Vunkerl F-4' },
    ['Gulldago'] = { type = 'Tutorial NPC', zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets D-11', note = 'Notes:\n* Provides tutorial information for newly created characters. *See Tutorial NPC for more information about the 7 mini quests.' },
    ['Gulmama'] = { type = 'Quest Giver NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria E-7', note = 'Starts Quests:\n* Trial by Ice\n\nInvolved in Quests:\n* SMN AF2: Class Reunion' },
    ['Gulool Ja Ja'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Mamook' }, location = 'Mamook', note = 'Involved in Missions:\n* Aht Urhgan Mission 29: Puppet in Peril\n\nNotes:\nThe double-headed "Autarch" of Mamook. He/they will participate in raids on Al Zahbi for the Astral Candescence.' },
    ['Gumbah'] = { type = 'Quest Giver', zones = { 'Bastok', 'Bastok Mines' }, location = 'Bastok Mines J-7 - Inside a house on the upper walkway, in the back room', note = 'Starts Quests:\n* Blade of Darkness\n* Blade of Death\n* Inheritance\n\nInvolved in Quests:\n* Rivals\n* The Eleventh\'s Hour\n\nInvolved in Missions:\n* Bastok Mission 6-1: Return of the Talekeeper\n* Bastok Mission 7-1: The Final Image\n* Bastok Mission 7-2: On My Way\n* Bastok Mission 8-2: Enter the Talekeeper\n* Bastok Mission 9-1: The Salt of the Earth\n* Bastok Mission 9-2: Where Two Paths Converge\n* The Voracious Resurgence #1: The Gloom Phantom\'s Approach\n* The Voracious Resurgence #2: The Brygid Cup\n\nNotes:\nA young Galka who is a resident of Bastok Mines. He is concerned about his friend, the Galkan elder Werei, who has apparently set off upon his Journey of Rebirth. He plays a major role in some of the more advanced Bastok Missions. He is also the catalyst for several Dark Knight related quests.' },
    ['Gumbah (S)'] = { type = 'Cutscene NPC', zones = { 'Bastok (S)', 'Bastok Markets (S)', 'Cutscene' }, location = 'Bastok Markets (S)', note = 'Involved in Quests:\n* Fires of Discontent\n* Light in the Darkness\n* Storm on the Horizon\n* Fire in the Hole\n\nNotes:\n* Loyal friend and battle companion to Galkan elder Werei.' },
    ['Gurdern'] = { zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno G-10', note = 'Involved in Quests:\n* Lure of the Wildcat (Jeuno)' },
    ['Gurdern (A)'] = { zones = { 'Abyssea', 'Abyssea - Attohwa' }, location = 'Abyssea - Attohwa H-8' },
    ['Gurfurlur the Menacing'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Halvung' }, location = 'Halvung', note = 'Involved in Missions:\n* Aht Urhgan Mission 22: Shield of Diplomacy\n\nNotes:\nThe leader of the Troll Mercenaries, employed by the Moblin magnate Megomak. He will participate in raids on Al Zahbi for the Astral Candescence.' },
    ['Gurren-Murren'] = { type = 'Quest giver NPC', zones = { 'Adoulin' }, note = 'Starts Quests:\n* Twitherym Dust' },
    ['Guruna-Maguruna'] = { type = 'Standard Merchant', zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst H-9' },
    ['Gushing Spring'] = { zones = { 'Rabao' }, location = 'Rabao G-8', note = 'Starts Quests:\n* VW Op. #101: Detour to Zepwell\n\nNotes:\nProvides players with assistance with Voidwatch operations similar to those employed by Jeuno. *Ask a bunch of questions. *Participate in Voidwatch Ops. *Request debriefing. *Request Voidstone. *Check Voidstone stock. *Request reward issuance. - Can purchase the following: **Cobalt Cell: 3,000 Cruor **Rubicund Cell: 3,000 Cruor **Xanthous Cell: 3,000 Cruor **Periapt of Emergence: 50,000 Cruor **Periapt of Guidance: 150,000 Cruor **Periapt of Percipience: 150,000 Cruor **Periapt of Sapience: 50,000 Cruor **Periapt of Clarity: 50,000 Cruor Can also convert any given Voiddust into a Voidstone granted that the player have no Voidstones on them currently.' },
    ['Guslam'] = { type = 'Quest Giver NPC', zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno H-8 [Durable Shields shop]', note = 'Starts Quests:\n* Borghertz\'s Sorcerous Hands: (BLM AF Hands)\'\n* Borghertz\'s Harmonious Hands: (BRD AF Hands)\n* Borghertz\'s Wild Hands: (BST AF Hands)\n* Borghertz\'s Dragon Hands: (DRG AF Hands)\n* Borghertz\'s Shadowy Hands: (DRK AF Hands)\n* Borghertz\'s Striking Hands: (MNK AF Hands)\n* Borghertz\'s Lurking Hands: (NIN AF Hands)\n* Borghertz\'s Stalwart Hands: (PLD AF Hands)\n* Borghertz\'s Vermillion Hands: (RDM AF Hands)\n* Borghertz\'s Chasing Hands: (RNG AF Hands)\n* Borghertz\'s Loyal Hands: (SAM AF Hands)\n* Borghertz\'s Calling Hands: (SMN AF Hands)\n* Borghertz\'s Sneaky Hands: (THF AF Hands)\n* Borghertz\'s Warring Hands: (WAR AF Hands)\n* Borghertz\'s Healing Hands: (WHM AF Hands)' },
    ['Gustavo'] = { type = 'Promenade Assistant', zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit I-10, Eastern Promenade', note = 'Notes:\n* Sign players\' birds up for entry in Adventurer Races.' },
    ['Guttrix'] = { type = 'Quest Giver NPC', zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno H-10', note = 'Starts Quests:\n* The Goblin Tailor' },
    ['Guwanana'] = { zones = { 'Windurst', 'Windurst Waters (South)' }, location = 'Windurst Waters (South)', note = 'Notes:\nOne of The Dark Lilies of the Harvest Festival event, held each October since 2004. Guwanana\'s Story:: Glimmer...shimmer... Shimmer...glimmer... Little fishies... Shimmering fishy-wishes... Where have you all gone...? Little fishies... Glimmering fishy-wishies... Are you here...? You mustaru be hiding... Here and there... The fishy-wishies I let free... Shimmering... glimmering...fish... But...I don\'taru see you...? Where have you gone...? The same as before... Nowhere to be found... But wait... That shimmer-glimmering... The Flash spell fused into your scaly-wales... Glimmer...shimmer... So many little fishy-wishies... You survived...' },
    ['Gu\'Zho Thunderblade'] = { type = 'Quest Starter', zones = { 'Cutscene', 'Oldton Movalpolos' }, location = 'Oldton Movalpolos E-13 - Cutscenes only', note = 'Involved in Quests:\n* A Generous General?\n\nNotes:\n* Shieldwarrior Gu\'Zho Thunderblade could not accept the leadership of the Adamantking and deserted the Quadav. Now he searches for a new job as a mercenary for the Moblins of Movalpolos.' },
