    ['Haih Ahmpagako'] = { zones = { 'Kazham' }, location = 'Kazham G-8' },
    ['Haja Zhwan'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) F-5', note = 'Involved in Quests:\n* When One Man Is Not Enough\n\nNotes:\n* Appears during Campaign Battles as the leader of the Wildcat Volunteers. *Taking part in Campaign Battles, Haja Zhwan will frequently be found in differing locations. While not out by Campaign Fortifications, she will be found in Windurst Waters (S) by the entrance. *Uses both Detonator and her signature Bloody Quarrel weaponskill. * Talk: If only the Parliament of Patriarchs would loosen the strings on their purses a little more, I would be outside right now roasting up a couple birdmen to snack on! * Battle Cry: Time to go to work!' },
    ['Hajaom'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate J-10 Under the arch.', note = 'Involved in Quests:\n* Got It All' },
    ['Hajawaa'] = { type = 'Armor Depository', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate H-8', note = 'Notes:\nStores lvl 24-60 AF, Relic, RSE and other gearsets.' },
    ['Hakaru-Marikaru'] = { zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods G-10', note = 'Notes:\nDialog: Elvaan are all so high and haughty. It almost seems like they look down at us Tarutaru at times. Huh...? How dare you say that\'s because we are so short that everyone can\'t help but look down at us! Beat it before I bite your kneecaps!' },
