    ['Haubijoux'] = { zones = { 'Jeuno', 'Port Jeuno' }, location = 'Port Jeuno H-7' },
    ['Haudrale'] = { type = 'Cutscene NPC', zones = { 'Cutscene' }, note = 'Involved in Missions:\n* WOTG07: Purple, The New Black\n* WOTG08: In the Name of the Father\n* WOTG09: Dancers in Distress\n* WOTG15: Crossroads of Time\n* WOTG19: Betrayal at Beaucedine\n* WOTG25: The Will of the World\n* WOTG26: Fate in Haze\n* WOTG37: Darkness Descends\n\nNotes:\nOne of the Spitewardens of Lady Lilith, the commander of the "Knights of the Rustwing Hawk" appears to be an elvaan fomor. He does not get along with Aquila.' },
    ['Hauh Colphioh'] = { type = 'Clothcraft Guildworker\'s Union NPC', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods G-12', note = 'Notes:\nHauh Colphioh is in charge of the Guildworker\'s Union for clothcrafting in Windurst. Once you have attained at least level 28 Cloftcraft you may speak with her, and begin accumulating Guild Points for items you turn in. The item requested changes daily, so its important to check back with her to keep track of current time limits, and to find out what new items the guild is accepting.' },
