    ['Heavy Bear, I.M.'] = { type = 'Conquest Overseer - Bastok Outland Conquest Guard', zones = { 'Bastok', 'Outland', 'Xarcabard' }, location = 'Xarcabard F-7', note = 'Notes:\nAppears, when Valdeaunia is under weekly conquest-control by Bastok ;Notes for characters only with Bastok as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts Valdeaunia Supplies for finishing Supply Quest ;Notes for characters only without Bastok as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
