    ['Helbort'] = { type = 'Quest Giver NPC', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria K-7, in Helbort\'s Blades', note = 'Starts Quests:\n* A Purchase of Arms' },
    ['Helga'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks I-8 - Top Level', note = 'Notes:\nOffers Information on The Republican Military: Greetings, adventurer. I am Gold Musketeer first captain, Helga. Would you like me to give you a simple brefing on the Republican Military? Yes.> The Republican military is comprised of two groups: the Republican Legion and the Musketeers. the legionary forces are formed from volunteers and draftees, and are divided into four different organizations. It is these organizations that handle the responsibility of defending our nation from invasion. The Musketeers are an elite group of officers hand-selected from legion ranks. As with the legion, this group is also divided into several smaller units. Of those units, the two most prominent would be the Iron Musketeers, who answer directly to the Department of Industry, and the Gold Musketeers, who take their orders from the Department of Mining. No.> Ah, I suppose you are already and expert on the subject. My apologies.' },
    ['Helga (A)'] = { zones = { 'Abyssea', 'Abyssea - Konschtat' }, location = 'Abyssea - Konschtat' },
    ['Helina'] = { type = 'Empyrean Armor NPC', zones = { 'Selbina' }, location = 'Selbina H-9|Inside the Weaver\'s Guild', note = 'Involved in Quests:\n* Treasures of the Earth\n\nNotes:\n* You can commission Geomancer Empyrean Armor from Helina by talking to her on Geomancer after completing the quest Treasures of the Earth. *You can choose the order in which you receive the armor. *Speak to her after the game day changes to exchange the received {{KeyItem' },
    ['Helmfried'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) L-9', note = 'Notes:\n"Before the onset of war, President Prien ralled the strong support of the Galkan citizenry. That was the key to his winning the election. But it seems his campaign promises of improving living standards have been complicated by the outbreak of hostilities."' },
    ['Helmut'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks F-8', note = 'Involved in Quests:\n* Bait and Switch' },
    ['Helmyre'] = { type = 'Chocobo Renter', zones = { 'Jugner Forest (S)', 'Outland' }, location = 'Jugner Forest (S) H-9', note = 'Notes:\n* Must be level 20, have a Chocobo License,and be affiliated with one of the armies of the three nations to be eligible to rent a Chocobo. *Rental fees will be charged in Allied Notes rather than gil.', icon = 'ChocoboRenter.png' },
