    ['Herald'] = { type = 'Ballista/Brenner Referee', zones = { '*Jugner Forest', 'Outland' }, location = '*Jugner Forest (I-8) *Meriphataud Mountains (G-7) *Pashhow Marshlands (I-7) *Diorama Abdhaljs-Ghelsba *Abdhaljs Isle-Purgonorgo (H-7)', note = 'Notes:\nThe Herald controls the match settings and admissions into Ballista and Brenner.' },
