    ['High Wind'] = { zones = { 'Jeuno', 'Ru\'Lude Gardens' }, location = 'Ru\'Lude Gardens H-6, Palace, Second Floor', note = 'Involved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n\nNotes:\nA Ducal Guard responsible for guarding the Archduke\'s Audience Chamber. High Wind is a surname in the Final Fantasy series as well as the name of the Airship in Final Fantasy VII.' },
