    ['Hugo'] = { type = 'Map Marker', zones = { 'Aht Urhgan Whitegate, across from the Mog House entrance', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate, across from the Mog House entrance', note = 'Notes:\nMarks one\'s town map with the locations of various NPCs important to adventures: *Home Points *Item Depository *Melody Minstrels *Weather Reporters *Traveling Bards *Reputation *Immigration *Armor Depository *Teleportation *Pursuivant *Gold World Pass Vendor *Because of the transient nature of NPCs within the Besieged zone, Hugo will only mark NPCs in Aht Urhgan Whitegate.' },
