    ['Ildy-Goldy'] = { zones = { 'Cutscene', 'Windurst' }, note = 'Involved in Quests:\n* Tuning Out\n* SMN AF1: The Puppet Master\n* SMN AF2: Class Reunion\n* SMN AF3: Carbuncle Debacle' },
    ['Ilgusin'] = { zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria G-7, Rusty Anchor Pub', note = 'Notes:\nAye, \'tis true that San d\'Oria joined Windurst, Bastok, and Jeuno in war twenty years ago. We slew the Shadow Lord, and drove back his hordes! I say "we," but what did the absent-minded Windurstians and granite-licking Bastokers do? Nothing! And don\'t get me started on those upstart fisherman from Jeuno! Our knights triumphed against darkness that day. San d\'Oria saved this world from the clutches of the Shadow Lord! Soon, our great kingdom will bring peace to this land! Fight with me, my brothers, until that glorious day has come!' },
    ['Ilieumort, R.K.'] = { type = 'Conquest Overseer', zones = { 'San d\'Oria', 'Yhoator Jungle' }, location = 'Yhoator Jungle I-8', note = 'Notes:\nAppears, when Elshimo Uplands is under weekly conquest-control by San d\'Oria. ;Notes for characters only with San d\'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Elshimo Uplands Supplies for finishing Supply Quest :*Accepts Garrison starting item Coeurl Leather Missive ;Notes for characters only without San d\'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
