    ['Inthius'] = { type = 'Weather Reporter', zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin F-9', note = 'Notes:\nChecks weather for the following locations: :*Ceizak Battlegrounds :*Yahse Hunting Grounds :*Foret de Hennetiel :*Morimar Basalt Fields :*Yorcia Weald :*Marjami Ravine :*Kamihr Drifts' },
    ['Invincible Shield'] = { type = 'Conflict Director', zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks G-8, Outside Cid\'s Lab', note = 'Involved in Quests:\n* Lure of the Wildcat (Bastok)\n* Getting a Ballista License\n\nNotes:\n* A renowned Bastokan hero due to his rank of Legatus of the 3rd Division during the Crystal War. *Is in charge of Ballista concerns for the Republic and will give you a Ballista Earring (Key Item)' },
    ['Invincible Shield (S)'] = { type = 'Campaign Battle Ally NPC', zones = { 'Bastok (S)', 'Bastok Markets (S)', 'Battle' }, location = 'Bastok Markets (S) G-4', note = 'Involved in Missions:\n* Affairs of State\n\nNotes:\n:*Holds the title of 3rd Division\'s Legatus which makes him Commander in Chief of the 3rd Division/Legion of the Republican Army. :* Appears during Campaign Battles in North Gustaberg (S) and Bastok Markets (S) as the leader of the 3rd Legionnaire squadron. :* Uses Raging Axe for 600-1000 damage, Spinning Axe for 200-1300 damage, Rampage for 900-2600 damage, Decimation for 700-1700 damage, and his own unique slightly-ranged slightly-AoE Weapon Skill called Napalm Tomahawk for 200-1500 damage. :* Napalm Tomahawk can make Light skillchain with Fragmentation weaponskills (Shark Bite, Savage Blade, etc) :* Uses Mighty Strikes (can use more than once) and Warcry (every couple minutes). :* Talk: Halt! If you\'re not one of the Fourth, then get your sorry tail over to the recruitment office on the double! And if you are one of us, then what the hell are you doing here talking to me!? Get back on the battlefield! About...FACE! :* Battle Cry: I never liked fighting on land... Now give me a well armed battleship on the open sea, and I\'ll have those turtlebacks running for their lives! :* For some reason, it seems difficult/impossible to see Invincible Shield\'s damage against enemy leaders.' },
    ['Ioupie, R.K.'] = { type = 'Conquest Overseer', zones = { 'Outland', 'Pashhow Marshlands' }, location = 'Pashhow Marshlands K-4', note = 'Notes:\nAppears, when Derfland is under weekly conquest-control by San d\'Oria. ;Notes for characters only with San d\'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Derfland Supplies for finishing Supply Quest ;Notes for characters only without San d\'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Iphaaf'] = { zones = { 'Al Zahbi' }, location = 'Al Zahbi H-7' },
    ['Ipupu'] = { zones = { 'West Sarutabaruta (I/J-8) - Tower Lobby', 'Windurst' }, location = 'West Sarutabaruta (I/J-8) - Tower Lobby', note = 'Involved in Quests:\n* Glyph Hanger' },
    ['Irate Destrier'] = { zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin G-8', note = 'Involved in Quests:\n* The Longest Way Round...' },
    ['Irmilant'] = { zones = { 'Rabao' }, location = 'Rabao G-7', note = 'Starts Quests:\n* The Immortal Lu Shang\n* Indomitable Spirit\n* Fish Favors the Bold' },
    ['Iroha'] = { type = 'Mission NPC', zones = { 'Battle', 'Cutscene', 'Far East' }, note = 'Involved in Missions:\n* Rhapsodies of Vana\'diel Missions\n\nNotes:\n* Wields powerful fire magic such as Flare II. *She is the future 14-year-old daughter of Tenzen and Kagero. *She eventually becomes the host for the reincarnated Phoenix.' },
    ['Iron Eater'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks J-8, outside the President\'s Office', note = 'Starts Quests:\n* The Weight of Your Limits\n\nInvolved in Quests:\n* Fires of Discontent\n* The Doorman\n* Waking the Colossus\n\nInvolved in Missions:\n* Bastok Mission 2-2: Wading Beasts\n* Bastok Mission 3-1: The Four Musketeers\n* Bastok Mission 5-1: Darkness Rising\n* Bastok Mission 6-1: Return of the Talekeeper\n* Bastok Mission 8-1: The Chains that Bind Us\n* Bastok Mission 8-2: Enter the Talekeeper\n* Bastok Mission 9-1: The Salt of the Earth\n* Bastok Mission 9-2: Where Two Paths Converge\n\nNotes:\n* He is a member of the The Mythril Musketeers and holds the rank of "Number Three." Iron Eater is his Hume-given name; his actual name is Pagdako. He plays a major role in Bastok Missions.' },
    ['Iron Eater (A)'] = { zones = { 'Abyssea', 'Abyssea - Misareaux, Base Camp' }, location = 'Abyssea - Misareaux, Base Camp', note = 'Starts Quests:\n* Missing in Action' },
    ['Iron Muscles'] = { zones = { 'Rabao' }, location = 'Rabao F-6' },
    ['Iron Ram Knight'] = { zones = { 'Battle', 'Everbloom Hollow', 'San d\'Oria (S)' }, location = 'Everbloom Hollow', note = 'Involved in Missions:\n* A Nation on the Brink (WOTG14)\n\nNotes:\n* Fights alongside Rongelouts N Distaud during the mission A Nation on the Brink.' },
    ['Ironclad Gorilla'] = { zones = { 'Tavnazian Safehold' }, location = 'Tavnazian Safehold H-8' },
    ['Iruki-Waraki'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate K-9 upstairs - Way of the Devout', note = 'Involved in Quests:\n* No Strings Attached\n* The Wayward Automaton\n* Operation Teatime\n* Puppetmaster Blues' },
    ['Iru-Kuiru'] = { zones = { 'Cut Scenes Only', 'Cutscene', 'Windurst' }, location = 'Cut Scenes Only', note = 'Involved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n\nNotes:\nBefore the outbreak of the Crystal War, Iru-Kuiru was one of the ministers for the Rhinostery, along with Yow Rabntah. They were sent along with Mythril Musketeers Ulrich, Raogrimm, and Cornelia to investigate the northlands in cooperation with Francmage of San d\'Oria. Some time after returning from the expedition he was mysteriously murdered.' },
    ['Irwyn'] = { zones = { 'Cutscenes', 'Jeuno' }, location = 'Cutscenes', note = 'Involved in Missions:\n* Borne by the Wind' },
    ['Isabella'] = { type = 'Survey NPC', zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) E-8', note = 'Notes:\n* Supply Commander of the Fourth Division\'s Seventh Cohors. *Allows Bastok affiliated players to vote on future campaign tactics. "600 loaves of iron bread...check. 15,000 copper bullets...check. Ah-- I am sorry, soldier, but my hands are tied at the moment. Could you return at a later date?"' },
    ['Isacio'] = { zones = { 'Selbina' }, location = 'Selbina G-10', note = 'Involved in Quests:\n* Elder Memories' },
    ['Isakoth'] = { type = 'Records of Eminence NPC', zones = { 'Bastok Markets', 'Jeuno' }, location = 'Bastok Markets E-11', note = 'Starts Quests:\n* Records of Eminence\n\nInvolved in Quests:\n* Records of Eminence: Tutorial\n* Teleports by Twilight\n\nNotes:\nSee Sparks of Eminence for a list of items, weapons, and armor available for purchase.' },
    ['Isanie'] = { zones = { 'Windurst Waters map=North|E-9' }, location = 'Windurst Waters map=North|E-9', note = 'Involved in Quests:\n* Escutcheons' },
    ['Isdebaaq'] = { type = 'Assault Mission Giver NPC: Mamool Ja Training Grounds', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate L-9/10, in the Commisions Agency', note = 'Notes:\nOffers various Assault Missions for an I.D tag. Sells items for accumulated Assault points (stage-specific). Offers Assault Missions:: :*Imperial Agent Rescue Mercenary Rank PSC and above :*Preemptive Strike Mercenary Rank PFC and above :*Sagelord Elimination Mercenary Rank SP and above :*Breaking Morale Mercenary Rank LC and above :*The Double Agent Mercenary Rank C and above :*Imperial Treasure Retrieval Mercenary Rank S and above :*Blitzkrieg Mercenary Rank SM and above :*Marids in the Mist Mercenary Rank CS and above :*Azure Ailments Mercenary Rank SL and above :*The Susanoo Shuffle Mercenary Rank FL' },
    ['Ishin, I.M.'] = { type = 'Conquest Overseer', zones = { 'Bastok', 'Buburimu Peninsula' }, location = 'Buburimu Peninsula E-7', note = 'Notes:\nAppears, when Kolshushu is under weekly conquest-control by Bastok. ;Notes for characters only with Bastok as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts Kolshushu Supplies for finishing Supply Quest :*Accepts Garrison starting item Mithra Fang Sack ;Notes for characters only without Bastok as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Ishvad'] = { type = 'Standard Merchant', zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin I-5 Waterfront', note = 'Notes:\n* Prices for the items sold by this NPCare not affected by Fame level. *Prices for the items sold by this NPCare reduced by Alliance Shirt +1.' },
    ['Ishwar'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria H-10, in Jeunoan Consul' },
    ['Ismenios Cutsilver'] = { zones = { 'Bastok', 'Cutscene', 'Cutscene Only' }, location = 'Cutscene Only', note = 'Involved in Quests:\n* Chasing Dreams\n* The Search for Goldmane\n* A Chocobo\'s Tale\n\nNotes:\nDeceased partner of Goldmane. Died in the capture of Atarefaunet. Son of Praefactus Leonnel of the Bastokan Navy.' },
    ['Istvan'] = { type = 'ENM Quest Timer Checker NPC', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods K-11', note = 'Notes:\n* Provides information on ENM battlefield lockout.' },
    ['Itzha Delavhitta'] = { zones = { 'Mhaura' }, location = 'Mhaura H-9' },
    ['Ivan'] = { type = 'Abyssea Support', zones = { 'Abyssea', 'Port San d\'Oria' }, location = 'Port San d\'Oria I-8', note = 'Notes:\n* Allows you to view your cruor balance. *Informs you the status of the resistance in Scars of Abyssea areas. *Can teleport you to any Abyssean Cavernous Maw for 200 Cruor. **He only gives you the option to teleport to a maw if you have watched the cutscene and flagged the associated quest after examining it for the first time. Note that you must talk to Joachim after receiving the cutscene at your first Scars of Abyssea maw to receive cutscenes from examining the other maws; you will simply be allowed into the other zones without a cutscene nor teleport access from Horst. You must also be in possession of at least one Traverser Stone to receive a cutscene at its corresponding Cavernous Maw. |' },
    ['Ivoh Haalameb'] = { type = 'Melody Minstrel', zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin D-9' },
    ['Iya Rihyo'] = { zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods G-9', note = 'Notes:\nCounts a a child for Starlight Celebration 2008 Dialog: Those automation guards called Cardians are said to grrrow smarter and smarter by the day as they learrrn more and more. It\'s only a matter of time until they all start developing their own perrrsonalities and then begin to fight among themselves. Won\'t that be fun?' },
    ['Iyvah Halohm'] = { type = 'Reputation NPC', zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin G-8' },
    ['Izabele'] = { type = 'Quest Giver', zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks G-8', note = 'Starts Quests:\n* The Gustaberg Tour' },
    ['Izabele (A)'] = { type = 'Reputation NPC', zones = { 'Abyssea', 'Abyssea - Misareaux' }, location = 'Abyssea - Misareaux K-7' },
    ['Jabbar'] = { type = 'Tenshodo Merchant', zones = { 'Bastok', 'Port Bastok' }, location = 'Port Bastok F-6 Warehouse 2 (Bastok)', note = 'Involved in Quests:\n* Tenshodo Membership\n\nNotes:\n* Open: 1:00 - 23:00 *No longer closed on Iceday. *Must be a member of the Tenshodo to buy from this merchant.' },
    ['Jabbos'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Mine Shaft #2716' }, location = 'Mine Shaft #2716', note = 'Involved in Quests:\n* A Question of Faith\n\nInvolved in Missions:\n* Promathia Mission 5-3: Three Paths\n* Past Sins (Louverance Path)\n* Promathia Mission 6-1: For Whom the Verse is Sung\n* Promathia Mission 6-4: One to be Feared\n* Promathia Mission 7-1: Chains and Bonds\n* Promathia Mission 7-2: Flames in the Darkness\n* Promathia Mission 7-3: Fire in the Eyes of Men\n* Promathia Mission 7-5: The Warrior\'s Path\n* Promathia Mission 8-1: Garden of Antiquity\n* Promathia Mission 8-2: A Fate Decided\n* Promathia Mission 8-3: When Angels Fall\n* Promathia Mission 8-4: Dawn\n\nNotes:\n* A Galka who has been living with the Moblins for a century.' },
    ['Jack of Clubs'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'Port Windurst (D,E-6)(Near Orastery entrance)', 'Windurst' }, location = 'Port Windurst (D,E-6)(Near Orastery entrance)', note = 'Notes:\nOffers General Information and a Map of Windurst: :Allow me to assist you if you are lost. What can Jack do for you? :*"To show you a map of Windurst.": [Displays an overview map of Windurst] :*"How to give items to townsfolk.": Interchange of items and money between people and things is called "Trading." First target entity to interact with. Nothing happens unless receiver is properly targeted. Open main menu. Press "Trade" button. Next choose items to hand over! Press "Confirm" button! Targeted entity should receive items. :*"How to go outside and battle.": Before setting out to battle: Confirm equipment is properly equipped! Magic-users "Use" spell scrolls on themselves to learn magic! Before commencing battle with monster: "Check" monster to confirm its strength! After battle is won: Look for "Spoils" dropped by monsters. If in party, "Cast Lots" for spoils! :*"About quests and missions.": Quests are requests for help from ordinary townsfolk. It pays to help people in need. Missions are official requests for assistance made by the Windurst authorities. You can receive missions from the guards at the town\'s gatehouse. :*"Nothing in particular.": Feel free to ask next time you need Jack\'s help. Over and out!' },
    ['Jack of Diamonds'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'Windurst', 'Windurst Walls' }, location = 'Windurst Walls C-13', note = 'Notes:\nOffers General Information and a Map of Windurst: :Allow me to assist you if you are lost. What can Jack do for you? :*"To show you a map of Windurst.": [Displays an overview map of Windurst] :*"How to give items to townsfolk.": Interchange of items and money between people and things is called "Trading." First target entity to interact with. Nothing happens unless reciever is properly targeted. Open main menu. Press "Trade" button. Next choose items to hand over! Press "Confirm" button! Targeted entity should receive items. :*"How to go outside and battle.": Before setting out to battle: Confirm equipment is properly equipped! Magic-users "Use" spell scrolls on themselves to learn magic! Before commencing battle wiht monster: "Check" monster to confirm its strength! After battle is won: Look for "Spoils" dropped by monsters. If in party, "Cast Lots" for spoils! :*"About quests and missions.": Quests are requests for help from ordinary townsfolk. It pays to help people in need. Missions are official requests for assistance made by the Windurst authorities. You can receive missions from the guards at the town\'s gatehouse. :*"Nothing in particular.": Feel free to ask next time you need Jack\'s help. Over and out!' },
    ['Jack of Hearts'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'Windurst', 'Windurst Waters map = North|G-9' }, location = 'Windurst Waters map = North|G-9', note = 'Notes:\nOffers General Information and a Map of Windurst: :Allow me to assist you if you are lost. What can Jack do for you? :*"To show you a map of Windurst.": [Displays an overview map of Windurst] :*"How to give items to townsfolk.": Interchange of items and money between people and things is called "Trading." First target entity to interact with. Nothing happens unless reciever is properly targeted. Open main menu. Press "Trade" button. Next choose items to hand over! Press "Confirm" button! Targeted entity should receive items. :*"How to go outside and battle.": Before setting out to battle: Confirm equipment is properly equipped! Magic-users "Use" spell scrolls on themselves to learn magic! Before commencing battle wiht monster: "Check" monster to confirm its strength! After battle is won: Look for "Spoils" dropped by monsters. If in party, "Cast Lots" for spoils! :*"About quests and missions.": Quests are requests for help from ordinary townsfolk. It pays to help people in need. Missions are official requests for assistance made by the Windurst authorities. You can receive missions from the guards at the town\'s gatehouse. :*"Nothing in particular.": Feel free to ask next time you need Jack\'s help. Over and out!' },
    ['Jack of Spades'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods H-10', note = 'Notes:\nCan be traded Adventurer Coupon for those starting in Windurst Woods. Offers General Information and a Map of Windurst: :Allow me to assist you if you are lost. What can Jack do for you? :*"To show you a map of Windurst.": [Displays an overview map of Windurst] :*"How to give items to townsfolk.": Interchange of items and money between people and things is called "Trading." First target entity to interact with. Nothing happens unless reciever is properly targeted. Open main menu. Press "Trade" button. Next choose items to hand over! Press "Confirm" button! Targeted entity should receive items. :*"How to go outside and battle.": Before setting out to battle: Confirm equipment is properly equipped! Magic-users "Use" spell scrolls on themselves to learn magic! Before commencing battle wiht monster: "Check" monster to confirm its strength! After battle is won: Look for "Spoils" dropped by monsters. If in party, "Cast Lots" for spoils! :*"About quests and missions.": Quests are requests for help from ordinary townsfolk. It pays to help people in need. Missions are official requests for assistance made by the Windurst authorities. You can receive missions from the guards at the town\'s gatehouse. :*"Nothing in particular.": Feel free to ask next time you need Jack\'s help. Over and out!' },
