    ['Jeanvirgaud'] = { type = 'Outpost Teleporter NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria L-10', note = 'Notes:\nAs of 7-12-2011 he is now located near the Mog House entrance.' },
    ['Jedelaih'] = { type = 'Past Event Watcher', zones = { 'Adoulin', 'Celennia Memorial Library' }, location = 'Celennia Memorial Library', note = 'Notes:\nThis NPC lets you watch cutscenes that you have previously seen in Celennia Memorial Library for 10 gil.' },
