    ['Jeremias'] = { type = 'Cutscene NPC', zones = { 'Bastok (S)', 'North Gustaberg (S)' }, location = 'North Gustaberg (S)', note = 'Involved in Quests:\n* Better Part of Valor\n\nNotes:\n* Seems to be a bodyguard of Senator Werner of the Republican Army during the Crystal War.' },
