    ['Jeronne'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Cutscene only', 'San d\'Oria' }, location = 'Cutscene only', note = 'Involved in Quests:\n* Prelude of Black and White\n\nNotes:\nJeronne is investigating the necropolis for Narcheral, hoping to get information regarding the movements of dark stalkers, or who might be causing them to rally...' },
    ['Jerra Ndala'] = { type = 'Artifact NPC', zones = { 'Adoulin', 'Tomato Vantage Point {{location|Rala Waterways|E-10' }, location = 'Tomato Vantage Point {{location|Rala Waterways|E-10', note = 'Involved in Quests:\n* Forging New Bonds\n\nNotes:\nAfter finishing the quest Legacies Lost and Found, you may commission Rune Fencer Attire from Jerra Ndala at the Tomato Vantage Point. You can choose the order in which you receive the armor and may commission a new piece one game day after the last piece was completed. Interact with the point after the game day changes to exchange the {{KeyItem' },
    ['Jerrett'] = { type = 'Abyssea Support', zones = { 'Abyssea', 'Heavens Tower - Near fountain' }, location = 'Heavens Tower - Near fountain', note = 'Notes:\n* Supplies players with additional Traverser Stones. His stock is shared with Joachim. |' },
    ['Jersey'] = { type = 'Outpost Vendor', zones = { 'Lufaise Meadows', 'Outland' }, location = 'Lufaise Meadows E-8', note = 'Notes:\nAppears when Tavnazian Archipelago is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader\'s current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil' },
