    ['Joyful Alicorn'] = { type = 'NPC Happy New Year 2014', zones = { 'Special Event', 'West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi\'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island' }, location = 'West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi\'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island', note = 'Notes:\nFollows Jubilant Alicorn, which is the only member of the procession with which interaction is possible. It is preceded by Jubilant Alicorn and Joyous Alicorn, and proceeded by Mirthful Ixion.' },
    ['Joyous Alicorn'] = { type = 'NPC Happy New Year 2014', zones = { 'Special Event', 'West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi\'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island' }, location = 'West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi\'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island', note = 'Notes:\nFollows Jubilant Alicorn, which is the only member of the procession with which interaction is possible. It is preceded by Jubilant Alicorn and proceeded by Joyful Alicorn and Mirthful Ixion.' },
