    ['Jubilant Alicorn'] = { type = 'NPC Happy New Year 2014', zones = { 'Special Event', 'West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi\'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island' }, location = 'West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi\'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island', note = 'Notes:\nTrade ordinary items one at a time (such as arrows, crossbow bolts, bullets, or ninja tools) to any Jubilant Alicorn to receive special items such as the monstrosity item Ake-Ome Spirit, which unlocks the monipulator form New Year Mandragora (MON). It is proceeded by Joyous Alicorn, Joyful Alicorn, and Mirthful Ixion, and roams the entire zone. It is the leader of the procession and the largest of the four.' },
    ['Jubilant Pixie'] = { zones = { '* West Sarutabaruta (S)' }, location = '* West Sarutabaruta (S) (F-10) * East Ronfaure (S) (J-7) South West Corner Of (J-7) Near The Wall * North Gustaberg (S) (H-6) * Vunkerl Inlet (S) (H-9) * Grauberg (S) (J-11) * Batallia Downs (S) Near at top of the hill at (F-7) * Fort Karugo-Narugo (S) (G-7) * Jugner Forest (S) (J-6) Along the road * Meriphataud Mountains (S) (I-6) South Center of (I-6), close to the wall * Pashhow Marshlands (S) * Rolanberry Fields (S) (H-7) * Sauromugue Champaign (S) * Beaucedine Glacier (S) (H-10) Turn left at the first tower upon zoning in from Batallia Downs (S) * Xarcabard (S) (J-8)', note = 'Involved in Quests:\n* Succor to the Sidhe' },
    ['Judith'] = { type = 'Mission NPC', zones = { 'Cutscene' }, note = 'Involved in Missions:\n* WOTG05: While the Cat is Away\n* WOTG09: Dancers in Distress\n* WOTG16: Sandswept Memories\n\nNotes:\nJudith is one of the members of Troupe Mayakov.' },
