    ['Jurgenclaus'] = { zones = { 'Bostaunieux Oubliette', 'San d\'Oria' }, location = 'Bostaunieux Oubliette G-8 Jurgenclaus: What do ya think you\'re lookin\' at? You don\'t know nothing about what\'s really going on under this hellhole do ya? Compared to the sewers, my cell is a palace!' },
