    ['Kam\'lanaut'] = { type = 'Cutscene NPC', zones = { 'Cut Scenes Only', 'Cutscene', 'Jeuno' }, location = 'Cut Scenes Only', note = 'Involved in Quests:\n* Apocalypse Nigh\n\nInvolved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Zilart Mission 1: The New Frontier\n* Zilart Mission 8: Return to Delkfutt\'s Tower\n* Promathia Mission 7-5 :The Warrior\'s Path {{verification\n\nNotes:\nKam\'lanaut is the Archduke of the Grand Duchy of Jeuno, and the one who introduced the art of crystal synthesis to Vana\'diel as well as the brother of Eald\'narche. Kam\'lanaut is one of very few characters that are left-handed.' },
    ['Kam\'lanaut (S)'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Jeuno (S)' }, note = 'Involved in Missions:\n* Crossroads of Time\n\nNotes:\nArchduke Kam\'lanaut during the Crystal War.' },
