    ['Kapeh Myohrye'] = { zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods K-7', note = 'Involved in Quests:\n* Lost Chick' },
    ['Karaha-Baruha'] = { zones = { 'Cutscene only', 'Windurst (S)' }, location = 'Cutscene only', note = 'Involved in Quests:\n* The Forbidden Path\n* Howl from the Heavens\n* At Journey\'s End\n\nInvolved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Windurst Mission 9-1: Doll of the Dead\n* Chains of Promathia Mission 3-3: The Road Forks\n\nNotes:\nThe legendary hero of the Crystal War, who worked endlessly to uncover the forbidden secrets of the Full Moon Fountain in order to save Windurst from destruction at the hands of the Yagudo Theomilitary. He is also the owner of the cardian Joker' },
