    ['Kareh\'ayollio'] = { type = 'CS NPC', zones = { 'Jeuno', 'Ru\'Lude Gardens' }, location = 'Ru\'Lude Gardens', note = 'Involved in Missions:\n* Bastok Mission 4-1: Magicite\n* San d\'Oria Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Promathia Mission 3-2: Vessel Without a Captain\n* Promathia Mission 5-3: Three Paths\n* The Pursuit of Paradise (Tenzen\'s Path)\n\nNotes:\n* A member of the Armathrwn Society, he works as an aide to Archduke Kam\'lanaut and later to Duke Vicarious Esha\'ntarl.He works alongside Mawl\'gofaur.' },
