    ['Karola'] = { zones = { 'Windurst', 'Windurst Walls' }, location = 'Windurst Walls K-6' },
    ['Karst'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks K-8', note = 'Involved in Quests:\n* Waking the Colossus\n\nInvolved in Missions:\n* Bastok Mission 2-3: The Emissary\n* Bastok Mission 5-1: Darkness Rising\n* Bastok Mission 5-2: Xarcabard, Land of Truths\n* Bastok Mission 7-2: On My Way\n* Bastok Mission 9-2: Where Two Paths Converge\n* A Crystalline Prophecy (Mission)\n\nNotes:\nPresident of the Republic of Bastok, and a controversial figure among many in the Republic. It is said that he only won his position due to the support of Cid. He is the father of Cornelia. Present version of Hrichter Karst. Derek Karst is his father.' },
    ['Karsten'] = { zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit H-8' },
    ['Karuru'] = { zones = { 'Windurst', 'Windurst Waters map = North|F-8' }, location = 'Windurst Waters map = North|F-8' },
    ['Kasaroro'] = { type = 'Consulate Representative NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria H-9, in Windurstian Consul', note = 'Involved in Missions:\n* Windurst Mission 2-3: The Three Kingdoms' },
    ['Kasim'] = { type = 'Outpost Vendor', zones = { 'Outland', 'The Sanctuary of Zi\'Tah' }, location = 'The Sanctuary of Zi\'Tah H-9', note = 'Notes:\nAppears when Li\'Telor is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader\'s current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil' },
    ['Kasper'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) G-8', note = 'Notes:\n"When the beasthordes sieged San d\'Oria, President Prien wasted no time in putting the entire republic on a wartime footing. In retrospect, it was certainly the right thing to do. If not for his unwavering leadership, we would most likely have begun the war well behind the already expanding beasthordes."' },
    ['Kasra'] = { type = 'Item Deliverer', zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno H-7', icon = 'Deliverer.png' },
    ['Katharina'] = { zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria L-6' },
    ['Katsunaga'] = { type = 'Quest Starter', zones = { 'Mhaura' }, location = 'Mhaura G-10', note = 'Starts Quests:\n* Fisherman\'s Heart' },
    ['Kavivian'] = { type = 'Event NPC', zones = { 'Lower Jeuno', 'Special Event' }, location = 'Lower Jeuno H-9' },
    ['Kaya, I.M.'] = { type = 'Conquest Overseer - Bastok Outpost Conquest Guard', zones = { 'Bastok', 'Outland', 'Xarcabard' }, location = 'Xarcabard H-8', note = 'Notes:\nAppears, when Valdeaunia is under weekly conquest-control by Bastok ;Notes for characters only with Bastok as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts Valdeaunia Supplies for finishing Supply Quest :*Accepts Garrison starting item Behemoth Leather Missive ;Notes for characters only without Bastok as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Kayeel-Payeel'] = { zones = { 'Windurst', 'Windurst Waters map = North|G-7' }, location = 'Windurst Waters map = North|G-7', note = 'Involved in Quests:\n* Starlight Celebration\n\nNotes:\n*  When talked to he says: Harrumph! The Federation has gone rotten, I tell you. Rotten! Who would have thought the day would come when people would forget the name Kayeel-Payeel, Master Caster of the Aquarian War Warlocks! If Warlock Warlord Robel-Akbel were only alive today, heads would roll! How long do the five ministries and the Parliament of Patriarchs plan on keeping his position empty? How long must Fort Karugo-Narugo remain in ruins? *(Trust is actually Kayeel-Payeel (S))' },
    ['Kayeel-Payeel (S)'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) F-7', note = 'Involved in Quests:\n* Howl from the Heavens\n\nNotes:\n* Appears during Campaign Battles as the leader of the Aquarian Casters. *Taking part in Campaign Battles, Kayeel-Payeel will frequently be found in differing locations. While not out by Campaign Fortifications, he will be found in Windurst Waters (S). *Kayeel-Payeel is among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once Windurst regains most territory in their cordon. *In Campaign Battles, he is a BLM/SMN wearing a full Cobra Unit Robe Set and wielding a Claustrum. *Has access to all Staff Weapon Skills including Gate of Tartarus *Assisted by an Ice Fiend and Thunder Fiend after a certain amount of time has elapsed, will summon the Ice Fiend first and then the Thunder Fiend, The elementals will mimic all of his spells. *Uses Manafont. *Has access to all BLM spells including Ancient Magic II with devastating damage (upwards of 2000HP) :* Has an incredibly potent Fast Cast effect when casting all his spells, his elementals also share this trait. *Uses a weaponskill called Tartarus Torpor which inflicts AoE sleep, Magic Evasion Down and Magic Defense Down. :* Players may gain access to Tartarus Torpor during Campaign Battles with a Samudra Equipped. * Battle Cry: The gates to the underworld have opened! I?ll see you on the other side?or not! Wahahahahah! * As a mercenary while waiting for a Campaign battle to start, talk to him and he says: Oh, whatever has become of my sweet Windurst? Rabble running through the streets, streets overrun with rabble! Why are you even speaking to me!? Does the title Master Caster no longer garner even an onze of respect!?' },
