    ['Kerutoto'] = { zones = { 'Windurst', 'Windurst Waters map = South|J-8' }, location = 'Windurst Waters map = South|J-8', note = 'Starts Quests:\n* Food for Thought\n* Blue Ribbon Blues\n* Waking Dreams\n\nInvolved in Quests:\n* Riding on the Clouds\n\nInvolved in Missions:\n* Windurst Mission 7-2: Awakening of the Gods\n* Promathia Mission 5-3: Three Paths\n* Where Messengers Gather (Ulmia\'s Path)\n\nNotes:\nDescribed in Riding on the Clouds as, "A woman everybody called a "strange little poppet" when she was younger"' },
    ['Kesha Shopehllok'] = { type = 'Goldfish Scooping', zones = { 'East Sarutabaruta', 'Outland', 'Special Event' }, location = 'East Sarutabaruta H-8', note = 'Notes:\nAppears, when the special event Sunbreeze Festival is active. :*Sells Super Scoops and buys items of characters :*Gives goldfish scooping points for trading special event catched fish :*Can give you a Goldfish Basket, but you lose all former accumulated goldfish scooping points :*Exchanges prizes for goldfish scooping points For detailed information on fish, prices and other things related to this event see Goldfish Scooping. ;Items sold: *Super Scoop 100gil' },
