    ['Ki Volep'] = { zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods G-11' },
    ['Kieran'] = { zones = { 'Norg' }, location = 'Norg I-8', note = 'Starts Quests:\n* Voidwatch Ops: Border Crossing\n* VW Op. #115: Li\'Telor Variant\n* Skyward Ho, Voidwatcher!\n\nNotes:\nProvides players with assistance with Voidwatch operations similar to those employed by Jeuno. *Ask a bunch of questions. *Participate in Voidwatch Ops. *Request debriefing. *Request Voidstone. *Check Voidstone stock. *Request reward issuance. - Can purchase the following: **Cobalt Cell: 3,000 Cruor **Rubicund Cell: 3,000 Cruor **Xanthous Cell: 3,000 Cruor **Periapt of Emergence: 50,000 Cruor **Periapt of Guidance: 150,000 Cruor **Periapt of Percipience: 150,000 Cruor **Periapt of Sapience: 50,000 Cruor **Periapt of Clarity: 50,000 Cruor Can also convert any given Voiddust into a Voidstone granted that the player have no Voidstones on them currently.' },
    ['Kierron'] = { type = 'Abyssea Support', zones = { 'Abyssea', 'Heavens Tower - Near fountain' }, location = 'Heavens Tower - Near fountain', note = 'Notes:\n* Allows you to view your cruor balance. *Informs you the status of the resistance in Scars of Abyssea areas. *Can teleport you to any Abyssean Cavernous Maw for 200 Cruor. **He only gives you the option to teleport to a maw if you have watched the cutscene and flagged the associated quest after examining it for the first time. Note that you must talk to Joachim after receiving the cutscene at your first Scars of Abyssea maw to receive cutscenes from examining the other maws; you will simply be allowed into the other zones without a cutscene nor teleport access from Horst. You must also be in possession of at least one Traverser Stone to receive a cutscene at its corresponding Cavernous Maw. |' },
    ['Kih Katteh, M.C.'] = { type = 'Campaign NPC', zones = { 'Vunkerl Inlet (S)', 'Windurst (S)' }, location = 'Vunkerl Inlet (S) G-10', note = 'Notes:\n* Windurst (S) affiliated Campaign Arbiter. Present when Windurst (S) has control of Vunkerl Inlet (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Kikilolo'] = { zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno H-9' },
    ['Kilhwch'] = { type = 'Campaign Freelance', zones = { 'Battle', 'Freelance', 'Varies' }, location = 'Varies', note = 'Involved in Quests:\n* Relic Weapon: Excalibur\n\nNotes:\n"I advise you distance yourself from Lady Ulla. I know not your intentions, but I am inclined to believe they are crooked." "Her father and I implored the Lady Ulla to remain within the confines of the estate, but our pleas fell on the deaf ears of youth, and thus I am here to ensure nothing unfortunate befalls her ladyship." *Fights alongside Ulla. *Wields Excalibur, and uses Knights of Round. *When Ulla yells "Kilhwch, silence these fiends!", Kilhwch may cast Silence on his current target. *Will cast Cure V on Ulla when he says: "Lady Ulla, we must retreat." *If Ulla is taken out in battle, Kilhwch will scream "How dare you!" and proceed to use Invincible and go on an all-out offensive. *When allied with the Kingdom of San d\'Oria Kilhwch will assist in battle at Jugner Forest (S). *When allied with the Kingdom of San d\'Oria, Ulla and Kilhwch can be found at (G-10) of Southern San d\'Oria (S). *When allied with the Federal Forces of Windurst, Kilhwch will assist in battle in the Sarutabaruta Front. *When allied with the Federal Forces of Windurst, Ulla and Kilhwch can be found at (F-7) of Windurst Waters (S). *When allied with the Republic of Bastok, Kilhwch will assist in battle at Grauberg (S) and Pashhow Marshlands (S). *When allied with the Republic of Bastok, Kilhwch can be found at D-11 in Bastok Markets (S). *When unallied, Kilhwch and Ulla can be found at (G-10) of Southern San d\'Oria (S).' },
    ['Kilusha'] = { type = 'Einherjar Merchant', zones = { 'Nashmau' }, location = '(H-7) Upper floor at Nashmau.', note = 'Involved in Quests:\n* An Imperial HeistDuties, Tasks, and Deeds\n\nNotes:\nA scientist formerly of the closed Hazhalm Testing Grounds, whose work has been suspended indefinitely by the Empire after a "portal" was opened and some "mice" slipped through the gate. She now seeks adventurers to "clean up" the facility so research can be resumed, and will reward those who enter Einherjar with exotic equipment in exchange for Therion Ichor. (see table below)' },
    ['Kimumu'] = { zones = { 'Windurst', 'Windurst Walls' }, location = 'Windurst Walls J-11' },
    ['Kindlix'] = { type = 'Standard Merchant', zones = { 'Jeuno', 'Near Kazham airship dock in Port Jeuno at' }, location = 'Near Kazham airship dock in Port Jeuno at (I-7).', note = 'Notes:\nPyropox\'s twin brother.' },
    ['King Destin'] = { zones = { 'Cutscene', 'Cutscenes', 'San d\'Oria' }, location = 'Cutscenes', note = 'Involved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* San d\'Oria Mission 5-2: The Shadow Lord\n* San d\'Oria Mission 9-2: The Heir to the Light\n\nNotes:\nKing Destin is the king of San d\'Oria. His wife passed away long ago. He is the father of Prince Trion, Prince Pieuje and Princess Claidie. The King is also first cousin and good friend of Valaineral R Davilles, from whom he learned most of his diplomacy and public affair skills.' },
    ['King of Hearts'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Windurst' }, note = 'Involved in Missions:\n* Aht Urhgan Mission 19: Sweets for the Soul\n* Aht Urhgan Mission 20: Teahouse Tumult\n* Aht Urhgan Mission 21: Finders Keepers\n* Aht Urhgan Mission 22: Shield of Diplomacy\n* Aht Urhgan Mission 23: Social Graces\n* Aht Urhgan Mission 24: Foiled Ambition\n* Aht Urhgan Mission 39: Allied Rumblings\n* Aht Urhgan Mission 40: Unraveling Reason\n* Aht Urhgan Mission 41: Light of Judgment\n\nNotes:\nA Cardian accompanying "Ambassador Karababa" to the Aht Urhgan Whitegate on a diplomatic mission. The Cardian is particularly proud and frequently gets into altercations with the royal automatons.' },
    ['King of Wands'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Inner Horutoto Ruins' }, location = 'Inner Horutoto Ruins', note = 'Involved in Missions:\n* Windurst Mission 3-2: Written in the Stars\n\nNotes:\nThe King of Wands appears along with the King of Batons during a cutscene for Windurst Mission 3-2 Written in the Stars. They are behind the Gate of Light where they can not be reached, however they are both visible on Wide Scan, along with an invisible NPC named "gohu" (probably a placeholder for the talisman), which is not visible on Wide Scan. More information can be found at [http://www.ffxionline.com/forums/general-ffxi-discussion/75301-king-batons-king-wands-gohu.html this link].' },
    ['Kingslayer Doggvdegg'] = { zones = { 'Beastman Confederate', 'Cutscene' }, note = 'Involved in Quests:\n* Wrath of the Griffon\n* The Price of Valor\n* Blood of Heroes\n\nNotes:\n* Leader of the Bloodwing Horde and Commander of Orcish Hosts, Doggvdegg was the undisputed leader of the Orcs during the Crystal War' },
