    ['Larkin, C.A.'] = { type = 'Campaign NPC', zones = { 'Jugner Forest (S)' }, location = 'Jugner Forest (S) I-8', note = 'Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of Jugner Forest (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign *Located in the NW corner of (I-8)' },
    ['Larzos'] = { type = 'Cutscene NPC', zones = { 'Cutscene' }, note = 'Involved in Missions:\n* WOTG19: Betrayal at Beaucedine\n* WOTG22: A Sanguinary Prelude\n* WOTG25: The Will of the World\n* WOTG26: Fate in Haze\n\nNotes:\nOne of the Spitewardens of Lady Lilith alongside Aquila and Haudrale, the commander of the "Bismuth Musketeers". Appears to be a galkan fomor.' },
    ['Lasthenes'] = { zones = { 'Bastok', 'Zeruhn Mines' }, location = 'Zeruhn Mines H-7', note = 'Notes:\n* Controls access to Korroloka Tunnel.' },
    ['Lathuya'] = { type = 'Quest Giver', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate F-8 - Second Floor', note = 'Involved in Quests:\n* Omens\n* Transformations\n\nNotes:\nA craftswoman in the employ of Kushdeel. She helps craft equipment for the Imperial Forces. Lathuya crafts the following pieces of Blue Mage Artifact Armor when given the appropriate items: *Magus Bazubands *Magus Shalwar *Magus Jubbah' },
    ['Latifah'] = { zones = { 'Bastok', 'Port Bastok' }, location = 'Port Bastok J-8', note = 'Involved in Quests:\n* Stamp Hunt\n\nNotes:\n* She warns adventures off the drawbrige when it is going up for airships.' },
    ['Latifah (A)'] = { type = 'Quest NPC', zones = { 'Abyssea', 'Abyssea - Uleguerand Second Outpost' }, location = 'Abyssea - Uleguerand Second Outpost', note = 'Involved in Quests:\n* Imperial Espionage' },
    ['Latteaune'] = { type = 'Melody Minstrel', zones = { 'Tavnazian Safehold' }, location = 'Tavnazian Safehold H-6, on the main level', note = 'Notes:\nThis NPC will let you watch cut-scenes that you have seen in the Tavnazian Safehold in the past, for 10 gil.' },
    ['Laucimercen'] = { zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria F-9' },
    ['Laughing Bison'] = { zones = { 'Mhaura' }, location = 'Mhaura I-9', note = 'Notes:\nAnnounces which ferry while arrive next, sign changes after each departure.' },
    ['Laughing Lizard'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst C-8', note = 'Notes:\nOffers an Explanation of the Fishing System: Eh? You say somethin\'? Hmph! You dang kids these days ain\'t go no respect for your elders. Can\'t you see I\'m tryin\' to learn this new fandagled fishin\' method? In my day, all we had to do was cast a line and wait for the baby to tug. Why, back then it was so easy, I could catch fish while I was slieepin\'! But now you gotta work for your meal! Let me tell you how it\'s done... First, you fix a little bait on your line, toss it into the water, and wait for somethin\' to bite. Eh? What\'s changed? Well, nothing yet! Would you just hold your horses and let me get to the good part? Now, once you feel the pull is where the real battle begins--and I say battle because that fish is not going to let you get him without a fight! If he starts tuggin\' to the left, you\'ve gotta pull to the right. If he starts tuggin\' to the right, you\'ve gotta pull to the left. Keepin\' centered--that\'s the key to tirin\' out that old puppy! And once you think you\'ve softened him up enough, that\'s when you reel him in. If you confirm a little too early, the fish may still have enough pep to run off with your bait. But if you spend too much time playin\' with him, he maight just get bored and be on his way. Of course, if you ever get a bad feeling that whatever\'s on the end of your line\'s fixin\' to snap your rod in two, you could always cancel your way out of things......sissy! Alright did you get all that? Well, keep listenin\', \'cause I\'m not done yet. This new type o\' fishin\' works differently with different types of rods. Those fancy carbon and glass rods may have what it takes to keep a fish on your line for a long time, but the flexibility of good old-fashioned wooden rods packs enough punch to tire out any fish in the blink of an eye. But enough of this chitchat. If I don\'t catch somthing\' for tonight\'s dinner, my wife\'ll clean me, gut me, and have me in a fryin\' pan faster than you can say Galka mauniere.' },
    ['Laujaquetemps'] = { type = 'Chocobobet Center Clerk', zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit H-7, Jeuno Area', note = 'Notes:\n* Takes bets for the chocobo races.' },
    ['Laurana'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno', note = 'Involved in Quests:\n* Girl in the Looking Glass\n* Past Reflections\n* Blessed Radiance\n\nNotes:\n* Mother of Palometa.' },
    ['Laurentia'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) D-10', note = 'Notes:\n"There\'s a mining spot in Grauberg where you can dig up some very good quality crystals. Apparently the Quadav Shieldwarriors will stop at nothing to gain control of mining resources. That\'s the reason for the continuing conflict between them and republic."' },
