    ['Layton'] = { type = 'Standard Merchant', zones = { 'Bastok (S)', 'The Eldieme Necropolis (S)' }, location = 'The Eldieme Necropolis (S) J-8 (via Batallia Downs (S) (J-10) entrance)' },
    ['Leadavox'] = { zones = { 'Outland', 'Vunkerl Inlet (S)' }, location = 'Vunkerl Inlet (S) J-6', note = 'Involved in Quests:\n* Better Part of Valor\n* Boy and the Beast (appears in cutscene)\n* Knot Quite There (appears in cutscene)\n* Beneath the Mask\n* Her Memories: Operation Cupid\n\nNotes:\n* A goblin familiar with the ways and languages of the beastmen races. She is more than willing to lend her services to members of the Allied Forces of Altana....for a fee. *She accompanied the Elvaan missionary Joseaneaut on his travels to the beastmen strongholds and served as a translator.' },
    ['Leaufetie, R.K.'] = { type = 'Conquest Overseer - San d\'Oria Outland Conquest Guard', zones = { 'Beaucedine Glacier', 'Outland', 'San d\'Oria' }, location = 'Beaucedine Glacier G-6', note = 'Notes:\nAppears, when Fauregandi is under weekly conquest-control by San d\'Oria ;Notes for characters only with San d\'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Fauregandi Supplies for finishing Supply Quest ;Notes for characters only without San d\'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Leaute'] = { type = 'Cut Scene NPC', zones = { 'Cut Scene Only', 'San d\'Oria' }, location = 'Cut Scene Only', note = 'Involved in Quests:\n* Her Majesty\'s Garden\n* Unexpected Treasure\n\nInvolved in Missions:\n* San d\'Oria Mission 6-1: Leaute\'s Last Wishes\n\nNotes:\nLeaute I d\'Oraguille was the Queen of San d\'Oria, wife of King Destin and mother of (in order): Trion, Pieuje and Claidie. Her madien name was Leaute I Tavnazia, Princess of Tavnazia. First born of the late Marquis Altedour I Tavnazia, her younger brother went missing when Tavnazia was destroyed during the Crystal War. She died 15 years ago in 869 C.E. under suspicious curcomstances. She was at least 38 years old, as she had already had her Coming of Age (held at age 20) by the time she married.' },
    ['Leautiere'] = { zones = { 'Adoulin', 'Yahse Hunting Grounds' }, location = 'Yahse Hunting Grounds G-7' },
    ['Lebondur'] = { type = 'Regional Vendor NPC :*Vollbow Region', zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst F-6' },
