    ['Leepe-Hoppe'] = { type = 'Quest NPC', zones = { 'Windurst', 'Windurst Waters map = South|J-9, on top of the Rhinostery' }, location = 'Windurst Waters map = South|J-9, on top of the Rhinostery', note = 'Starts Quests:\n* The Moonlit Path\n* Tuning In\n* Tuning Out\n\nInvolved in Missions:\n* Windurst Mission 1-3: The Price of Peace\n* Windurst Mission 7-2: Awakening of the Gods' },
