    ['Lerene'] = { type = 'Quest Giver NPC', zones = { 'Adoulin', 'Outer Ra\'Kaznar map=Map 1|N-7' }, location = 'Outer Ra\'Kaznar map=Map 1|N-7', note = 'Starts Quests:\n* Lerene\'s Lament' },
