    ['Lharant'] = { zones = { 'Cut Scene Only', 'San d\'Oria' }, location = 'Cut Scene Only', note = 'Involved in Quests:\n* Face of the Future\n\nNotes:\nYoung Rholont grown up.' },
    ['Lhe Lhangavo'] = { type = 'Cutscene NPC', zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin', note = 'Involved in Quests:\n* Scaredy-Cats\n* Not-So-Clean Bill\n\nInvolved in Missions:\n* An Extraordinary Gentleman\n* Glimmer of Portent\n* ...Into the Fire\n* Ministerial Whispers' },
    ['Lhimo Keanyohn'] = { type = 'VCS Chocobo Racing Associate', zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst E-6', note = 'Notes:\n* Provides information about Chocobo Racing, and recruits adventurers for the CRA Windurst team.* Removed from Game on 9/9/2010.' },
    ['Lhu Mhakaracca'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) E-9', note = 'Involved in Quests:\n* When One Man Is Not Enough\n\nNotes:\n:*Appears during Campaign Battles as the leader of the Python Mercenaries. :*Calls upon Kyo and Pya, which are Rocs. :*Taking part in Campaign Battles, Lhu Mhakracca will frequently be found in differing locations. While not out by Campaign Fortifications, she will be found in Windurst Waters (S). :*Owns a Guttler. Unlike most relic weapons that seem to keep their intelligence a secret, Lhu\'s Guttler speaks publicly, much to her annoyance. :*Talk: (Guttler! I told you to keep qui--) Ahahahah... Don\'t mind me, I was just...uh...keeping myself company! (Shhh! If you open your mouth one more ti--) Ahahaha... Uh, were you still there? :*Guttler\'s battle cry: Guttler thirsty! Guttler want blood! More blood! (It says this right before Lhu uses Onslaught)' },
    ['Libran Caster'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Various', 'Windurst (S)' }, location = 'Various', note = 'Notes:\n:*Leader of the Libran Casters is Zolku-Azolku. :*Squadron appears in various locations either fortifying or in Campaign Battles. :*Buffs themselves with Protect IV and Shell III.' },
    ['Lidaise'] = { type = 'Chocobo Renter', zones = { 'Meriphataud Mountains (S)', 'Outland' }, location = 'Meriphataud Mountains (S) I-8', note = 'Notes:\n* Must be level 20, have a Chocobo License,and be affiliated with one of the armies of the three nations to be eligible to rent a Chocobo. *Rental fees will be charged in Allied Notes rather than gil.', icon = 'ChocoboRenter.png' },
    ['Lidaise, T.K.'] = { type = 'Campaign NPC', zones = { 'Garlaige Citadel (S)', 'San d\'Oria (S)' }, location = 'Garlaige Citadel (S) I-6', note = 'Notes:\n* San d\'Oria affiliated Campaign Arbiter. Present when San d\'Oria (S) has control of Garlaige Citadel (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
