    ['Little Sheep'] = { type = 'Livestock', zones = { 'Adoulin', 'Mog Garden' }, location = 'Mog Garden', note = 'Involved in Quests:\n* Release the Fleece\n* Feeding Frenzy\n\nNotes:\n* Little Sheep is added to your Mog Garden during the quest Release the Fleece. *See Monster Rearing for more information.' },
    ['Llewellyn'] = { type = 'Campaign Evaluator', zones = { 'Windurst (S)', 'Windurst Waters (S) map = North|G-9' }, location = 'Windurst Waters (S) map = North|G-9', note = 'Notes:\n* Llewellyn provides evaluations for players aligned with the Cobra Unit.' },
    ['Loaranne'] = { type = 'Event NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria', 'Special Event' }, location = 'Northern San d\'Oria' },
    ['Lobho Ukipturi'] = { type = 'Outpost Vendor', zones = { 'Buburimu Peninsula', 'Outland' }, location = 'Buburimu Peninsula E-7', note = 'Notes:\nAppears when Kolshushu is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader\'s current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil' },
    ['Logan'] = { type = 'Cutscene NPC', zones = { 'Adoulin', 'Cutscene', 'Eastern Adoulin' }, location = 'Eastern Adoulin', note = 'Involved in Quests:\n* Flowers for Svenja{{Verification' },
    ['Loillie'] = { zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) K-9 * Found through the Portcullis at (L-8), then south into a tunnel and up the stairs. She is atop the overpass, manning a bow.', note = 'Involved in Quests:\n* Gifts of the Griffon\n\nInvolved in Missions:\n* WOTG21: Proof of Valor' },
    ['Lokhong'] = { type = 'Guild Merchant NPC: Fishing Guild :Open: 1:00 - 23:00 :Similar to, but does not share stock with Rajmonda.', zones = { 'Ferry lower deck (Selbina to Mhaura route only)' }, location = 'Ferry lower deck (Selbina to Mhaura route only)' },
    ['Lokpix'] = { zones = { 'Eastern Altepa Desert', 'Outland' }, location = 'Eastern Altepa Desert G-7, next to the Telepoint', note = 'Starts Quests:\n* Open Sesame' },
    ['Lola'] = { type = 'Skirmish NPC', zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin G-8 (other side of the table from Oston)', note = 'Involved in Quests:\n* A Thirst for the Eons\n* A Thirst Before Time\n\nNotes:\n* Explains the various rules associated with Skirmishes. * You must first speak with Oston before Lola will accept trades. *Stores and exchanges Lebondopt Wings and Pulchridopt Wings for Armor found in Skirmish. After she accepts Lebondopt wings, you must speak with her again before she will accept Pulchridopt wings.' },
    ['Lollyspox'] = { zones = { 'Crawlers\' Nest (S)', 'Outland' }, location = 'Crawlers\' Nest (S) L-8', note = 'Notes:\n;Items sold: *Hi-Potion 4,500 gil *Hi-Ether 28,000 gil' },
    ['Loloroon'] = { zones = { 'Nashmau' }, location = 'Nashmau G-7' },
