    ['Lootblox'] = { type = 'Goblin Peddler', zones = { 'Davoi', 'Outland' }, location = 'Davoi J-7', note = 'Notes:\nYou must have a {{KeyItem' },
    ['Lord Fainevlure Ordelle'] = { zones = { 'Never shown', 'San d\'Oria' }, location = 'Never shown', note = 'Notes:\nLord Fainevlure Ordelle was the first captain of the Royal Knights. His face adorns the Ordelle Bronzepiece, which was issued in commemoration of him and his knights.' },
    ['Lord Torresapet B Ordelle'] = { zones = { 'Never shown', 'San d\'Oria' }, location = 'Never shown', note = 'Involved in Quests:\n* Signed in Blood (mentioned)\n\nNotes:\nLord Torresapet B Ordelle was a famous explorer and is the namesake of Ordelle\'s Caves, a twisting limestone cavern which he discovered and went to great lengths to map. He was the rival and contemporary of Gwynham Ironheart, another famous explorer and the creator of the Stone Monuments. Near the end of his life, he wrote a book on the life of Gwynham, which currently resides in the possession of Abelard in Selbina, but was sadly damaged by Gwyham\'s daughter, Enid Ironheart, and is missing several pages.' },
    ['Lorena'] = { type = 'Guildworker\'s Union', zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks E-7', note = 'Notes:\nServes the same function as Macuillie, her counterpart in Northern San d\'Oria.' },
    ['Lorissa'] = { type = 'Mellidopt Wing Trader', zones = { 'Adoulin', 'Yorcia Weald' }, location = 'Yorcia Weald I-10 upon selecting the ??? by the Augural Conveyor', note = 'Notes:\nYou need to have previously entered an Alluvion Skirmish before she will appear. She will store Mellidopt Wings traded to the ??? and exchange them for the following items. ---- ? Weapons ? Armour ? Augmentation Stones ? ----' },
    ['Lothur, I.M.'] = { type = 'Campaign NPC', zones = { 'Bastok (S)', 'Castle Zvahl Keep (S)' }, location = 'Castle Zvahl Keep (S)', note = 'Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok has control of Castle Zvahl Keep (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation. *Campaign Sword in front of name during Campaign.' },
