    ['Loussaire'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) G-10', note = 'Starts Quests:\n* Scholar\'s Loafers Quest\n* Scholar\'s Pants Quest\n* Scholar\'s Gown Quest\n\nNotes:\nLoussaire provides the following Scholar Artifact Armor upon completion of certain Side Quests: *Scholar\'s Loafers *Scholar\'s Pants *Scholar\'s Gown Note: *Player must be 50+ Scholar and complete Downward Helix to accept the side quest. *Disappears during Campaign Battles in the city.' },
    ['Loutille'] = { zones = { 'Garlaige Citadel (S)', 'San d\'Oria (S)' }, location = 'Garlaige Citadel (S) I-7', note = 'Notes:\n:"Have you heard tell of the Gigas invasion of Vunkerl Inlet? :Stories tell of their monstrous strength, effortlessly tossing about boulders even larger than themselves. :...That reminds me, I haven\'t acquried a map of Vunkerl Inlet myself. :I must go and retrieve one from the Munitions Storeroom."' },
    ['Louvairausse'] = { type = 'Mission NPC', zones = { 'Cutscene', 'San d\'Oria (S)' }, note = 'Involved in Missions:\n* WOTG22: A Sanguinary Prelude' },
    ['Louverance'] = { type = 'Mission NPC', zones = { 'Cutscene', 'Cutscenes', 'San d\'Oria' }, location = 'Cutscenes', note = 'Involved in Quests:\n* Over the Hills and Far Away\n* Signed in Blood\n* Tea with a Tonberry?\n\nInvolved in Missions:\n* The Road Forks: The Road Forks\n* Where Messengers Gather (Ulmia\'s Path)\n* Promathia Mission 7-4: Calm Before the Storm\n* Promathia Mission 8-4: Dawn\n\nNotes:\nThe grandson of Francmage and the heir to the Knights Mistalle, Louverance N Mistalle was employed as a Royal Knight until he resigned his commission. He appears a few times in the Chains of Promathia Missions.' },
    ['Louxiard'] = { zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) G-7 * Behind the Portcullis', note = 'Starts Quests:\n* Gifts of the Griffon\n\nInvolved in Missions:\n* WOTG21: Proof of Valor' },
    ['Luca'] = { type = 'Chocobo Circuit Associate', zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit H-9', note = 'Notes:\n* Mans the general information counter in the Chocobo Circuit with Khatri.' },
    ['Lucia'] = { zones = { 'Selbina' }, location = 'Selbina I-10' },
    ['Lucius'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks J-9, inside the Aide\'s Office on the upper level', note = 'Involved in Quests:\n* Riding on the Clouds\n* Waking the Colossus\n* Trust: Bastok - Triggers the cutscene to learn Trust: Volker if you are at least Rank 6.\n\nInvolved in Missions:\n* Bastok Mission 1-1: The Zeruhn Report\n* Bastok Mission 2-3: The Emissary\n* Bastok Mission 3-2: To the Forsaken Mines\n* Bastok Mission 3-3: Jeuno\n* Bastok Mission 5-1: Darkness Rising\n* Bastok Mission 5-2: Xarcabard, Land of Truths\n* Bastok Mission 9-1: The Salt of the Earth\n* Bastok Mission 9-2: Where Two Paths Converge\n\nNotes:\nDescribed in Riding on the Clouds as, "A man who is ready to move Bastok into the age of magic."' },
    ['Lucius (A)'] = { zones = { 'Abyssea', 'Abyssea - Grauberg' }, location = 'Abyssea - Grauberg G-12' },
    ['Lucky Ladon'] = { type = 'Special Event NPC', zones = { 'West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi\'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island / Xarcabard (roaming)' }, location = 'West Ronfaure / East Ronfaure / La Theine Plateau / Valkurm Dunes / Jugner Forest / Batallia Downs / North Gustaberg / South Gustaberg / Konschtat Highlands / Pashhow Marshlands / Rolanberry Fields / Beaucedine Glacier / Western Altepa Desert / Eastern Altepa Desert / West Sarutabaruta / East Sarutabaruta / Tahrongi Canyon / Buburimu Peninsula / Meriphataud Mountains / Sauromugue Champaign / The Sanctuary of Zi\'Tah / Yuhtunga Jungle / Yhoator Jungle / Qufim Island / Xarcabard (roaming)', note = 'Involved in Quests:\n* Happy New Year 2012\n* Happy New Year 2024' },
    ['Lucretia'] = { type = 'Guild Merchant NPC: Smithing Guild', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria E-6', note = 'Notes:\nNo longer closed on Watersday.No longer shares stock with Doggomehr.Stock is the same selection as Vicious Eye and Mololo offers.' },
    ['Lucretia (Ceizak Battlegrounds)'] = { type = 'Quest NPC', zones = { 'Adoulin', 'Ceizak Battlegrounds' }, location = 'Ceizak Battlegrounds H-9', note = 'Starts Quests:\n* To Catch a Predator' },
    ['Ludiault'] = { zones = { 'Norg' }, location = 'Norg I-9' },
    ['Ludwig'] = { type = 'Map Vendor', zones = { 'Mhaura' }, location = 'Mhaura H-9', note = 'Notes:\n* It is more than unlikely that Ludwig is related to Ludwig (S) (wrong face, place and displaced occupation).' },
    ['Ludwig (S)'] = { type = 'Campaign Battle Ally NPC', zones = { 'Bastok (S)', 'Bastok Markets (S)', 'Battle' }, location = 'Bastok Markets (S) H-10', note = 'Involved in Missions:\n* | involved in quests\n\nNotes:\n:* Holds the title of 2nd Division\'s Legatus which makes him Commander in Chief of the 2nd Division/Legion of the Republican Army. :* Can appear in all Campaign Battles for Bastok (S) as the leader of the 2nd Legionnaire squadron. :* Can cast Bio III, Sleep II, Stun, Drain, Aspir, and the Absorb line of spells (eg. Absorb-VIT). :* Uses Guillotine for 1700-2600+ damage. :* His attacks have an Additional Effect: {{Dark|Darkness damage' },
    ['Ludwig Eichberg'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) H-10', note = 'Involved in Missions:\n* Affairs of State\n\nNotes:\n* Holds the title of 2nd Division\'s Legatus which makes him Commander in Chief of the 2nd Division/Legion of the Republican Army. "We may have the upper hand in technology and munitions, but the enemy\'s advantage lies in their sheer numbers. The Allied Campaign will not win in a day, soldier. Make every bullet count."' },
    ['Luhk Leotih, M.C.'] = { type = 'Campaign NPC', zones = { 'Beaucedine Glacier (S)', 'Windurst (S)' }, location = 'Beaucedine Glacier (S) I-8', note = 'Notes:\n* Windurst affiliated Campaign Arbiter. Present when Windurst (S) has control of Beaucedine Glacier (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Lulupp'] = { zones = { 'Kazham' }, location = 'Kazham G-7', note = 'Involved in Quests:\n* The Opo-opo and I\n\nNotes:\n*  Accepts the Broken Mithran Rod for The Opo-opo and I.' },
    ['Lumber Chest'] = { zones = { 'Abyssea', 'Abyssea - Uleguerand (Vertical Conflux #01)' }, location = 'Abyssea - Uleguerand (Vertical Conflux #01)', note = 'Involved in Quests:\n* Home, Home on the Range' },
    ['Luminous Coalescence'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Windurst (S)', 'Windurst Waters (S), Garlaige Citadel (S)' }, location = 'Windurst Waters (S), Garlaige Citadel (S)', note = 'Notes:\n* Summoned by Lutete during Campaign Battles (up to 4 {{PAGENAME' },
    ['Lumomo'] = { type = 'Quest NPC', zones = { 'Windurst', 'Windurst Waters map = North|F-10' }, location = 'Windurst Waters map = North|F-10', note = 'Starts Quests:\n* Eco-Warrior (Windurst)' },
    ['Lunar Rabbit'] = { type = 'Event NPC', zones = { 'Ru\'Lude Gardens', 'Special Event' }, location = 'Ru\'Lude Gardens I-8', note = 'Description:\nA white rabbit which replaces the brown rabbit next to Chacharoon during a full moon.\n\nNotes:\nTrade it certain vegetables for a chance to receive a Large White Tail. It accepts: *San d\'Orian Carrot *Moon Carrot *Vomp Carrot *Zegham Carrot *Faerie Apple *La Theine Cabbage *Mithran Tomato *Napa *Ogre Pumpkin *Pamamas *Winterflower *Attohwa Ginseng *Yellow Ginseng' },
    ['Luquillaue'] = { zones = { 'Carpenters\' Landing Barge', 'Outland' }, location = 'Carpenters\' Landing Barge', note = 'Notes:\nProvides information about when the barge will land.' },
    ['Luren'] = { type = 'Crafter Points Administration', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria E-3', note = 'Notes:\nAdministrates Crafter Points for items used to upgrade Escutcheons. Also sells Crafting Kits.' },
    ['Lurouillat'] = { type = 'Sealed Container NPC', zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) J-9', note = 'Notes:\n* Trade Sealed Containers to her to receive the corresponding key item for SCNM battle.' },
    ['Lusiane'] = { type = 'Standard Merchant', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria F-8, in front of Taumila\'s Sundries' },
    ['Lutete'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) L-10', note = 'Involved in Quests:\n* Howl from the Heavens\n\nNotes:\n* Appears during Campaign Battles as the leader of the Ariesian Casters. *Lutete and her caster company will only engage in campaign battles at Garlaige Citadel (S) and Windurst Waters (S). *Summons three Luminous Coalescences that fight alongside her. *Casts Curaga IV on herself and her Luminous Coalescences. *Use the weapon skill Moonlight to restore the MP of her elementals. *Talk: ... Mastering these Near Eastern magics can be quite taxing. If I had a choice, I\'d rather be back in bed, relaxing... *Battle cry: ... Um... Holy light... show the way...?' },
    ['Luthiaque'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria G-9', note = 'Involved in Quests:\n* Lost Chick\n\nNotes:\nThis NPC will display a map of San d\'Oria.' },
    ['Lutia'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks I-9', note = 'Notes:\n* Friend to Professor Emanritan.' },
    ['Luto Mewrilah'] = { type = 'Quest Giver NPC', zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno G-8', note = 'Starts Quests:\n* Unlisted Qualities (FQ 1A)\n* Girl in the Looking Glass (FQ 1B)\n* Mirror, Mirror (FQ 1C)\n* Past Reflections (FQ 2)\n* Blighted Gloom (FQ 3)\n* Chameleon Capers (FQ 4)\n* Blessed Radiance (FQ 5)\n* Mirror Images (FQ 6)\n* Regaining Trust (FQ cap60)\n* Clash of the Comrades (FQ cap70)\n* A Trial in Tandem (FQ cap75)\n* A Trial in Tandem, Redux (FQ cap80)\n* Yet Another Trial in Tandem (FQ cap85)\n* A Quaternary Trial in Tandem (FQ cap90)\n\nInvolved in Quests:\n* Picture Perfect (FQ cap55) (not involved but listed for reference only)\n* Mixed Signals (FQ cap65)\n* Bait and Switch\n* Lure of the Wildcat (Jeuno)' },
    ['Luuh Koplehn'] = { zones = { 'Windurst', 'Windurst Walls' }, location = 'Windurst Walls F-7', note = 'Notes:\nDialog: Come on, Professorrr Koru-Moru. I\'m not moving until you cough up the gil forrr yourrr overdue accounts at the Bonework\'s Guild. As both a ministerrr and the principal of our local school, shouldn\'t you be setting a betterrr example?' },
    ['Luzaf'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Various cutscenes, the Ashu Talif' }, location = 'Various cutscenes, the Ashu Talif', note = 'Involved in Quests:\n* Unwavering Resolve\n\nStarts Missions:\n* Aht Urhgan Mission 35: Legacy of the Lost\n\nInvolved in Missions:\n* Aht Urhgan Mission 15: The Black Coffin\n* Aht Urhgan Mission 22: Shield of Diplomacy\n* Aht Urhgan Mission 25: Playing the Part\n* Aht Urhgan Mission 29: Puppet in Peril\n* Aht Urhgan Mission 30: Prevalence of Pirates\n* Aht Urhgan Mission 32: In the Blood\n* Aht Urhgan Mission 34: Testing the Waters\n* Aht Urhgan Mission 36: Gaze of the Saboteur\n* Aht Urhgan Mission 37: Path of Blood\n* Aht Urhgan Mission 41: Light of Judgment\n* Aht Urhgan Mission 42: Path of Darkness\n* Aht Urhgan Mission 45: Ragnarok\n\nNotes:\n* Prince Luzaf is the admiral of the "Black Coffin," a.k.a. the Ashu Talif. Originally led a resistance against the Empire of Aht Urhgan two hundred years prior in the Arrapago Islands, but continues to roam the seas as a Fomor.' },
    ['Lycopodium (NPC)'] = { zones = { 'Batallia Downs (S), Garlaige Citadel (S), North Gustaberg (S),', 'Outland' }, location = 'Batallia Downs (S), Garlaige Citadel (S), North Gustaberg (S),', note = 'Starts Quests:\n* Lycopodium Warps' },
