    ['Maccus'] = { type = 'Monstrosity NPC', zones = { 'Feretory' }, location = 'Feretory', note = 'Involved in Quests:\n* Monstrosity (Quest)\n* Monstrosity\n\nNotes:\nThis spirit resides in the Feretory. It is the true form of the one of the possessed mannequin knowns as Suspicious Hume, Suspicious Elvaan, Suspicious Galka, or Suspicious Tarutaru.' },
    ['Macera'] = { type = 'Armor Depository', zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin I-11', note = 'Notes:\nStores lvl 24-60 AF, Relic, RSE and other gearsets.' },
