    ['Machitata'] = { type = 'Residence Renter', zones = { 'Windurst', 'Windurst Waters map = North|L-11' }, location = 'Windurst Waters map = North|L-11', note = 'Involved in Quests:\n* Hat in Hand' },
    ['Machu-Kuchu'] = { type = 'Warp NPC', zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst E-7', note = 'Notes:\nHe will warp you for free to Komulili in (Windurst Walls, (J-11). "Have you, traveler, also come to Windurst to take a looky at the Great Star Tree? If so, then the star tree, also known as Heavens Tower, is far to the northeasty of here, in Windurst Walls. If you wanty, I can use my magic to sendy you to Windurst Walls in an instant. Would you likey that?"' },
    ['Macici'] = { type = 'Free and Advanced Synthesis Image Support NPC :*Smithing Guild', zones = { 'Al Zahbi' }, location = 'Al Zahbi H-9', note = 'Involved in Quests:\n* Promotion: Chief Sergeant\n\nNotes:\n* Payment for Advanced Synthesis support is one Imperial Bronze Piece.' },
    ['Macro Test'] = { zones = { 'Batallia Downs' }, location = 'Batallia Downs K-8 / Rolanberry Fields J-5 / Sauromugue Champaign E-6', note = 'Notes:\n* Batallia Downs: 2 Cardians *Rolanberry Fields: 3 Cardians *Sauromugue Champaign: 3 Cardians The Cardians live just outside the exits from Jeuno. As the name implies, their intended purpose is to allow players to test combat macros that are only usable during combat. * Check as "Impossible to Gauge". * Do not move or fight back. * Damage from all attacks (both physical and magical) is reduced to zero. * Completely immune to all enfeebles except Dia and Bio (damage over time from those two spells is also reduced to zero). * You cannot gain TP and you cannot gain combat or magic skillups from attacking them. * Their HP is shrouded at all times. Like Domain Invasion, Macro Test cardians can be attacked by any player regardless of party or alliance formation. Unlike Domain Invasion, Trusts can not be called out while engaged with a Macro Test cardian. You can disengage and immediately begin calling trusts.' },
    ['Macuillie'] = { type = 'Guildworker\'s Union NPC :*Smithing', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria E-6', note = 'Notes:\nServes the same function as Lorena, her counterpart in Metalworks.' },
