    ['Magali'] = { zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit H-8' },
    ['Magdalena'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) F-8', note = 'Notes:\n"I\'ll admit, I wasn\'t sure how things would turn out when Selbina suddenly declared its independence. Senator Werner dispatched the Republican Legion and took control of the situation with such incredible speed. Even the president himself was amazed by the senator\'s show of skill."' },
