    ['Magumo-Yagimo, W.W.'] = { type = 'Conquest Overseer - Windurst Outpost Conquest Guard', zones = { 'Outland', 'Windurst', 'Xarcabard' }, location = 'Xarcabard H-8', note = 'Notes:\nAppears, when Valdeaunia is under weekly conquest-control by Windurst ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Valdeaunia Supplies for finishing Supply Quest :*Accepts Garrison starting item Behemoth Leather Missive ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Mahien-Uhien'] = { type = 'Outpost Vendor', zones = { 'West Sarutabaruta' }, location = 'West Sarutabaruta H-6', note = 'Notes:\nAppears when Sarutabaruta is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader\'s current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil' },
