    ['Mandragora Assistant'] = { zones = { '*Southern San d\'Oria' }, location = '*Southern San d\'Oria K-10 *Bastok Mines I-9 *Windurst Walls C-12 *Ru\'Lude Gardens G-9 *Mhaura G-9 *Mog Garden By the umbrella. *Rabao G-6 *Chocobo Circuit H-9 *Eastern Adoulin H-10', note = 'Notes:\nThey show up on Wide Scan if you have difficulty finding them. They are very small and have no name over their heads.' },
