    ['Matica, R.K.'] = { type = 'Conquest Overseer - San d\'Oria Outland Conquest Guard', zones = { 'Outland', 'Qufim Island', 'San d\'Oria' }, location = 'Qufim Island I-8', note = 'Notes:\nAppears, when Qufim is under weekly conquest-control by San d\'Oria ;Notes for characters only with San d\'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Qufim Supplies for finishing Supply Quest ;Notes for characters only without San d\'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Matifa'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate H-9 - Serpentking Square, Fountain', note = 'Involved in Quests:\n* Arts and Crafts' },
    ['Matildie'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria J-8', note = 'Notes:\nDialogue: Anilla: Is it just me, or are there more strangers in town these days? Whatever could it mean? Matildie: What, have you not heard? They are recruiting adventurers in droves! I hear they\'re taking any who will come-- foreigners, even! Anilla: Well, guess what happened to me. I was tidying the house yesterday, when a strange man walked in. He then ran out the veranda without even saying hello! Matildie: Shame on those adventurers! At least they could knock before barging into our homes. |' },
    ['Matoaka'] = { type = 'Standard Merchant', zones = { 'Gems by Kshama in {{location|Lower Jeuno|H-9', 'Jeuno' }, location = 'Gems by Kshama in {{location|Lower Jeuno|H-9' },
    ['Matrimonial Coffer'] = { type = 'Standard Merchant', zones = { '. *Chateau d\'Oraguille' }, location = '. *Chateau d\'Oraguille (H-9) *Metalworks (J-8) *Heavens Tower (In the Clerical Chamber)', note = 'Notes:\nSee also *Rembard *Cloud Walker *Pompi-Rompi *Celebratory Chest' },
    ['Matthias'] = { zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets J-9', note = 'Notes:\nMatthias crafts the following pieces of Dancer Artifact Armor when given the appropriate items: *Dancer\'s Bangles *Dancer\'s Tiara *Dancer\'s Shoes Note: You will need to speak with Olgald in Upper Jeuno (G-7) before talking to Matthias in order to place a request with him.' },
    ['Matthias (S)'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) J-9', note = 'Notes:\n"I\'m a huge fan of Laila\'s dancing! She\'s such an artist! Everyone agrees that she is a child prodigy. It\'s undeniable! Unfortunately, she\'s also famous for not signing autographs. Promise if you ever get one, you\'ll give it to me!"' },
