    ['Maxine'] = { zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit H-8' },
    ['Mayakov'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Lion Springs Tavern', 'San d\'Oria (S)' }, location = 'Lion Springs Tavern', note = 'Involved in Missions:\n* WOTG04: The Queen of the Dance\n* WOTG05: While the Cat is Away\n* WOTG06: A Timeswept Butterfly\n* WOTG07: Purple, The New Black\n* WOTG08: In the Name of the Father\n* WOTG09: Dancers in Distress\n* WOTG14: A Nation on the Brink\n* WOTG16: Sandswept Memories\n\nNotes:\nThe flamboyant, lisping leader of Troupe Mayakov. He along with his dancing troupe arrived in San d\'Oria for a performance at the Lion Springs Tavern during the Crystal War. He appears to wield a Joyeuse in battle.' },
