    ['Mhabi Molkot'] = { type = 'Conflict Director', zones = { 'Heavens Tower', 'Windurst' }, location = 'Heavens Tower', note = 'Involved in Quests:\n* Getting a Ballista License\n\nNotes:\nGives information regarding Ballista. Will also, if asked, give you a Ballista Earring (Key Item)' },
    ['Mhabi Molkot (A)'] = { zones = { 'Abyssea', 'Abyssea - Tahrongi' }, location = 'Abyssea - Tahrongi', note = 'Notes:\nTalk: Can\'t figure out those ministry types out for the life of me. I don\'t care what you\'rrre studyin\', it can\'t be more important than the lives of your friends! My Terrible Tigresses... I hope they\'re alrrright...' },
