    ['Miageau'] = { type = 'Quest Giver NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria L-7, at entrance to the Cathedral', note = 'Starts Quests:\n* Waters of the Cheval' },
