    ['Michaela'] = { type = ': Circuit NPCs', zones = { 'Chocobo Circuit' }, location = 'Chocobo Circuit H-10', note = 'Notes:\n* A representative of the CRA, Michaela issues the stands for display of trophies. *The stands available are the CS Bronze Stand, the CS Gold Stand and the CS Mythril Stand. *Michaela will also engrave the stand if required, or trade the trophy and stand for an engraved plaque.' },
    ['Michea'] = { type = 'Quest Giver', zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets F-10 2nd floor house on right', note = 'Starts Quests:\n* The Elvaan Goldsmith\n\nInvolved in Quests:\n* Father Figure\n* Distant Loyalties\n* The First Meeting\n\nInvolved in Missions:\n* Bastok Mission 1-3: Fetichism\n* Bastok Mission 9-2: Where Two Paths Converge\n* The Voracious Resurgence #2: The Brygid Cup' },
