    ['Midras'] = { type = 'Quest NPC', zones = { 'Bastok', 'Cutscene', 'Western Adoulin, Sih Gates, Yorcia Weald' }, location = 'Western Adoulin, Sih Gates, Yorcia Weald', note = 'Involved in Quests:\n* Vegetable Vegetable Revolution\n* Vegetable Vegetable Evolution\n* Vegetable Vegetable Crisis\n* Vegetable Vegetable Frustration\n\nNotes:\n* Cid\'s son. *Referred to as "Junior" by Amchuchu.' },
    ['Miene'] = { type = 'Quest Giver NPC', zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria I-9', note = 'Involved in Quests:\n* Flyers for Regine\n* The Pickpocket' },
    ['Mieuseloir B Enchelles'] = { type = 'Campaign Hero NPC', zones = { 'Battle', 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) L-6', note = 'Notes:\nAppears during offensive Campaign Battles as the leader of the Crimson Wolf Esquires. *Mieuseloir appears to be a Dark Knight/Paladin, who wields Ragnarok. **Melee attacks have a constant Endrain, sapping between 50-100 HP from his enemies. **Has access to Black Magic: Aspir, Drain, all Absorb- spells, Stun and Dread Spikes. **Has access to White Magic: Protect IV, Shell IV, Holy, Banish III and Cure IV. **Uses all Sword WS\'s including Savage Blade. ***Uses the unique weapon skill Cruel Riposte, which drains an enormous amount of HP from his enemy. **Uses Blood Weapon. **Uses Shield Bash. *Mieuseloir appears several times in the Vana\'diel Tribune in the stories of Joseaneaut\'s Mission. He is referred to as the leader of the "Red Wolves" in A Heroic Gigas, which undoubtedly is the same as the Crimson Wolves of the Crystal War.' },
    ['Mighty Fist'] = { type = 'Quest Giver', zones = { 'Bastok', 'Metalworks, Darksteel Forge' }, location = 'Metalworks, Darksteel Forge (G-9)', note = 'Starts Quests:\n* The Darksmith\n\nInvolved in Quests:\n* Dark Legacy' },
