    ['Mihl Pakorhma'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S)', note = 'Involved in Quests:\n* The Tigress Stirs\n* The Tigress Strikes\n* Knot Quite There\n* A Manifest Problem\n* The Long March North\n* Howl from the Heavens\n* Manifest Destiny\n* At Journey\'s End' },
    ['Mihli Aliapoh'] = { type = 'Serpent General', zones = { 'Al Zahbi' }, location = 'Al Zahbi H-7, 2nd floor', note = 'Involved in Quests:\n* Soothing Waters\n\nNotes:\n* Mihili Aliapoh is one of five Serpent Generals defending Al Zahbi during Besieged. She holds the title of Waterserpent General and is a Mithra White Mage. *She must be in Al Zahbi in order to complete the quest Soothing Waters. If she is held prisoner, the quest cannot be completed until she is rescued.' },
