    ['Miliart, T.K.'] = { type = 'Sigil NPC - San d\'Oria National Campaign Guard', zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) L-10', note = 'Notes:\n:*Casts Sigil :*Sells items for Allied Notes (San d\'Oria Campaign Items) at certain conditions. :*Explains the Campaign system by choosing some available questions. :*Tells you the remaining time on your current Sigil effect. For further information see Campaign Arbiter.' },
