    ['Mog Dinghy'] = { type = 'Transportation', zones = { '*Mog Garden *Port San d\'Oria' }, location = '*Mog Garden *Port San d\'Oria I-8 *Port Bastok K-11 *Port Windurst C-8', note = 'Notes:\n* Mog Garden: Provides access to Western Adoulin, Eastern Adoulin, and the area from which Mog Garden was entered. *Port San d\'Oria / Port Bastok /Port Windurst: Provides access to Mog Garden if the player is eligible' },
