    ['Mokto-Lankto, W.W.'] = { type = 'Conquest Overseer', zones = { 'Pashhow Marshlands', 'Windurst' }, location = 'Pashhow Marshlands K-6', note = 'Notes:\nAppears, when Derfland is under weekly conquest-control by Windurst. ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Derfland Supplies for finishing Supply Quest :*Accepts Garrison starting item Silver Engraving ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Mokyokyo'] = { type = 'Windurst Gate Guard', zones = { 'Windurst', 'Windurst Waters map = North|F-5' }, location = 'Windurst Waters map = North|F-5', note = 'Starts Missions:\n* Windurst Missions\n\nNotes:\n* If you accept your first Windurst mission from her, you will receive the title \'Fresh "North Winds" Recruit.\'' },
    ['Mololo'] = { type = 'Guild Merchant', zones = { 'Mhaura' }, location = 'Mhaura G-9 (Blacksmiths\' Guild Salesroom)', note = 'Notes:\n: Open always. :No longer shares stock with Kamilah. :Stock is the same selection as Lucretia and Vicious Eye offers. :Never runs out of stock. :Prices are static.' },
    ['Molting Moth, I.M.'] = { type = 'Conquest Overseer - Bastok Outland Conquest Guard', zones = { 'Bastok', 'Outland', 'West Ronfaure' }, location = 'West Ronfaure F-12', note = 'Notes:\nAppears, when Ronfaure is under weekly conquest-control by Bastok ;Notes for characters only with Bastok as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts Ronfaure Supplies for finishing Supply Quest ;Notes for characters only without Bastok as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Momiji'] = { zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno I-6', note = 'Notes:\nTo anyone who listens to her, Momiji recounts her youth spent with her lover, whom she describes as a shy, quiet boy. She will then remark that it is only the perspective of old age that has taught her the importance of love. Then, she will mention that her husband is well: so full of life that she doesn\'t know what to do. It is implied that her husband is not her remembered lover, and that she regrets a decision of her youth. She wears Maat\'s Cap, a hat which is also worn by Degenhard (and which is awarded to any player who defeats Maat in every job.) Articles in the Vana\'diel Wind have described Maat and Degenhard as long-time rivals who once trained at the same dojo. Perhaps Mojimi is Maat\'s wife; perhaps Degenhard is the lost lover of her youth (although both Maat and Degenhard could be described as "full of life.")' },
    ['Momoroon'] = { type = 'Auction House (Nashmau)', zones = { 'Nashmau' }, location = 'Nashmau G-7' },
    ['Momowa'] = { zones = { 'Campaign battles', 'Freelance' }, location = 'Campaign battles', note = 'Notes:\n*  May assist Rongo-Nango during campaign battles.' },
    ['Monberaux'] = { zones = { 'Jeuno', 'Upper Jeuno map = Infirmary|G-10' }, location = 'Upper Jeuno map = Infirmary|G-10', note = 'Involved in Quests:\n* The Lost Cardian\n* Regaining Trust\n* Save the Clock Tower\n* The Kind Cardian\n\nInvolved in Missions:\n* Bastok Mission 3-3: Jeuno\n* Windurst Mission 3-3: A New Journey\n* San d\'Oria Mission 3-3: Appointment to Jeuno\n* Promathia Mission 1-1: The Rites of Life\n* Promathia Mission 3-5: Darkness Named\n* Promathia Mission 5-3: Three Paths\n* The Pursuit of Paradise (Tenzen\'s Path)\n\nNotes:\nAccording to Professor Emanritan, this is a very classy Elvaan name.' },
    ['Monberaux (A)'] = { zones = { 'Abyssea', 'Abyssea - Attohwa' }, location = 'Abyssea - Attohwa H-8' },
    ['Moniquaurie'] = { type = 'Cutscene NPC', zones = { 'Abyssea', 'Jugner Forest' }, location = 'Jugner Forest', note = 'Starts Quests:\n* The Beast of Bastore' },
    ['Monisette'] = { zones = { 'Jeuno', 'Port Jeuno' }, location = 'Port Jeuno I-8', note = 'Notes:\n*  Stores chapters of Rem\'s Tale 1-10 for players. You may trade multiple types of chapters all at once to store them in one transaction. * Upgrades Artifact Armor/Artifact Armor +1 to Reforged Artifact Armor (Item Level 109). * Upgrades Reforged Artifact Armor to Reforged Artifact Armor +1 (Item Level 119). * Upgrades Relic Armor/Relic Armor +1 to Reforged Relic Armor (Item Level 109). * Upgrades Reforged Relic Armor to Reforged Relic Armor +1 (Item Level 119). * Upgrades Empyrean Armor to Reforged Empyrean Armor (Item Level 109). * Upgrades Reforged Empyrean Armor to Reforged Empyrean Armor +1 (Item Level 119). * When upgrading armor, {{PAGENAME' },
    ['Mono Nchaa'] = { type = 'Standard Merchant', zones = { 'Nchaa\'s Good Goods - Windurst Woods', 'Windurst' }, location = 'Nchaa\'s Good Goods - Windurst Woods H-13' },
