    ['Moogle (A)'] = { zones = { 'Abyssea', 'Abyssea - Uleguerand Third Outpost' }, location = 'Abyssea - Uleguerand Third Outpost', note = 'Starts Quests:\n* Home, Home on the Range' },
    ['Moogle (Let\'s Go! Vana\'diel Day! 12)'] = { zones = { 'Special Event' } },
    ['Moogle (Mog House)'] = { type = 'MHMU worker', zones = { 'Adoulin', 'Al Zahbi', 'Bastok', 'Bastok (S)', 'Jeuno', 'Mog House', 'San d\'Oria', 'San d\'Oria (S)', 'Windurst', 'Windurst (S)' }, location = 'Mog House', note = 'Starts Quests:\n* Give a Moogle a Break\n* Moogles in the Wild\n* The Moogle\'s Picnic!\n\nInvolved in Quests:\n* Unexpected Treasure\n\nStarts Missions:\n* A Moogle Kupo d\'Etat\n* Drenched! It Began with a Raindrop\n* Hasten! In a Jam in Jeuno?\n* Welcome! To My Decrepit Domicile\n* Shock! Arrant Abuse of Authority\n* Lender Beware! Read the Fine Print\n* Rescue! A Moogle\'s Labor of Love\n* Relief! A Triumphant Return\n\nInvolved in Missions:\n* Burgeoning Dread\n\nNotes:\n* This moogle is present in your Mog House and Rent-a-Rooms as a housekeeper. He can change your Main Job and Support Job, check your Delivery Box, access your Mog Safe, Mog Locker, Storage, and Mog Satchel, change the Layout of your furniture, and manage your Gardening. :*These services are only available at the five major nations and Campaign barracks. In smaller towns, you\'ll need to speak with Nomad Moogles. *Speaking to him will confirm the status of your Moghancement auras. *Your moogle also plays an important role in A Moogle Kupo d\'Etat storyline.' },
    ['Moogle (NM)'] = { zones = { 'Battle' } },
