    ['Moogle Gatherer'] = { zones = { '* (2011) Ghelsba Outpost' }, location = '* (2011) Ghelsba Outpost (G-8) * (2011) Palborough Mines Map 1 (I-8)(Opposite side from the Elevator lever) * (2011) Giddeus (H-7)', note = 'Involved in Quests:\n* Moogle\'s Largesse Mini-quest' },
