    ['Moreno-Toeno'] = { type = 'Quest Giver NPC', zones = { 'Windurst', 'Windurst Waters map = North|L-6, in the Aurastery' }, location = 'Windurst Waters map = North|L-6, in the Aurastery', note = 'Starts Quests:\n* Teacher\'s Pet\n\nInvolved in Missions:\n* Windurst Mission 2-2: A Testing Time\n* Windurst Mission 8-1: Vain\n\nNotes:\nMoreno-Toeno is a teacher of the Aurastery. He participates in one quest and two missions, all regarding matters with the Aurastery. He speaks in alliterations, just as fluidly as Shantotto speaks in rhyme.' },
