    ['Morimar'] = { type = 'Mission NPC', zones = { 'Cutscene', 'Leafallia', 'Outland' }, location = 'Leafallia H-8', note = 'Involved in Missions:\n* Darrcuiln (Mission)\n* The Gates\n* Morimar (Mission)\n* A New Force Arises\n* A Shrouded Canopy\n* Leafallia (Mission)\n* Rosulatia\'s Promise\n\nNotes:\n* Former companion of August Adoulin. *Namesake of the Morimar Basalt Fields. *A Noble Warrior.' },
