    ['Movamuq'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Mine Shaft #2716' }, location = 'Mine Shaft #2716', note = 'Involved in Missions:\n* Promathia Mission 5-3: Three Paths\n* Past Sins (Louverance Path)\n* Promathia Mission 8-4: Dawn\n\nNotes:\n* One of Jabbos\' Moblin friends.' },
    ['Moyoyo'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks I-7 - Consulate of Windurst' },
    ['Mrohk Sahjuuli'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate I-11 Lower Floor', note = 'Notes:\nGhanraam will exchange items from Salvage II ruins expeditions and crafting items for pieces of Salvage +1 armor. Mrohk Sahjuuli can also store plans obtained in Salvage II runs. * To upgrade a piece, trade her the plans (if she isn\'t storing them already). Then trade her the other required items at the same time: lv.45 armor piece, the payment (Imp. Pieces), and if you are making a +1 piece from the Salvage (I) Armor, then trade the lv.75 armor piece as well. If doing She will give you the reward immediately, unlike Salvage (I) armor.' },
    ['Muchavatte'] = { zones = { 'Cut scenes only', 'Cutscene', 'San d\'Oria' }, location = 'Cut scenes only', note = 'Involved in Quests:\n* Undying Flames\n\nInvolved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Promathia Mission 4-3: The Secrets of Worship\n\nNotes:\nMuchavatte P Couchiret is the former papsque of the San d\'Orian church. He died of a broken heart after Cardinal Mildaurion, leader of the Tavnavian Cathedral, sabotaged the Temple\'s attempt to discover the location of the Gate of the Gods during the Crystal War. After telling his close friends "I was forced to abandon the truth", he publicly declared the Gate of the Gods was not a physical location but located with the heart shortly before his death, single-handedly reversing thousands of years of dogma. He is buried in the Reliquary. His sussessor\'s name is Shamonde. |' },
    ['Muckvix'] = { zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno H-10', note = 'Involved in Quests:\n* Return to the Depths\n\nInvolved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Maat on the Rampage\n* Not Just a Pretty Face' },
