    ['Mumor'] = { type = 'Event NPC', zones = { 'Northern San d\'Oria', 'Special Event' }, location = 'Northern San d\'Oria F-5 / Bastok Markets (G-8) / Windurst Waters North (F-9)', note = 'Involved in Quests:\n* Heroines\' Holdfast\n\nNotes:\nCurrently touring the land as a top-selling stage performer, Mumor is the only daughter of Professor Sarmoega, undisputed genius inventor and head of the Research Institute for Paranormal Phenomenon (RIPP). Her true identity, however, is that of a superpower-imbued fighter who has received special training specifically in preparation for her destined battle against the evil demon king, Ullegore. With her father\'s miraculous invention, the aptly named "Miracle Wand" in hand, Mumor transforms from an affable if somewhat ungraceful young lady into the irresistibly adorable superheroine, Fantastic Fraulein Mumor. Her claim to fame is the ability to convert the boisterous support of loving fans into a formidable force which, when fully charged, can be used to unleash an ultimate attack against the enemy for massive damage. thumb|Mumor during the 2008 festival' },
    ['Mumupp'] = { zones = { 'Kazham' }, location = 'Kazham J-9', note = 'Involved in Quests:\n* The Opo-opo and I\n\nNotes:\n*  Accepts the Ten of Coins (Card) for The Opo-opo and I.' },
    ['Mumuroon'] = { zones = { 'Nashmau' }, location = 'Nashmau H-9' },
    ['Munitions Moogle'] = { zones = { 'Port Jeuno' }, location = 'Port Jeuno E-6', note = 'Notes:\n* Will return any lost ammunition-generating belt granted as part of augmenting REMA item level 119 ranged weaponry. Will only perform this service once per character. Trade the Moogle the corresponding item to retrieve your belt.' },
    ['Mupia, R.K.'] = { type = 'Conquest Overseer', zones = { 'San d\'Oria', 'Yuhtunga Jungle' }, location = 'Yuhtunga Jungle G-6', note = 'Notes:\nAppears, when Elshimo Lowlands is under weekly conquest-control by San d\'Oria. ;Notes for characters only with San d\'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Elshimo Lowlands Supplies for finishing Supply Quest ;Notes for characters only without San d\'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Muruk-Mojiruk'] = { zones = { 'Adoulin', 'Ceizak Battlegrounds' }, location = 'Ceizak Battlegrounds K-7' },
    ['Musdahl'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate J-8', note = 'Notes:\nGuard at the gate to the place "Way of Devout"' },
    ['Mushayra'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate F-10, on the upper level of Stoneserpent Square, in a covered stall' },
    ['Mushosho'] = { type = 'Outpost Vendor', zones = { 'Meriphataud Mountains', 'Outland' }, location = 'Meriphataud Mountains E-5', note = 'Notes:\nAppears when Aragoneu is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader\'s current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil' },
    ['Mushuhi-Metahi'] = { type = 'Weather Reporter', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods K-12', note = 'Notes:\nChecks weather for the following locations: :* East Sarutabaruta :* West Sarutabaruta :* Tahrongi Canyon :* Buburimu Peninsula :* Meriphataud Mountains' },
    ['Mustafa'] = { zones = { 'Bastok', 'Port Bastok' }, location = 'Port Bastok G-7' },
    ['Musto-Rusto'] = { type = 'Quest Giver NPC', zones = { 'Adoulin', 'Battle', 'Cutscene', 'Mischief Marker at Western Adoulin' }, location = 'Mischief Marker at Western Adoulin (J-11)', note = 'Involved in Quests:\n* All the Way to the Bank\n* To Laugh Is to Love\n* A Barrel of Laughs\n\nNotes:\n* In battle for A Barrel of Laughs, he uses lower-tier enfeebling magic such as Paralyze and Slow.' },
    ['Mutihb'] = { zones = { 'Cut scenes', 'Cutscene' }, location = 'Cut scenes', note = 'Involved in Quests:\n* Luck of the Draw\n* Equipped for All Occasions {{Verification\n\nNotes:\n* Involved in the storyline of the Corsair Job, the Seagull Phratrie and The Ashu Talif.' },
