    ['Myllue, R.K.'] = { type = 'Campaign NPC', zones = { 'Batallia Downs (S)', 'San d\'Oria (S)' }, location = 'Batallia Downs (S) J-7, at the north side of the fort. * This is a different location from where the Campaign Arbiter stands if the region is under beastmen control.', note = 'Notes:\n* San d\'Oria (S) affiliated Campaign Arbiter. Present when San d\'Oria (S) has control of Batallia Downs (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Mystrix'] = { type = 'Gobbie Mystery Box Vendor', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria L-7', note = 'Notes:\n{{GobbieBox' },
    ['Mythily'] = { type = 'Immigration NPC', zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks J-8 Top level, President\'s office, Dept. of Industry', note = 'Notes:\nCost to Change Allegiance When Bastok is in: *1st Place in Conquest - 40,000g *2nd Place in Conquest - 12,000g *3rd Place in Conquest - 4,000g Restrictions: *When changing allegiance, you retain all conquest points. They are inaccessible, though, until you return to your previous nation. *If this is the first time you\'ve switched to this nation, you are reset to Rank 1, 0 conquest points, and no Outposts done. *If you decide later to return to your previous Nation, you will get your previous Rank, conquest points, and Outposts back. *Any rewards for missions done in other nations are retained when you switch (i.e. you will keep your Airship Pass, etc.) *If you are currently on a mission, you are not allowed to change allegiance. *You will keep all Outposts from your old nations. They are inaccessible, though, until you return to your previous nation. :*This only applies to outpost data that was saved to the game on and after the 6/9/2008 patch. Any outpost data saved prior will have to be quested again. GMs have clarified that the reason for this inconvenience is due to previous "thematic" deletions of outpost data from completed supply missions at the time of the allegiance change. Example: A player was allied with San d\'Oria with all outposts complete and changed to Bastok on 5/1/08 and then obtained all outposts again. That player then changes allegiance to Windurst on 6/20/08. All outpost data for San d\'Oria is lost but all outpost data for Bastok is saved.' },
    ['Myuhn Rohli, M.C.'] = { type = 'Campaign NPC', zones = { 'Grauberg (S)', 'Windurst (S)' }, location = 'Grauberg (S) I-8', note = 'Notes:\n* Windurst (S) affliated Campaign Arbiter. Present when Windurst (S) has control of Grauberg (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Myumimi'] = { zones = { 'Windurst', 'Windurst Waters map = South|H-8' }, location = 'Windurst Waters map = South|H-8' },
    ['Nabihwah'] = { type = 'Imperial Standing', zones = { 'Nashmau' }, location = 'Nashmau H-6', note = 'Notes:\n:*Casts Sanction on registered mercenaries (w/ Sanction Enhancements) :*Recharges Chariot Band, Emperor Band, or Empress Band. :*Sells items for Imperial Standing at appropriate rank. :*Explains Sanction, Imperial Standing, and Besieged system by choosing some available questions.' },
    ['Nachou'] = { zones = { 'Chateau d\'Oraguille', 'San d\'Oria' }, location = 'Chateau d\'Oraguille H-8' },
    ['Nachou (A)'] = { type = 'Quest NPC', zones = { 'Abyssea', 'Abyssea - Uleguerand' }, location = 'Abyssea - Uleguerand G-9 in the tunnels', note = 'Involved in Quests:\n* Slip Sliding Away' },
    ['Nadee Periyaha'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate H-9 Serpentking Square', note = 'Involved in Quests:\n* Rat Race\n\nNotes:\n"Well, I guess you came to the right lady!" "I\'m the closest thing you\'ll get to a Qiqirn without the beady eyes, red nose, pot belly, and mysterious fanny pack." "Not that I\'m proud of it or anything..."' },
    ['Nadeeha'] = { zones = { 'Nashmau' }, location = 'Nashmau', note = 'Notes:\n* This NPC is currently not found in Nashmau, if the NPC does not exist (anymore), please update and remove accordingly.' },
    ['Nadeey'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate K-7', note = 'Involved in Quests:\n* Soothing Waters\n\nInvolved in Missions:\n* Aht Urhgan Mission 4: Knight of Gold\n* Aht Urhgan Mission 28: Bastion of Knowledge\n* Reunited\n\nNotes:\nNadeey will replace your Treasures of Aht Urhgan mission ring if you discard your current ring, then speak to Nadeey for a cutscene, giving you a choice of the three again. You need not wait for conquest tally between dropping the ring and obtaining your first replacement, but if you want to change rings again, you must wait for the conquest tally.' },
    ['Nafiwaa'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate G-5 - Alchemist\' Guild', note = 'Involved in Quests:\n* Promotion: Lance Corporal' },
    ['Nag\'molada'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Jeuno', 'Ru\'Lude Gardens' }, location = 'Ru\'Lude Gardens', note = 'Involved in Quests:\n* Apocalypse Nigh\n\nInvolved in Missions:\n* Promathia Mission 1-1: The Rites of Life\n* Promathia Mission 1-2: Below the Arks\n* Promathia Mission 1-3: The Mothercrystals\n* Promathia Mission 2-1: An Invitation West\n* Promathia Mission 2-2: The Lost City\n* Promathia Mission 2-3: Distant Beliefs\n* Promathia Mission 2-4: An Eternal Melody\n* Promathia Mission 2-5: Ancient Vows\n* Promathia Mission 3-2: Vessel Without a Captain\n* Promathia Mission 3-4: Tending Aged Wounds\n* Promathia Mission 4-2: The Savage\n* Promathia Mission 5-1: The Enduring Tumult of War\n* Promathia Mission 5-2: Desires of Emptiness\n* Promathia Mission 5-3: Three Paths\n* The Pursuit of Paradise (Tenzen\'s Path)\n* Promathia Mission 6-1: For Whom the Verse is Sung\n* Promathia Mission 6-2: A Place to Return\n* Promathia Mission 6-4: One to be Feared\n* Promathia Mission 7-5: The Warrior\'s Path\n* Promathia Mission 8-1: The Garden of Antiquity\n* Promathia Mission 8-2: A Fate Decided\n* Promathia Mission 8-3: When Angels Fall\n\nNotes:\nNag\'molada is a diplomat for the Duchy of Jeuno, and a member of the Armathrwn Society. In the time of the Great War, he was employed by the Archduke as a special envoy to the other three nations, and assisted in the formation of the Allied Forces of Altana. He has an exceptional grasp of strategy and is highly skilled in negotiations.' },
    ['Nag\'molada (S)'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Jeuno (S)' }, note = 'Involved in Quests:\n* Downward Helix (SCH AF2)\n* Seeing Blood-red (SCH AF3)\n\nInvolved in Missions:\n* A Spoonful of Sugar (WOTG11)\n* Borne by the Wind (WOTG13)\n* A Nation on the Brink (WOTG14)\n* Crossroads of Time (WOTG15)\n\nNotes:\nA member of the Armathrwn Society, serving as an agent of Archduke Kam\'lanaut during the Crystal War. He spearheaded an investigation into the mass disappearances of numerous military scholars.' },
    ['Naguipeillont, R.K.'] = { type = 'Conquest Overseer', zones = { 'San d\'Oria', 'West Sarutabaruta' }, location = 'West Sarutabaruta H-6', note = 'Notes:\nAppears, when Sarutabaruta is under weekly conquest-control by San d\'Oria. ;Notes for characters only with San d\'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Sarutabaruta Supplies for finishing Supply Quest :*Accepts Garrison starting item Seven-Knot Quipu ;Notes for characters only without San d\'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Naho Gwanboh'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S)', note = 'Involved in Quests:\n* A Feast for Gnats\n* The Long March North\n* Howl from the Heavens\n* Manifest Destiny\n\nNotes:\n* Appears during cutscenes as the leader of the Cheetah Volunteers that have come from the Olzhirya and were funded by the Allied War Council out of Jeuno.' },
    ['Nahshib'] = { type = 'Assault Periqia NPC', zones = { 'Al Zahbi', 'Dvucca Isle Staging Point (Caedarva Mire' }, location = 'Dvucca Isle Staging Point (Caedarva Mire I-9)', note = 'Involved in Quests:\n* Beginnings\n\nInvolved in Missions:\n* Aht Urhgan Mission 2: Immortal Sentries\n* Aht Urhgan Mission 31: Shades of Vengeance\n\nNotes:\n* Speak with him to receive an Assault Armband for assault missions in Periqia.' },
    ['Naih Arihmepp'] = { zones = { 'Windurst', 'Windurst Walls' }, location = 'Windurst Walls F-5', note = 'Involved in Quests:\n* Lure of the Wildcat (Windurst)' },
    ['Naiko-Paneiko'] = { type = 'Quest Giver NPC', zones = { 'Windurst', 'Windurst Waters South' }, location = 'Windurst Waters South (C-11) in the Tarutaru Times, in Gingerberry Grove. Take the road past the Baren-Moren-Hatter, through covered path, left at the fork. Last building.', note = 'Starts Quests:\n* Making Headlines\n* Scooped!\n* The Weekly Adventurer &mdash; see Naiko-Paneiko (S)\n\nInvolved in Quests:\n* Riding on the Clouds\n\nNotes:\nDescribed in Riding on the Clouds as, "A man looking for something snappy to hook his customers."' },
    ['Naiko-Paneiko (S)'] = { type = 'Quest NPC', zones = { 'Crawlers\' Nest (S)', 'Windurst (S)' }, location = 'Crawlers\' Nest (S) L-8', note = 'Starts Quests:\n* The Weekly Adventurer' },
    ['Naillina'] = { zones = { 'Selbina' }, location = 'Selbina F-9', note = 'Starts Missions:\n* RoV 1-1-3 - Set Free' },
    ['Naja Salaheem'] = { type = 'Mission Giver; Quest Giver', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi', 'Battle' }, location = 'Aht Urhgan Whitegate I-10; upstairs', note = 'Starts Quests:\n* Promotion: Private First Class\n* Promotion: Superior Private\n* Promotion: Sergeant\n* Promotion: Sergeant Major\n* Promotion: Second Lieutenant\n* Promotion: First Lieutenant\n\nInvolved in Quests:\n* Lure of the Wildcat (All Nations)\n* Promotion: Lance Corporal\n* Promotion: Captain\n* An Imperial Heist\n* Coming Full Circle\n* Unwavering Resolve\n* Waking the Colossus\n* Lure of the Wildcat:\n* Trade Invitation Cards after completing Immortal Sentries for Imperial Currency:\n* Number of Cards (Reward)\n* One Invitation Cards (Imperial Bronze Piece x 1)\n* Two Invitation Cards (Imperial Bronze Piece x 2)\n* Three Invitation Cards (Imperial Bronze Piece x 3)\n* Four Invitation Cards (Imperial Mythril Piece x 1)\n* Note that Rank 2 for San d\'Orians or advancement to Mission 2-3 for Windurstians and Bastokers is required to enter the Chateau d\'Oraguille. 5 of the NPCs for Lure of the Wildcat quest are there, and thus access to it is required to get the Mythril piece as a reward.\n* Titles Given:\n* Assault Rank 1: Private Second Class\n* Assault Rank 2: Private First Class\n* Assault Rank 3: Superior Private\n* Assault Rank 5: Corporal\n* Assault Rank 6: Sergeant\n* Assault Rank 7: Sergeant Major\n* Assault Rank 8: Chief Sergant\n* Assault Rank 9: Second Lieutenant\n* Assault Rank 10: First Lieutenant\n* Assault Rank 11: Captain\n* Lure of the Wildcat (All Nations): Wildcat Publicist\n* Battle NPC:\n* Naja fights alongside the party in the battle against Amnaf for Aht Urhgan Mission 42: Path of Darkness.\n* Uses Hundred Fists.\n\nStarts Missions:\n* Aht Urhgan Mission 1: Land of Sacred Serpents\n* Aht Urhgan Mission 2: Immortal Sentries\n* Aht Urhgan Mission 3: President Salaheem\n* Aht Urhgan Mission 4: Knight of Gold\n* Aht Urhgan Mission 8: A Mercenary Life\n* Aht Urhgan Mission 9: Undersea Scouting\n* Aht Urhgan Mission 11: Imperial Schemes\n* Aht Urhgan Mission 12: Royal Puppeteer\n* Aht Urhgan Mission 13: Lost Kingdom\n* Aht Urhgan Mission 14: The Dolphin Crest\n* Aht Urhgan Mission 15: The Black Coffin\n* Aht Urhgan Mission 16: Ghosts of the Past\n* Aht Urhgan Mission 17: Guests of the Empire\n* Aht Urhgan Mission 18: Passing Glory\n* Aht Urhgan Mission 19: Sweets for the Soul\n* Aht Urhgan Mission 20: Teahouse Tumult\n* Aht Urhgan Mission 21: Finders Keepers\n* Aht Urhgan Mission 22: Shield of Diplomacy\n* Aht Urhgan Mission 23: Social Graces\n* Aht Urhgan Mission 24: Foiled Ambition\n* Aht Urhgan Mission 25: Playing the Part\n* Aht Urhgan Mission 26: Seal of the Serpent\n* Aht Urhgan Mission 27: Misplaced Nobility\n* Aht Urhgan Mission 28: Bastion of Knowledge\n* Aht Urhgan Mission 29: Puppet in Peril\n* Aht Urhgan Mission 30: Prevalence of Pirates\n* Aht Urhgan Mission 31: Shades of Vengeance\n* Aht Urhgan Mission 32: In the Blood\n* Aht Urhgan Mission 33: Sentinels\' Honor\n* Aht Urhgan Mission 34: Testing the Waters\n* Aht Urhgan Mission 35: Legacy of the Lost\n* Aht Urhgan Mission 36: Gaze of the Saboteur\n* Aht Urhgan Mission 37: Path of Blood\n* Aht Urhgan Mission 38: Stirrings of War\n* Aht Urhgan Mission 39: Allied Rumblings\n* Aht Urhgan Mission 40: Unraveling Reason\n* Aht Urhgan Mission 41: Light of Judgment\n* Aht Urhgan Mission 42: Path of Darkness\n* Aht Urhgan Mission 43: Fangs of the Lion\n* Aht Urhgan Mission 44: Nashmeira\'s Plea\n* Aht Urhgan Mission 45: Ragnarok\n* Aht Urhgan Mission 46: Imperial Coronation\n* Aht Urhgan Mission 47: The Empress Crowned\n* Aht Urhgan Mission 48: Eternal Mercenary\n\nInvolved in Missions:\n* Aht Urhgan Mission 7: Westerly Winds\n* Aht Urhgan Mission 19: Sweets for the Soul\n* Aht Urhgan Mission 21: Finders Keepers\n* Aht Urhgan Mission 23: Social Graces\n* Aht Urhgan Mission 37: Path of Blood\n* Aht Urhgan Mission 38: Stirrings of War\n* Aht Urhgan Mission 42: Path of Darkness\n* Aht Urhgan Mission 47: The Empress Crowned' },
    ['Najaaj'] = { zones = { 'Al Zahbi' }, location = 'Al Zahbi J-8' },
    ['Najelith'] = { type = 'Serpent General', zones = { 'Al Zahbi' }, location = 'Al Zahbi G-8', note = 'Involved in Quests:\n* When the Bow Breaks\n* Soothing Waters\n* Embers of His Past\n\nNotes:\n*  Najelith is one of five Serpent Generals defending Al Zahbi during Besieged. She holds the title Galeserpent General and is a Hume Ranger. *She must be in Al Zahbi in order to complete the quest When the Bow Breaks. If she is held prisoner, the quest cannot be completed until she is rescued.' },
    ['Naji'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks J-8', note = 'Involved in Quests:\n* Riding on the Clouds\n* The Doorman\n* Trust: Bastok\n* Adventurer Appreciation Campaign 2010\n\nInvolved in Missions:\n* Bastok Mission 1-1: The Zeruhn Report\n* Bastok Mission 2-3: The Emissary\n* Bastok Mission 3-1: The Four Musketeers\n* Bastok Mission 5-1: Darkness Rising\n* Bastok Mission 6-2: The Pirates\' Cove\n* Bastok Mission 9-2: Where Two Paths Converge\n* Promathia Mission 3-1: Call of the Wyrmking\n* Aht Urhgan Mission 38: Stirrings of War\n* Aht Urhgan Mission 39: Allied Rumblings\n* Aht Urhgan Mission 40: Unraveling Reason\n* Aht Urhgan Mission 41: Light of Judgment\n* A Crystalline Prophecy (Mission)\n* The Voracious Resurgence #2: The Brygid Cup\n\nNotes:\n*  Naji is an important part of the Bastok Missions. * He is a member of the Mythril Musketeers. * Ranks at number five in the Mythril Musketeer hierarchy. In spite of being among Bastok\'s five most elite soldiers, Naji is usually given menial tasks and is often the target of teasing from his comrades. Their comments are referenced in Riding on the Clouds where his description is, "Bastok\'s number five \'doorman\'." *Son of Yasin.' },
    ['Naji (A)'] = { zones = { 'Abyssea - Konschtat' }, location = 'Abyssea - Konschtat J-5', note = 'Starts Quests:\n* Playing Paparazzi\n\nInvolved in Quests:\n* Secret Agent Man\n\nNotes:\n* ' },
    ['Najib'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'Jeuno', 'Port Jeuno' }, location = 'Port Jeuno I-10' },
    ['Najjar'] = { zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria K-6', note = 'Involved in Quests:\n* Under Oath' },
    ['Nakho Jawantal'] = { zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno G-10' },
    ['Nalba-Dalaba'] = { zones = { 'Crawlers\' Nest (S)', 'Windurst (S)' }, location = 'Crawlers\' Nest (S) F-8', note = 'Notes:\n"...Ever since the Federal Forces took over the storerooms for their operations, my business has become a literal casualty of war.And the fields are being trompy-stomped from the battles with turtlemen. What\'s an honestaru merchant to do?"' },
    ['Nalpupu'] = { type = 'Cage Teleporter', zones = { 'Pankration', 'The Colosseum' }, location = 'The Colosseum J-7' },
    ['Nalta'] = { zones = { 'Appears in the capital city of the nation ranked first in conquest (does not show up when there is a tie for first) :*In San d\'Oria: Southern San d\'Oria', 'Bastok', 'San d\'Oria', 'Windurst' }, location = 'Appears in the capital city of the nation ranked first in conquest (does not show up when there is a tie for first) :*In San d\'Oria: Southern San d\'Oria (I-9) :*In Windurst: Windurst Woods (H-10) :*In Bastok: Port Bastok (K-8)' },
    ['Nambima-Hyonbima'] = { type = 'Quest NPC', zones = { 'Bastok', 'Cutscene', 'Cutscenes' }, location = 'Cutscenes', note = 'Involved in Quests:\n* Bait and Switch\n* Chameleon Capers\n\nNotes:\n* One of Miledo-Shiraddo\'s costumes. Wears shades with a robe.' },
    ['Namonutice'] = { type = 'Reputation NPC', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria K-6, in the Lion Springs Tavern' },
    ['Namonutice (A)'] = { type = 'Reputation NPC', zones = { 'Abyssea', 'Abyssea - La Theine' }, location = 'Abyssea - La Theine E-3' },
    ['Nanaa Mihgo'] = { zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods J-3', note = 'Starts Quests:\n* Mihgo\'s Amigo\n* Rock Racketeer\n* THF AF1: The Tenshodo Showdown\n* THF AF2: As Thick as Thieves\n* THF AF3: Hitting the Marquisate\n\nInvolved in Quests:\n* Lure of the Wildcat (Windurst)\n* Trust: Windurst\n* Crying Over Onions\n\nInvolved in Missions:\n* Windurst Mission 2-1: Lost for Words\n* Roar! A Cat Burglar Bares Her Fangs\n\nNotes:\nWhile not common knowledge, Nanaa\'s parentage is rather distinguished. She is the daughter of two of the more famous adventurers in Windurst\'s history. Her mother is none other than former Chieftainess and Mercenary Major Romaa Mihgo. Her father is the war hero and military tactician Lehko Habhoka. Yet despite the fame of her parents, Nanaa has carved out her own life as the infamous "Cat Burglar" of Windurst. Her "antics" are known throughout the world, yet she somehow still manages to find home in Windurst. She left Kazham in anger after Romaa picked Jakoh Wahcondalo as her successor. Despite her penchant for troublemaking, it is perhaps because of her political connections that the Windurstian authorities don\'t bother her as she is allowed to run her "business" without interference.' },
    ['Nanaa Mihgo (A)'] = { zones = { 'Abyssea', 'Abyssea - Altepa' }, location = 'Abyssea - Altepa D-12' },
    ['Nanaroon'] = { type = 'Auction House (Nashmau)', zones = { 'Nashmau' }, location = 'Nashmau G-7 - 2nd Floor' },
    ['Nangst'] = { zones = { 'Bastok', 'Bastok Mines' }, location = 'Bastok Mines G-6' },
    ['Nantoto'] = { type = 'Quest NPC', zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno H-8', note = 'Starts Quests:\n* Teleports by Twilight\n* Shifty Shades of Prey\n* Petals of Recollection\n* To Kill Mocking Birds' },
    ['Naravime'] = { zones = { 'Jeuno', 'Port Jeuno' }, location = 'Port Jeuno H-7' },
    ['Narcheral'] = { type = 'Quest Giver NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria M-6, in the Cathedral upstairs', note = 'Starts Quests:\n* Messenger from Beyond\n* Prelude of Black and White\n* Pieuje\'s Decision' },
    ['Nareema'] = { type = 'Assault Azouph Isle NPC', zones = { 'Al Zahbi', 'Azouph Isle Staging Point (Caedarva Mire' }, location = 'Azouph Isle Staging Point (Caedarva Mire K-9)', note = 'Involved in Quests:\n* Beginnings\n\nInvolved in Missions:\n* Immortal Sentries\n* Azure Experiments\n\nNotes:\n* Speak with her to receive an Assault Armband for assault missions in Leujaoam Sanctum. Quote: "Blue...muddies the purest waters." "It is the mark of the blue mage..." "You and I..." "The color of our blood...our souls...the same..." "I cannot bear it... Cannot..." "I was free..." "You have lost your freedom..." "Leave me be... I cannot bear it..."' },
    ['Narihira'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno', note = 'Involved in Quests:\n* A Clock Most Delicate\n\nNotes:\nGalmut\'s boss and friend, previous clock tower engineer.' },
    ['Narito-Pettito'] = { zones = { 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) F-8 - North' },
    ['Narkissa, C.A.'] = { type = 'Campaign NPC', zones = { 'Bastok Markets (S)', 'Jeuno (S)' }, location = 'Bastok Markets (S) E-8', note = 'Notes:\n* Jeuno affliated Campaign Arbiter. *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign *She cannot teleport you to Beastman Strongholds (Castle Oztroja (S), La Vaule (S), Beadeaux (S), Castle Zvahl Baileys (S), Castle Zvahl Keep (S), Throne Room (S))' },
    ['Narsaude'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria G-8', note = 'Notes:\n"Only the honorable may serve San d\'Oria in all her glory. We don\'t need vagabonds watering down our ranks." "Finish your business, and get out of our city!"' },
    ['Narsha'] = { zones = { 'Jeuno', 'Port Jeuno' }, location = 'Port Jeuno J-8' },
    ['Naruru'] = { zones = { 'Jeuno', 'Lower Jeuno 1st level inside Merchant\'s House' }, location = 'Lower Jeuno 1st level inside Merchant\'s House (H-10)', note = 'Involved in Quests:\n* Lure of the Wildcat (Jeuno)\n* Cook\'s Pride' },
    ['Naruru (A)'] = { zones = { 'Abyssea', 'Abyssea - Attohwa' }, location = 'Abyssea - Attohwa G-10', note = 'Starts Quests:\n* For Want of a Pot\n\nInvolved in Quests:\n* Family Ties' },
    ['Narvecaint'] = { zones = { 'La Theine Plateau', 'San d\'Oria' }, location = 'La Theine Plateau F-7 at the entrance of Ordelle\'s Caves.', note = 'Involved in Quests:\n* A Timely Visit\n\nInvolved in Missions:\n* San d\'Oria Mission 2-1: The Rescue Drill' },
    ['Nasheefa'] = { type = 'Map Giver', zones = { 'Al Zahbi', 'Caedarva Mire' }, location = 'Caedarva Mire E-11', note = 'Notes:\n* Grants access to Alzadaal Undersea Ruins for One Imperial Silver Piece.' },
    ['Nashmeira'] = { type = 'Cutscene NPC', zones = { 'Al Zahbi', 'Cutscene', 'Imperial Ward' }, location = 'Imperial Ward', note = 'Starts Quests:\n* Forging a New Myth\n\nInvolved in Quests:\n* Saga of the Skyserpent\n* Soothing Waters\n* Coming Full Circle\n* Waking the Colossus\n* Divine Interference\n* The Rider Cometh\n* Unwavering Resolve\n* A Stygian Pact\n\nInvolved in Missions:\n* Aht Urhgan Mission 11: Imperial Schemes\n* Aht Urhgan Mission 12: Royal Puppeteer\n* Aht Urhgan Mission 18: Passing Glory\n* Aht Urhgan Mission 19: Sweets for the Soul\n* Aht Urhgan Mission 20: Teahouse Tumult\n* Aht Urhgan Mission 21: Finders Keepers\n* Aht Urhgan Mission 23: Social Graces\n* Aht Urhgan Mission 28: Bastion of Knowledge\n* Aht Urhgan Mission 29: Puppet in Peril\n* Aht Urhgan Mission 30: Prevalence of Pirates\n* Aht Urhgan Mission 32: In the Blood\n* Aht Urhgan Mission 34: Testing the Waters\n* Aht Urhgan Mission 35: Legacy of the Lost\n* Aht Urhgan Mission 36: Gaze of the Saboteur\n* Aht Urhgan Mission 37: Path of Blood\n* Aht Urhgan Mission 39: Allied Rumblings\n* Aht Urhgan Mission 43: Fangs of the Lion\n* Aht Urhgan Mission 44: Nashmeira\'s Plea\n* Aht Urhgan Mission 45: Ragnarok\n* Aht Urhgan Mission 47: The Empress Crowned\n\nNotes:\nEmpress of Aht Urhgan, 16th ruler of the Majaab Dynasty. Nashmeira proclaims herself to be the Empire--the very embodiment of the nation. She is rarely seen in public; however, her militaristic statements are the cause of much concern for Aht Urhgan\'s neighboring countries. Ignoring the views of her advisors, Nashmeira has recently ordered a large-scale recruitment of mercenaries to deal with the barbaric races inhabiting the lands that surround the Imperial capital. ([http://www.playonline.com/ff11us/ahturhgan/index.html Official ToAU Site])' },
    ['Nashu'] = { type = 'Cutscene NPC', zones = { 'Adoulin', 'Eastern Adoulin (residence)' }, location = 'Eastern Adoulin (residence)', note = 'Involved in Quests:\n* Thorn in the Side\n* Velkkovert Operations' },
