    ['Nikki'] = { zones = { 'Jeuno', 'Port Jeuno' }, location = 'Port Jeuno H-9' },
    ['Nikkoko'] = { type = 'Synthesis Image Support NPC :*Clothcraft Guild', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods G-12', note = 'Notes:\n* Nikkoko is one of two workers who provides free synthesis support for clothcrafting in Windurst. Speaking with her will raise your clothcrafting skill ever so slightly, and give you a better chance at successful synths. After speaking with her however, you may not ask any other NPC for synthesis support until the one she has given you has worn away.' },
