    ['Noble Warrior'] = { type = 'Battle NPC', zones = { 'Battle', 'Cirdas Caverns (U)', 'Outland' }, location = 'Cirdas Caverns (U)', note = 'Notes:\n* Assists the player in The Gates. *Uses Into the Light, 12 Blades of Remorse, Vehement Resolution, Camaraderie of the Crevasse, and Arduous Decision. *His true identity is Morimar.' },
    ['Nogelle'] = { type = 'Quest Giver NPC', zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria G-7, in the Rusty Anchor Pub', note = 'Starts Quests:\n* Lufet\'s Lake Salt' },
