    ['Odoba'] = { type = 'Guild Merchant (Alchemy)', zones = { 'Bastok', 'Bastok Mines' }, location = 'Bastok Mines K-6', note = 'Notes:\n* Open: Always. *No longer shares stock with Maymunah, and prices are static. *Has much higher stock limits than Maymunah, but can be depleted. *Stock is replenished over time, and everything is restocked.' },
    ['Odzmanouk'] = { type = 'Freelance', zones = { 'Battle', 'Campaign battles', 'Freelance' }, location = 'Campaign battles', note = 'Notes:\n* Transformed version of Areuhat in battle. Players that complete the Areuhat quest ?Beast from the East? can subsequently trade to a Scouted Areuhat a Shell Bug, and cause her to take flight as Odzmanouk during Campaign Battles. *Primarily uses Hurricane Wing on surrounding opponents. Also uses Spike Flail on opponents behind her.' },
