    ['Ovjang'] = { type = 'Cutscene NPC', zones = { 'Al Zahbi', 'Cutscene', 'Imperial Ward' }, location = 'Imperial Ward', note = 'Starts Quests:\n* An Imperial Heist\n\nInvolved in Quests:\n* Forging a New Myth\n* Coming Full Circle\n* The Rider Cometh\n* Unwavering Resolve\n* A Stygian Pact\n* Divine Interference\n\nInvolved in Missions:\n* Aht Urhgan Mission 11: Imperial Schemes\n* Aht Urhgan Mission 12: Royal Puppeteer\n* Aht Urhgan Mission 18: Passing Glory\n* Aht Urhgan Mission 19: Sweets for the Soul\n* Aht Urhgan Mission 20: Teahouse Tumult\n* Aht Urhgan Mission 21: Finders Keepers\n* Aht Urhgan Mission 29: Puppet in Peril\n* Aht Urhgan Mission 30: Prevalence of Pirates\n* Aht Urhgan Mission 32: In the Blood\n* Aht Urhgan Mission 34: Testing the Waters\n* Aht Urhgan Mission 35: Legacy of the Lost\n* Aht Urhgan Mission 39: Allied Rumblings\n* Aht Urhgan Mission 47: The Empress Crowned\n\nNotes:\nAn automaton belonging to puppetmaster Aphmau along with Mnejing.' },
    ['Owain'] = { zones = { 'Jeuno', 'Tavnazian Safehold' }, location = 'Tavnazian Safehold H-6', note = 'Starts Quests:\n* Tavnazian Terrors\n* Bibiki Bombardment\n\nNotes:\nProvides players with assistance with Voidwatch operations. *Ask a bunch of questions. *Participate in Voidwatch Ops. *Request debriefing. *Request Voidstone. *Check Voidstone stock. *Request reward issuance. - Can purchase the following: **Cobalt Cell: 3,000 Cruor **Rubicund Cell: 3,000 Cruor **Xanthous Cell: 3,000 Cruor **Periapt of Emergence: 50,000 Cruor **Periapt of Guidance: 150,000 Cruor **Periapt of Percipience: 150,000 Cruor **Periapt of Sapience: 50,000 Cruor **Periapt of Clarity: 50,000 Cruor **Beguiling Petrifact: 330,000 Cruor **Seductive Petrifact: 330,000 Cruor **Maddening Petrifact: 330,000 Cruor Can also convert any Voiddust into a Voidstone as long as the player has no Voidstones in their possession, currently.' },
    ['Ozzmo-Mazmo'] = { zones = { 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) F-8 - North' },
    ['Packapic'] = { type = 'Moblin Maze Mongers NPC', zones = { 'Everbloom Hollow', 'Outland' }, location = 'Everbloom Hollow', note = 'Notes:\n* A Moblin Maze Mongers employee who provides player support within the lobby of Everbloom Hollow. Packapic assists players by: *Allowing players to choose from an assortment of sound tracks to listen to while completing maze missions. A wide assortment of tracks are provided free of charge and more desirable tracks can be purchased with Maze Marbles. *Offering a temporary item exchange. Each item can only be used within the maze and must be purchased with Maze Marbles before entering.' },
    ['Pacomart'] = { zones = { 'Selbina' }, location = 'Selbina (H-10)', note = 'Starts Missions:\n* The Beginning\n\nNotes:\nThe Beginning can also be started with Tonasav in Mhaura.' },
