    ['Paito-Maito'] = { zones = { 'Norg' }, location = 'Norg G-6', note = 'Notes:\n"I\'m the gaudy-bodyguard of this place. You make one wrong move and I will smack and kick and punch and whack and pummel and smash and crash and grind your bones into powder...and then kick you some more. You follow the rules, I\'ll let you live. You break them, I break you."' },
    ['Pakeke'] = { zones = { 'Windurst', 'Windurst Walls' }, location = 'Windurst Walls E-6', note = 'Notes:\nDialog: Welcome to the magical town of Windurst. Home of fun-loving Tarutaru and free-willed Mithra. You are now in Windurst Walls. It\'s a holy site revered by us Tarutaru since ancientaru times. I hope you enjoy your visitaru here.' },
