    ['Palardaifault V Draffles'] = { type = 'Survey NPC', zones = { 'San d\'Oria', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) I-9', note = 'Notes:\nArmy Curate for San d\'Oria records opinions of adventurers on matters regarding internal policies, battle strategies and the army\'s generals. The opinions are tallied weekly and influence the available Campaign Ops. The weight of an adventurer\'s opinions is based on their medals.' },
    ['Palarillont'] = { zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno H-8', note = 'Notes:\nDialog: *"Long have I hoarded my gil, and the time for purchase is at hand! But shall I buy weaponry or armor?" *"In offense the best defense may lie, but quickly is the unarmored knight struck down. Hmm... Which to choose..."' },
