    ['Panta-Putta (A)'] = { zones = { 'Abyssea', 'Abyssea - Misareaux Wanders around the whole zone. *Found up at VC#05. *Found down by VC#08. *Found by VC #00' }, location = 'Abyssea - Misareaux Wanders around the whole zone. *Found up at VC#05. *Found down by VC#08. *Found by VC #00', note = 'Notes:\n* The child of Teigero-Bangero (A) in Abyssea - Vunkerl. *Has multiple sayings it will yell that will show in player\'s chatlogs. :"And mommy...where\'s my M-mommy-wommy...?" :"... Wh-where\'s my daddy...?" :"I said, where are you guys!?!? Answer me! Now, now, now!!!"' },
