    ['Parara'] = { zones = { 'Heavens Tower', 'Windurst' }, location = 'Heavens Tower' },
    ['Parcarin'] = { zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria H-10', note = 'Involved in Quests:\n* Lure of the Wildcat (San d\'Oria)\n\nNotes:\nDialogue: Heard the whispers, have you? The beastmen have a new leader. War is preparing! Ah, but any horde of beastmen will break upon these walls like water. Long live King Destin! If quest "Lure of the Wildcat (San d\'Oria)" is active: I hear the town of Al Zahbi, a strategic location in the west of Aht Urhgan, often finds itself surrounded by invading beastman forces... What feeble defenses they must have in the Near East. This is what comes of a nation that does not embrace the path of chivalry. Our heroic knights would make short work of any beastman horde, no matter their number! Long live King Destin!' },
    ['Parcarin (A)'] = { zones = { 'Abyssea', 'Abyssea - Vunkerl Located by base camp near Cavernous Maw' }, location = 'Abyssea - Vunkerl Located by base camp near Cavernous Maw' },
    ['Parelbriaux'] = { zones = { 'Tavnazian Safehold', 'Tavnazian Safehold Upper Level' }, location = 'Tavnazian Safehold Upper Level (K-7)', note = 'Involved in Quests:\n* X Marks the Spot\n* Petals for Parelbriaux\n\nInvolved in Missions:\n* Promathia Mission 2-3: Distant Beliefs\n* Promathia Mission 2-4: An Eternal Melody\n* Promathia Mission 4-3: The Secrets of Worship' },
    ['Parike-Poranke'] = { type = 'Adventurer\'s Assistant - Food Effect Remover', zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno H-8', note = 'Starts Quests:\n* Brown Magic\n\nInvolved in Quests:\n* Expanding Horizons (Limit 7)\n* Beyond the Stars (Limit 8)\n\nNotes:\nthumb|Digestive Magic Skillup by 0,1A Tarutaru mage in Lower Jeuno who is working on a report for the Orastery in Windurst. Parike-Poranke claims to be able to use "Brown magic" in order to cure indigestion. Parike-Poranke is featured in G7, or Expanding Horizons, where he helps the player uncap to 85. He is also mentioned when you remove food effects in the Kokba Hostel in Al Zahbi.' },
    ['Parledaire, R.K.'] = { type = 'Conquest Overseer - San d\'Oria Outpost Conquest Guard', zones = { 'Beaucedine Glacier', 'Outland', 'San d\'Oria' }, location = 'Beaucedine Glacier H-9', note = 'Notes:\nAppears, when Fauregandi is under weekly conquest-control by San d\'Oria ;Notes for characters only with San d\'Oria as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Fauregandi Supplies for finishing Supply Quest :*Accepts Garrison starting item Tiger Leather Missive ;Notes for characters only without San d\'Oria as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Parlemaille'] = { zones = { 'Norg' }, location = 'Norg H-9', note = 'Notes:\n"The jungle that covers this island is so big, it\'s divided into two--the Yhoator Jungle and the Yuhtunga Jungle. I wouldn\'t recommend traveling without a map, since you could get lost, or...eaten. Remember, it\'s a jungle out there. Har har! Get it?' },
