    ['Paujean'] = { zones = { 'Bastok', 'Port Bastok' }, location = 'Port Bastok F-6 - Bottom floor of Warehouse 2', note = 'Starts Quests:\n* Silence of the Rams\n\nInvolved in Quests:\n* Lure of the Wildcat (Bastok)' },
