    ['Petva'] = { zones = { 'Jeuno', 'Ru\'Lude Gardens' }, location = 'Ru\'Lude Gardens H-8', note = 'Notes:\nDialog: *"Sir Nag\'molada often speaks with the common people of the duchy. I even heard that promotions are granted to those who happen to impress him." *"I wonder if he will ever stop to speak with me... What would I say?"' },
    ['Pevovo'] = { type = 'Standard Merchant NPC', zones = { 'Yahse Hunting Grounds' }, location = 'Yahse Hunting Grounds K-9' },
    ['Pew Sahbaraef'] = { type = 'Item Deliverer', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods J-12', icon = 'Deliverer.png' },
    ['Phairet'] = { zones = { 'San d\'Oria', 'West Ronfaure' }, location = 'West Ronfaure I-11', note = 'Involved in Quests:\n* The Trader in the Forest\n\nNotes:\nThis NPC sells Batagreens, but not in the style of the Standard Merchant. You must trade him 50 gil each and every time you require a single Batagreens. If you trade more than that, he\'ll still only take 50 and give you one. You must first start the quest "The Trader in the Forest" before he will accept your purchase.' },
    ['Phairupegiont'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria H-8', note = 'Involved in Quests:\n* Lure of the Wildcat (San d\'Oria)\n\nNotes:\nDialogue: Ever heard of the Brugaire Consortium? They\'re the largest trading company in San d\'Oria, with merchants traveling as far as Jeuno. The vast cargo rooms down at the port belong to them, you know. If quest "Lure of the Wildcat (San d\'Oria)" is active: Yes, I know of the badge you wear. I was in the port when the Brugaire Consortium was unloading a large shipment of the things. I wonder if even the Brugaire Consortium goes too far, sometimes. This strange foreign cargo will land them in deep water with the Temple Knights, you mark my words.' },
