    ['Porlco-Glaico'] = { zones = { 'Fort Karugo-Narugo (S)' }, location = 'Fort Karugo-Narugo (S) K-6' },
    ['Poroggo Prince'] = { zones = { 'Freelance', 'Windurst Waters (S) map = Northern|H-10' }, location = 'Windurst Waters (S) map = Northern|H-10', note = 'Notes:\n"Ribbit! Ribbit!" *Appears in campaign battle if the Poroggo Servant is successfully influenced. *Uses assorted black magic *Assisted by 3 Poroggo Servants *After using Providence, he will use the extra spells including Death and Breakga. *Frog Cheer will affect all players and other allied forces in range. Maruna-Kurina\'s Notes: Fanciful-wanciful fairy tales about a frog princess have been passed down in Windurst since days of eld. Some say the newcome prince of these froglike beastmen has been seen leaping and bounding about the frontlines of battle. No doubt the figment of some delusional soldier\'s imagination, but still... Folklore always spoke of their insatiable-watiable appetites, and now soldiers would tell that feeding them will actually help win them to our cause. ?Give him Lufaise flies,? they say, ?and the frog prince will requite!? I can\'t make heads or tails of it... N-n-not thataru I bother myself with such childish topics!' },
    ['Poroggo Servant'] = { zones = { '*West Sarutabaruta (S)', 'Freelance' }, location = '*West Sarutabaruta (S) (F-4) *Windurst Waters (S) North (H-10)', note = 'Notes:\n:*Influenced by trading a Lufaise Fly. :*To be able to trade additional Lufaise Flies, you will have to zone into nearby Windurst Waters (S) and back out. :*When allied, the Poroggo Prince and several servants will fight in campaign battles. :*Servants use no TP moves or cast spells, but attack fast and have Additional Effect: Weight on their melee attacks.' },
    ['Portaure'] = { type = 'Quest Giver NPC', zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria H-9, in Cargo Room B', note = 'Starts Quests:\n* A Job for the Consortium\n\nInvolved in Quests:\n* Flyers for Regine\n* Mirror, Mirror' },
    ['Porter Moogle'] = { zones = { '*Lower Jeuno' }, location = '*Lower Jeuno I-6 *Northern San d\'Oria K-8 *Bastok Markets I-9 *Port Windurst L-6 *Tavnazian Safehold F-8 *Aht Urhgan Whitegate I-11 *Selbina *Mhaura *Rabao G-8 *Kazham H-9 *Norg G-7 *Nashmau H-6 *Southern San d\'Oria (S) M-5 *Bastok Markets (S) H-7 *Windurst Waters (S) map=North|L-10 *Western Adoulin H-11 *Mog Garden', note = 'Notes:\nFind a nearby Porter Moogle and talk to him and select the option to buy a Slip. Once you find the slip you want you select it and confirm your selection. Each slip will cost you 1000 gil to buy. After purchasing any storage slip, you may trade 1-7 corresponding items per trade along with the slip. NOTE: This does NOT mean you can only store up to 7 items on a single slip, it simply means you can only transfer up to 7 at a time to the Porter for storage. At any time after you have the slip you can continue to make trades of 1-7 items along with the corresponding slip, thereby storing all your like items with the Moogle instead of in your MH. This feature is handy when you later get another armor drop, like in Dynamis, and want to store it somewhere until you need it. To withdraw an item simply trade him the corresponding slip and he will give you an option to retrieve your armor. You only pay an initial fee of 1,000 gil when purchasing a storage slip, you will not pay every time you store or withdraw gear. Storage slips cannot be discarded unless all stored items are retrieved first. As of Feb. 14, 2011, items with a Magian Trial insignia can no longer be stored with a Porter Moogle. Any items with an active trial stored before that date have had all trial progress erased.' },
    ['Portia'] = { type = 'Mission NPC', zones = { 'Cutscene', 'San d\'Oria (S)' }, note = 'Involved in Missions:\n* WOTG05: While the Cat is Away\n* WOTG06: A Timeswept Butterfly\n* WOTG07: Purple, The New Black\n* WOTG08: In the Name of the Father\n* WOTG09: Dancers in Distress\n* WOTG11: A Spoonful of Sugar\n* WOTG14: A Nation on the Brink\n* WOTG16: Sandswept Memories\n* WOTG17: Northland Exposure\n* WOTG18: Traitor in the Midst\n* WOTG19: Betrayal at Beaucedine\n* WOTG22: A Sanguinary Prelude\n* WOTG23: Dungeons and Dancers\n* WOTG25: The Will of the World\n\nNotes:\n* Portia Fonteyn is a member of Troupe Mayakov.' },
    ['Porupen-Kyurupen'] = { zones = { 'Windurst', 'Windurst Waters map = North|H-9' }, location = 'Windurst Waters map = North|H-9' },
    ['Poseaulloie'] = { type = 'Special Event NPC', zones = { 'Patrols set route in Northern San d\'Oria', 'San d\'Oria' }, location = 'Patrols set route in Northern San d\'Oria I-8 > J-8 > I-9 > J-9 through the Parade Ground shown on the map, north of the exit to South San d\'Oria.', note = 'Notes:\n* One of The Dark Lilies of the Harvest Festival event held each October since 2004. Follow Poseaulloie without being seen to receive, from the Exorcist, a Witch Hat or Coven Hat. *Thought to be the Dark Kindred\'s Shadowhand from the Crystal War when the The Dark Lilies were enslaved by the Shadow Lord.' },
