    ['Pulonono'] = { type = 'VCS Chocobo Trainer', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods K-12, Chocobo Stables', note = 'Notes:\nA member of the Vana\'diel Chocobo Society. She will help you raise your own Chocobo if you trade an egg to her.' },
    ['Pulse Martello'] = { zones = { 'Abyssea', 'near Veridical Conflux #00 in: :Abyssea - Attohwa' }, location = 'near Veridical Conflux #00 in: :Abyssea - Attohwa (F-8) :Abyssea - Misareaux (I-8) :Abyssea - Vunkerl (I-9)', note = 'Notes:\nThese martellos can be found near the military camps at Conflux #00 in Scars of Abyssea areas. Pulse Martellos are associated with Bastion, being the cornerstone of the resistance effort and under constant attack by enemy hordes intent on their destruction. Adventurers may aid in their defense by speaking to Bastion Prefects to receive Pennant status and engage in battle, or may undertake Resistance Ops by talking to nearby Resistance Sappers to aid in strengthening the martellos and the defenses surrounding them. Pulse Martellos can be buffed with Protect, Shell, and Embrava spells, as well as Earthen Ward and other Blood Pact: Wards. Pulse Martellos do receive the benefits of these statuses. Unlike other Martellos in Abyssea, Pulse Martellos cannot be used by adventurers to regain health, and are not affected by area quests given by Machine Outfitters.' },
    ['Pulykiki'] = { zones = { 'Windurst', 'Windurst Waters map = South|E-5' }, location = 'Windurst Waters map = South|E-5' },
