    ['Purere (A)'] = { type = 'Quest NPC', zones = { 'Abyssea', 'Abyssea - Uleguerand Third Outpost' }, location = 'Abyssea - Uleguerand Third Outpost', note = 'Involved in Quests:\n* Imperial Espionage' },
    ['Puroiko-Maiko, W.W.'] = { type = 'Conquest Overseer - Windurst National Conquest Guard', zones = { 'Windurst', 'Windurst Waters map = North|G-5' }, location = 'Windurst Waters map = North|G-5', note = 'Notes:\n;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts traded Crystals for filling up the Windurst Mission-Rank bar (the red bar at the character\'s profile) :*Sells items for Conquest Points (Items for Windurst) at certain conditions. It will be also possible to get some items of other Nations (Items for Bastok / Items for San d\'Oria) at the guards, if your current Allegiance ranks higher at the weekly Conquest results (for further information see under the items articles) :*Starts Supply Run Missions and offers a list of already delivered supplies :*Starts an Expeditionary Force by giving an E.F. region insignia to you :*Explains the Conquest system by choosing some available questions. ;Notes for characters only without Windurst as current Allegiance: :*Doesn\'t offer any function For further information see Conquest Overseer.' },
    ['Purottoto'] = { zones = { 'Fort Karugo-Narugo (S)' }, location = 'Fort Karugo-Narugo (S) K-10' },
    ['Pursuivant'] = { zones = { '::Ru\'Lude Gardens', 'Al Zahbi', 'Bastok', 'Jeuno', 'Outland', 'San d\'Oria', 'Windurst' }, location = '::Ru\'Lude Gardens (I-8) ::Windurst Waters North (J-9) ::Port Bastok (J-12) ::Northern San d\'Oria (K-9) ::Aht Urhgan Whitegate (G-11) ::Abdhaljs Isle-Purgonorgo (H-7), (H-8) ::Diorama Abdhaljs-Ghelsba (F-7), (G-6), (G-10)', note = 'Notes:\nPursuivants offer information about the game Ballista and can give the upcoming match schedules; they are also able to warp characters to the specific Ballista or Brenner battle areas. When a player chooses to warp back at camp after a death, a specific Pursuivant of your current allegiance (San\'dorian, Bastokan, or Windurstian Pursuivant) will offer a Ballista Earring or a Ballista Band, when you talk to him. The Pursuivant in Abdhaljs Isle-Purgonorgo will warp players back to Upper Jeuno. The Pursuivants in Diorama Abdhaljs-Ghelsba will warp players back to Ru\'Lude Gardens.' },
    ['Putori-Tutori'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'The Sanctuary of Zi\'Tah' }, location = 'The Sanctuary of Zi\'Tah', note = 'Involved in Quests:\n* Mandau\n\nInvolved in Missions:\n* The Scent of Battle\n\nNotes:\n* One of the members of the Hydra Corps. *Younger brother of Atori-Tutori.' },
