    ['Ragelise'] = { type = 'Mission NPC', zones = { 'Cutscene', 'San d\'Oria (S)' }, note = 'Involved in Missions:\n* WOTG04: The Queen of the Dance\n* WOTG05: While the Cat is Away\n* WOTG06: A Timeswept Butterfly\n* WOTG07: Purple, The New Black\n* WOTG08: In the Name of the Father\n* WOTG09: Dancers in Distress\n* WOTG11: A Spoonful of Sugar\n* WOTG14: A Nation on the Brink\n* WOTG20: On Thin Ice\n* WOTG25: The Will of the World\n\nNotes:\n* Sir Ragelise B Baloumat is the captain of the Knights of the Ironcrest Hawk. His order attempted to assist the Knights of the Madder Falcon in retaking La Vaule from the Orcish Hosts.' },
    ['Ragemont'] = { type = 'Cutscene NPC', zones = { 'Abyssea', 'La Theine Plateau' }, location = 'La Theine Plateau', note = 'Starts Quests:\n* A Goldstruck Gigas' },
    ['Raghd'] = { type = 'Standard Merchant', zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets J-8 - Carmelide\'s Jewelry' },
    ['Raging Lion'] = { type = 'Adventurer\'s Assistant', zones = { 'Jeuno', 'Port Jeuno' }, location = 'Port Jeuno H-8', note = 'Notes:\nProvides Airship schedule information for Bastok.' },
    ['Raging Tiger'] = { zones = { 'Selbina' }, location = 'Selbina I-10', note = 'Notes:\n* Guard at the entrance of Selbina port' },
    ['Raginmund'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) L-10', note = 'Involved in Quests:\n* Too Many Chefs\n* (This NPC is only present when there is no Campaign Battle.)\n\nNotes:\n"I hear lots of people saying they wish they hadn\'t been born to witness such dark and troubled days. But I, for one, am glad I\'m alive to witness this war. Undoubtedly there are hardships to be endured, but this is a heroic battle that will surely live on in our histories! I would count myself blessed to be able to see it through to completion!"' },
    ['Ragyaya'] = { zones = { 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) E-9 - North' },
    ['Rahal'] = { type = 'Quest NPC', zones = { 'Chateau d\'Oraguille', 'San d\'Oria' }, location = 'Chateau d\'Oraguille H-9 Royal Knight\'s Qtrs', note = 'Starts Quests:\n* Knight Stalker\n\nInvolved in Quests:\n* Lure of the Wildcat (San d\'Oria)\n* The Holy Crest\n\nInvolved in Missions:\n* San d\'Oria Mission 8-2: Lightbringer\n* San d\'Oria Mission 9-2: The Heir to the Light\n* Aht Urhgan Mission 5: Confessions of Royalty\n* The Voracious Resurgence: Altennia Burns Bright\n\nNotes:\n* Rahal S Lebrart is the leader of the Royal Knights. His past involves some shady characters, but his heart is pure. He is widely regarded for his knowledge of most things military (from the training of knights to ancient orders) and his awareness of the goings on within the nation\'s holdings.' },
    ['Rahal (A)'] = { type = 'Quest NPC', zones = { 'Abyssea', 'Veridical Conflux #01 Abyssea - Vunkerl' }, location = 'Veridical Conflux #01 Abyssea - Vunkerl (F-4)', note = 'Starts Quests:\n* Whither the Whisker\n\nNotes:\n* In Abyssea, Rahal is the commander of the Resistance Forces located in Abyssea - Vunkerl.' },
    ['Rahal (S)'] = { zones = { 'Cutscene', 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S)', note = 'Involved in Quests:\n* Gifts of the Griffon\n* Claws of the Griffon\n* Boy and the Beast\n* Wrath of the Griffon\n* Perils of the Griffon\n* In a Haze of Glory\n\nNotes:\n* Excenmille\'s second in command of the Young Griffons.' },
    ['Rahdjab'] = { zones = { 'Al Zahbi', 'Battle', 'Leujaoam Sanctum' }, location = 'Leujaoam Sanctum', note = 'Involved in Missions:\n* Red Versus Blue' },
    ['Rahi Fohlatti'] = { zones = { 'Rabao' }, location = 'Rabao G-9', note = 'Starts Quests:\n* Trial Size Trial by Wind\n\nNotes:\nWill warp main-job Summoners to Cloister of Gales if traded the Mini Tuning Fork of Wind while Trial Size Trial by Wind is open. Most SMNs never complete this quest so that a permanent warp to Cloister of Gales is available. She will also provide a new mini fork at any time if the old one was dropped.' },
    ['Raibaht'] = { zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks G-8 - Cid\'s Lab', note = 'Starts Quests:\n* Hyper Active\n* Teak Me to the Stars\n* The Naming Game\n* Dark Legacy\n\nInvolved in Quests:\n* Lure of the Wildcat (Bastok)\n* The Usual\n* Riding on the Clouds\n* Vegetable Vegetable Crisis\n* Vegetable Vegetable Frustration\n\nInvolved in Missions:\n* Bastok Mission 1-2: A Geological Survey\n* Bastok Mission 7-1: The Final Image\n\nNotes:\n*  Cid\'s assistant * Friend to Hilda\'s late husband, Sirius. He often visits their restaurant, the "Steaming Sheep". * Described in Riding on the Clouds as, "A man so quiet, his boss is ready to call him "Silent Mountain"."' },
    ['Raibaht (A)'] = { zones = { 'Abyssea', 'Abyssea - Konschtat' }, location = 'Abyssea - Konschtat I-13 (Main Entrance Camp)', note = 'Starts Quests:\n* Of Malnourished Martellos\n\nInvolved in Quests:\n* Hope Blooms on the Battlefield' },
