    ['Red Canyon (S)'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) H-4', note = 'Notes:\n"Port Bastok is strictly off-limits to all but authorized personnel. However, if you wish to travel to North Gustaberg, you may use the Republic\'s supply causeway. Cross the bridge?"' },
    ['Red Ghost'] = { type = 'Quest NPC', zones = { 'Jeuno', 'Port Jeuno' }, location = 'Port Jeuno G-8', note = 'Involved in Quests:\n* Unlisted Qualities (See also: Adventuring Fellow Personality)\n* Lure of the Wildcat (Jeuno)' },
    ['Red Ghost (A)'] = { zones = { 'Abyssea', 'Abyssea - Attohwa' }, location = 'Abyssea - Attohwa H-8', note = 'Notes:\n* Used to get to the Field Encampment for the first time. Simply talk to him, then he will teleport you above the ledge to Alrauverat.' },
    ['Red Rose Condottiere'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'San d\'Oria (S)', 'Vunkerl Inlet (S)' }, location = 'Vunkerl Inlet (S)', note = 'Notes:\n*  Appears during Campaign Battles as part of the Knights of the Red Rose squadron, under the command of the Samurai Noillurie. They are only deployed to Vunkerl Inlet (S) * Like their Savage Hound Condottie counterparts they are an all female unit. * Although they wear several Dark Knight only pieces of armor they have not been observed to use any form of magic. * Though they use great axes, they seem to be samurai like their commander, as they possess the Demon Killer trait.' },
    ['Rediroq'] = { type = 'Moblin Maze Mongers NPC', zones = { 'Everbloom Hollow', 'Outland' }, location = 'Everbloom Hollow', note = 'Notes:\n* Rediroq warps players and their party members into the ordered maze from the lobby of Everbloom Hollow.' },
    ['Reelarik'] = { zones = { 'Everbloom Hollow (Inside maze area)' }, location = 'Everbloom Hollow (Inside maze area)', note = 'Involved in Quests:\n* Aquatic Depopulation Team\n\nNotes:\nRewards points for fish and monsters caught during the fishing competition when using Maze Voucher 08.' },
    ['Reet'] = { type = 'Adventurer\'s Assistant', zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets G-8', note = 'Notes:\nOffers General Information and a Map of Bastok: :I am charged with the task of assisting novice adventurers. What would you like to know? :*"How do I give items to people?": Giving items ot other people is called "trading." It is done by selecting "Trade" from the main menu on the right. You must target the person either before or after selecting "Trade." Then just choose the items you wish to give the person when your inventory window appears. "Trading" is crucial to completing quests and missions, and also during conquests. Remember it well. If you have an Adventurer Coupon in your possession, use "Trade" now to give it to me. I will hand you some starting gil in return. Come to me if there is anything more you would like to know. :*"Where can I fight monsters?": Before you take on any fiends, there are a few things you should remember. First, always have weapons and armor equipped, and spells memorized from scrolls. Second, always "check" your target before engaging it. Never take on a foe that seems too strong for you to defeat alone. Third, when you are in a party, make it a habit to cast lots fro your share of the party "spoils" after successfully defeating a monster. Come to me if there is anything more you would like to know. :*"What are quests and missions?": Some people in town will ask you to do certain taks for them. These are called "quests." Complete them, and they should reward you for your efforts. There are also tasks you can do for your country, know as "missions." There is a guard at each gate charged with assigning them. Speak to the guards for more details. Come to me if there is anything more you would like to know. :*"I want to see a map of the city.": [Displays an overview map of Bastok] :*"Nothing for now.": Come to me if there is anything more you would like to know.' },
