    ['Republic Supplier'] = { type = 'Campaign Battle NPC', zones = { 'Bastok (S)', 'Battle', 'Varies' }, location = 'Varies', note = 'Notes:\n* Appears during an offensive campaign against Beastman territories. Up to 3 suppliers may be present at a time. *Distributes temporary items to players allied with Bastok in the battle. *Upon the depletion of their stock, these distributors will temporarily return to headquarters in order to replenish their stores. *They will take defensive action against aggressors, but during that time they will be unable to dispense items. Should they become incapacitated in the course of battle, a replacement will be dispatched after a certain amount of time has elapsed. *Item availability and quantity is directly influenced by each nation\'s skill and production levels.' },
    ['Republican Infantry'] = { zones = { 'Bastok', 'Ruhotz Silvermines' }, location = 'Ruhotz Silvermines', note = 'Involved in Missions:\n* Brave Dawn I (Bastok), Brave Dawn II (Bastok), Brave Dawn III (Bastok)' },
    ['Resauchamet'] = { type = 'Fomor Hate NPC', zones = { 'Tavnazian Safehold' }, location = 'Tavnazian Safehold K-7, On the upper level', note = 'Notes:\n:Provides information about a character\'s Fomor Hate level. :"You are an adventurer... I can smell the dark blood of the undead as it drips slowly from your soiled garments. Beware, my friend, for you are not alone in your journey. Lost spirits lurk in the shadows behind you, waiting for their chance to rob you of your soul. Hmmm..." :1) "You still have a fairly good head start, but they will not let up until they have found you and filled your heart with poison and pain.? ::Fomors will not aggro. :2) ?They are close, It is only a matter of time before you have fallen within their reach." ::Fomors will aggro. :3) "Can you not feel the hands that reach up from the bottomless depths of hell? Can you not feel the gaze of a thousand eyes, glowing red with anger and hate?" ::Fomors will aggro. :4) "The grip of evil is tightening on the very essence of what makes you who you are. Be forewarned, as it will not be long before you are confronted with a battle for more than just your life." ::Fomors will aggro. "Oh, poor child! May the light of the Dawn Goddess lead you from the pitch-black depths of darkness!"' },
    ['Resistance Fighter'] = { zones = { 'Abyssea', 'Abyssea - Attohwa' }, location = 'Abyssea - Attohwa', note = 'Involved in Quests:\n* Looking for Lookouts\n\nNotes:\n* There are 5 different Resistance Fighters located around Parradamo Tor.' },
    ['Resistance Sapper'] = { zones = { 'Abyssea', 'Veridical Conflux 00 :Abyssea - Attohwa' }, location = 'Veridical Conflux 00 :Abyssea - Attohwa (G-8) :Abyssea - Misareaux (I-7) :Abyssea - Vunkerl (I-9)', note = 'Starts Quests:\n* Resistance Ops' },
    ['Resistance Sergeant'] = { zones = { 'Abyssea', 'Abyssea - Attohwa' }, location = 'Abyssea - Attohwa G-10 Abyssea - Misareaux (?-?) Abyssea - Vunkerl (?-?)', note = 'Notes:\n* Provides players with information about the resistance outpost status and the likelihood of Abyssean horde invasions.' },
    ['Retto-Marutto'] = { type = 'Guild Merchant NPC: Bonecraft Guild *Open: 24 hours. *No longer closed Windsday. *No longer shares stock with Shih Tayuun, and prices are static. *Has much higher stock limits than Shih Tayuun, but can be depleted. *Stock is replenished over time.', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods H-12' },
