    ['Rokor-Makor'] = { type = 'Event Sideshow NPC', zones = { 'Special Event', 'Windurst Woods' }, location = 'Windurst Woods K-12', note = 'Notes:\n* Durning Sunbreeze, allows you play a chocobo catch game. You must have earned the HQ gear from the main event to participate in hard mode (for chance to earn a Green Prize Balloon). *During Starlight, allows you to play a job guessing game, basically a version of the board game Mastermind.' },
