    ['Rolf'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) G-5', note = 'Notes:\n"This here\'s a useful chocobo as you\'ll ever see. Capable of anything from battle mount to messenger chocobo!"' },
    ['Romaa Mihgo'] = { zones = { 'Kazham' }, location = 'Kazham H-11', note = 'Involved in Quests:\n* Tuning Out\n* Everyone\'s Grudging\n\nInvolved in Missions:\n* Windurst Mission 7-2: Awakening of the Gods\n\nNotes:\n* The mother of Nanaa Mihgo, Romaa was the former Cobra Mercenary Major during the Crystal War, as well as the former chieftainness of Kazham. *She waits patiently for her love (Lehko Habhoka) to return' },
    ['Romaa Mihgo (A)'] = { zones = { 'Abyssea', 'Abyssea - Uleguerand - First Outpost' }, location = 'Abyssea - Uleguerand - First Outpost (K-9)', note = 'Notes:\nWhen the Abyssean Hordes attacked the mainland, Romaa Mihgo set forth from Kazham to aid in the defense effort. Her outpost is just south of Veridical Conflux #5.' },
    ['Romaa Mihgo (S)'] = { zones = { 'Battle', 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) G-11', note = 'Involved in Quests:\n* The Tigress Stirs\n* The Tigress Strikes\n* Knot Quite There\n* A Manifest Problem\n* When One Man Is Not Enough\n* A Feast for Gnats\n* The Long March North\n* Sins of the Mothers\n* Howl from the Heavens\n* At Journey\'s End\n\nInvolved in Missions:\n* WOTG02: Back to the Beginning\n* WOTG14: A Nation on the Brink\n* WOTG15: Crossroads of Time\n\nNotes:\n* Leader of the Cobra Unit of the Mithra Mercenaries during the Crystal War. Presents medals awarded to adventurers aligned with her Cobra Unit after successful evaluations.' },
