    ['Royal Banneret'] = { zones = { 'Battle', 'Belfry', 'San d\'Oria (S)' }, location = 'Belfry', note = 'Notes:\n* Spawned by an Allied Belfry erected by the Royal Army of San d\'Oria. Participates in offensive Campaign Battles. A maximum of 5 reinforcements will appear, and they will continually respawn unless the belfry is demolished. *They will immediately charge to the Fortifications and attack any defenders they encounter.' },
    ['Royal Esquire'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Belfry', 'San d\'Oria (S)' }, location = 'Belfry', note = 'Notes:\n* Spawned by an Allied Armored Belfry erected by the Royal Army of San d\'Oria. Participates in offensive Campaign Battles. A maximum of 5 reinforcements will appear, and they will continually respawn unless the belfry is demolished. *They will immediately charge to the Fortifications and attack any defenders they encounter.' },
    ['Royal Garrison'] = { zones = { 'Everbloom Hollow', 'San d\'Oria' }, location = 'Everbloom Hollow', note = 'Involved in Missions:\n* Granite Rose I (San d\'Oria)\n* Granite Rose II (San d\'Oria)' },
    ['Royal Guard'] = { zones = { 'Battle', 'East Ronfaure (S)', 'San d\'Oria (S)' }, location = 'East Ronfaure (S)', note = 'Notes:\n* Under the command of General Valaineral R Davilles. *They are among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once San d\'Oria regains most territory in their cordon.' },
    ['Royal Knight'] = { zones = { 'Battle', 'Jugner Forest (S), East Ronfaure (S), Batallia Downs (S).', 'San d\'Oria (S)' }, location = 'Jugner Forest (S), East Ronfaure (S), Batallia Downs (S).', note = 'Notes:\n* Utilizes Weapon Skills: Fast Blade, Circle Blade, Shining Blade, Red Lotus Blade (Possibly others yet to be observed.). *Utilizes Spells: Banish II (Possibly others yet to be observed.).' },
    ['Royal Palliator'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'San d\'Oria (S)', 'Southern San d\'Oria (S), East Ronfaure (S), Jugner Forest (S), Vunkerl Inlet (S), The Eldieme Necropolis (S), Batallia Downs (S)' }, location = 'Southern San d\'Oria (S), East Ronfaure (S), Jugner Forest (S), Vunkerl Inlet (S), The Eldieme Necropolis (S), Batallia Downs (S)', note = 'Notes:\n* Appears in Campaign battles along with another dispatched unit (except the Gold Badger Esquire) in areas under San d\'Orian control; they never appear as a standalone unit. *They will cast Blink, Phalanx, Stoneskin, Raise, and up to Protect IV, Shell IV, and Cure V on Campaign NPCs, anyone with Allied Tags on, and Beastmaster pets. Their spells seem to be on a timer, similar to Pixies. **The selection of spells they\'ll cast is dependent on conditions of the Royal Army of San d\'Oria. Their capabilities can be augmented by doing the Cut and Cauterize (S) campaign ops. *They will not attack unless attacked. When attacked, he\'ll draw his hammer and start attacking the aggressor. This will often happen in battles with monsters that use AoE attacks (such as Battle Dance). *Has a finite MP pool, as of such will actually be seen in the Command/heal stance to recover MP and HP. You will often see them /heal after all Campaign mobs nearby are defeated and Campaign still continues because another wave is on the way. Because they are San d\'Oria, their MP pool is smaller than those of the physicians of Windurst and Bastok (but have higher HP as a result). *In the event that the unit they arrived with retreats, they will remain on the battlefield and not retreat, remaining to assist anyone nearby and to fight if attacked. *Low defense and HP compared to other Royal Army units, as of such they wont last long when attacked. *Uses an ability called Goddess\'s Shield; this enables them to cast self-targeting spells like Blink and Phalanx on allied targets.' },
    ['Royal Provisioner'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'San d\'Oria (S)', 'Varies' }, location = 'Varies', note = 'Notes:\n* Appears during offensive campaigns against Beastman territories. Up to 3 provisioners may be present at one time. *Distributes temporary items to players allied with San d\'Oria in the battle. *Upon the depletion of their stock, they temporarily return to headquarters to replenish their stores. *They take defensive action against aggressors, but during that time they cannot dispense items. If incapacitated, a replacement is dispatched after some time has passed. *Item availability and quantity is directly influenced by each nation\'s skill and production levels.' },
    ['Rubahah'] = { type = 'Standard Merchant', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate F-9', note = 'Involved in Quests:\n* Led Astray' },
    ['Rudolfo'] = { zones = { 'Rabao' }, location = 'Rabao J-7', note = 'Involved in Quests:\n* Chasing Dreams' },
    ['Ruediger, I.M.'] = { type = 'Campaign NPC', zones = { 'Bastok (S)', 'Garlaige Citadel (S)' }, location = 'Garlaige Citadel (S) I-6', note = 'Notes:\n* Bastok affiliated Campaign Arbiter. Present when Bastok (S) has control of Garlaige Citadel (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Ruenda'] = { zones = { 'Bastok', 'Port Bastok' }, location = 'Port Bastok E-7', note = 'Involved in Missions:\n* The Brygid Cup' },
    ['Rughadjeen'] = { type = 'Serpent General', zones = { 'Al Zahbi' }, location = 'Al Zahbi G-7', note = 'Involved in Quests:\n* Saga of the Skyserpent\n* When the Bow Breaks\n* Fist of the People\n* Soothing Waters\n* Embers of His Past\n\nNotes:\n* Rughadjeen is one of five Serpent Generals defending Al Zahbi during Besieged. He holds the title Skyserpent General, the leader of the five Serpent Generals, and is an Elvaan Paladin. *Rughadjeen\'s double bladed sword is an Algol, and it is rumored the very same Algol that was once wielded by the great hero Balrahn. *He must be in Al Zahbi in order to complete the quest Saga of the Skyserpent. If he is held prisoner, the quest cannot be completed until he is rescued. Historical Background: His name may be derived from the Arabic word, Mujahideen (???????), meaning "strugglers." Considering his job, it befits him.' },
    ['Rugiette'] = { zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria J-8, in Regine\'s Magicmart', note = 'Involved in Quests:\n* Riding on the Clouds\n* Lure of the Wildcat (San d\'Oria)\n\nNotes:\nDescribed in Riding on the Clouds as, "A shopkeeper who longs for customers that want more than scrolls of Stone."' },
