    ['Rungaga'] = { type = 'VCS Chocobo Racing Associate', zones = { 'Chocobo Circuit - Windurst Entrance', 'Windurst' }, location = 'Chocobo Circuit - Windurst Entrance', note = 'Notes:\n* Provides information about Chocobo Racing, and recruits adventurers for the CRA Windurst team.This NPC used to be in Windurst Woods (K-12) prior to the 9/9/10 patch.' },
    ['Runito-Monito'] = { type = 'Standard Merchant', zones = { 'Mhaura' }, location = 'Mhaura H-8 - Upstairs in the Sailors\' Stay inn', note = 'Notes:\nSells:: *Cat Baghnakhs 106 - 225 *Brass Baghnakhs 1,554 *Brass Dagger 855 - 967 *Bronze Rod 92 - 104 *Brass Rod 634 - 717 *Brass Xiphos 3,601 - 4,071 *Claymore 2,502 - 2,828 *Butterfly Axe 618 - 698 *Dart 9 - 10 *Wooden Arrow 3 - 4 *Bone Arrow 4 - 5 *Crossbow Bolt 5 - 6' },
    ['Runje Desaali'] = { zones = { 'Adoulin', 'Cutscene', 'Eastern Adoulin' }, location = 'Eastern Adoulin J-10', note = 'Notes:\n* Sells High-purity Bayld for 10,000 bayld apiece. **You must ask her about Geosuke before this service is available. **Purchasing 100 H-P Bayld in one transaction nets you a free pinch of H-P Bayld. *Provides bayld in exchange for {{Rare|nc' },
