    ['Saradorial'] = { type = 'Goldfish Scooping Vendor', zones = { 'Outland', 'Special Event', 'West Ronfaure' }, location = 'West Ronfaure G-10', note = 'Notes:\nAppears when the special event Sunbreeze Festival is active. :*Sells Super Scoops and buys items of characters :*Gives goldfish scooping points for trading special event-caught fish :*Can give you a Goldfish Basket, but you lose any accumulated goldfish scooping points :*Exchanges prizes for goldfish scooping points :*Unwillingly tells players about the goldfish universe For detailed information on fish, prices and other things related to this event, see Goldfish Scooping. ;Items sold: *Super Scoop 100gil' },
