    ['Saunders, C.A.'] = { type = 'Campaign NPC', zones = { 'Castle Zvahl Baileys (S)', 'Jeuno (S)' }, location = 'Castle Zvahl Baileys (S) J-8', note = 'Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of Castle Zvahl Baileys (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Savae E Paleade'] = { zones = { 'Metalworks', 'San d\'Oria' }, location = 'Metalworks I-9', note = 'Involved in Missions:\n* Journey Abroad' },
    ['Savage Hound Condottiere'] = { zones = { 'East Ronfaure (S), Jugner Forest (S). Vunkerl Inlet (S), Batallia Downs (S), The Eldieme Necropolis (S).', 'San d\'Oria (S)' }, location = 'East Ronfaure (S), Jugner Forest (S). Vunkerl Inlet (S), Batallia Downs (S), The Eldieme Necropolis (S).', note = 'Notes:\n*  Under the command of the elvaan general Leonoyne. * Interestingly they are clad in several Dark Knight only armor pieces but have not been observed to cast any form of magic. *They are among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once San d\'Oria regains most territory in their cordon. *Although they appear on screen as Savage Hound Condottie they are actually Savage Hound Condottiere, however with insufficient room in the name space their names are displayed incorrectly in game on sight unless targeted.' },
    ['Sawyer'] = { type = 'Standard Merchant', zones = { 'Bastok', 'Port Bastok' }, location = 'Port Bastok E-6 - Steaming Sheep Restaurant' },
    ['Sazahlam'] = { type = 'Red Command Platform Guard', zones = { 'Pankration', 'The Colosseum' }, location = 'The Colosseum H-7' },
    ['Scamplix'] = { type = 'Standard Merchant', zones = { 'Rabao' }, location = 'Rabao F-7' },
    ['Scarlet Boar Esquire'] = { zones = { 'Battle', 'East Ronfaure (S), Jugner Forest (S), Vunkerl Inlet (S), Batallia Downs (S), The Eldieme Necropolis (S).', 'San d\'Oria (S)' }, location = 'East Ronfaure (S), Jugner Forest (S), Vunkerl Inlet (S), Batallia Downs (S), The Eldieme Necropolis (S).', note = 'Notes:\n* Appears during Campaign Battles , following Ashmea B Greinner. *Appear to be Warriors though wielding Polearms, similar to the Crimson Wolf Esquires.' },
    ['Scarlette, C.A.'] = { type = 'Campaign NPC', zones = { 'Jeuno (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) H-9', note = 'Notes:\n* Jeuno affliated Campaign Arbiter. *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign *You are only allowed Teleportation to areas that you have physically visited. * Costs: ** 20 Allied Notes Areas controlled by your Affiliated Country. ** 40 Allied Notes Areas non-Beastmen controlled adjacent to your home country. ** 50 Allied Notes Areas non-Beastmen controlled not adjacent to your home country. ** 80/90 Allied Notes Areas that are Beastmen controlled. *She cannot teleport you to Beastman Strongholds (Castle Oztroja (S), La Vaule (S), Beadeaux (S), Castle Zvahl Baileys (S), Castle Zvahl Keep (S), Throne Room (S))' },
    ['Scarred Shark'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) G-5', note = 'Starts Quests:\n* Hammering Hearts\n\nNotes:\n"Do you know what a Sahagin is? You know, those fish-like beastmen. Their demolition tactics have reduced Port Bastok to a shadow of its former glory. The Third Division of the Republican Legion is working tirelessly to rebuild it. And the crushing defeat at Grauberg left even the Fourth Division nearly annihilated. At this rate, who knows what will become of our Republic..." His galkan name is Vareggo.' },
    ['Scavnix'] = { type = 'Standard Merchant :Open from 11:00 to 22:00', zones = { 'Under the bridge in Windurst Walls at', 'Windurst' }, location = 'Under the bridge in Windurst Walls at (H-4)', note = 'Notes:\nNeed to go down a ramp at H-4 in order to find him under the bridge' },
    ['Scorpion Caster'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Various Campaign Fortifications', 'Windurst (S)' }, location = 'Various Campaign Fortifications', note = 'Notes:\n* Leader of the Scorpion Casters is Gariri. *Squadron appears in various locations either fortifying or in Campaign Battles. *They are among the few that may be dispatched to Beaucedine Glacier (S) and Xarcabard (S) once Windurst regains most territory in their cordon. *Cast high-tier area spells, such as Thundaga III.' },
    ['Scotwick'] = { type = 'Allied Notes Notorious Monster Proprietor', zones = { 'Windurst (S)', 'Windurst Waters (S) map = North|K-10' }, location = 'Windurst Waters (S) map = North|K-10', note = 'Starts Quests:\n* Allied Notes Notorious Monsters\n\nNotes:\n* Trade Allied Notes for ANNM Temporary Key Item Green-Labeled Crate * 1500 Allied Notes if allied with Windurst (S). * 3000 Allied Notes if allied with another nation.' },
    ['Scylla Brigade Elite'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Belfry', 'Jeuno (S)' }, location = 'Belfry', note = 'Notes:\n* Spawned by an Allied Armored Belfry erected by the any of the Allied Forces of Altana during an assault of Beaucedine Glacier (S) or Xarcabard (S). *Participates in offensive Campaign Battles. A maximum of 5 reinforcements will appear, and they will continually respawn unless the belfry is demolished. *They will immediately charge to the Fortifications and attack any defenders they encounter.' },
    ['Scylla Brigade Healer'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Beaucedine Glacier (S), Xarcabard (S)', 'Jeuno (S)' }, location = 'Beaucedine Glacier (S), Xarcabard (S)', note = 'Notes:\n:*Appears in Campaign battles along with another dispatched unit in Northland areas under Allied control; they never appear as a standalone unit. :*They will cast Blink, Phalanx, Stoneskin, Raise, and up to Protect IV, Shell IV, and Cure V on Campaign NPCs, anyone with Allied Tags on, and Beastmaster pets. Their spells seem to be on a timer, similar to Pixies. ::*Unknown how the selection of spells they\'ll cast is determined. :*They will not attack unless attacked. When attacked, he\'ll draw his hammer and start attacking the aggressor. This will often happen in battles with monsters that use AoE attacks (such as Battle Dance). :*Has a finite MP pool, as of such will actually be seen in the Command/heal stance to recover MP and HP. You will often see them /heal after all Campaign mobs nearby are defeated and Campaign still continues because another wave is on the way. :*In the event that the unit they arrived with retreats, they will remain on the battlefield and not retreat, remaining to assist anyone nearby and to fight if attacked. :*Have low defence and HP compared to other units, as of such they wont last long when attacked. :*Uses an ability called Goddess\'s Shield; this enables them to cast self-targeting spells like Blink and Phalanx on allied targets.' },
    ['Scylla Brigade Officer'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Belfry', 'Jeuno (S)' }, location = 'Belfry', note = 'Notes:\n* Spawned by an Allied Belfry erected by the any of the Allied Forces of Altana during an assault of Beaucedine Glacier (S) or Xarcabard (S). *Participates in offensive Campaign Battles. A maximum of 5 reinforcements will appear, and they will continually respawn unless the belfry is demolished. *They will immediately charge to the Fortifications and attack any defenders they encounter. *Casts Cure IV, Protect IV, and Shell III on themselves.' },
    ['Sebohl Reccohta'] = { zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin E-8 Pioneers\' Coalition' },
    ['Seburoa-Mabilua'] = { zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst L-7' },
    ['Secodiand'] = { type = 'Quest Giver NPC', zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria F-6, on the walkway', note = 'Starts Quests:\n* Fear of the Dark' },
    ['Secodiand (A)'] = { zones = { 'Abyssea', 'E-3 Main Camp Abyssea - La Theine' }, location = 'E-3 Main Camp Abyssea - La Theine', note = 'Starts Quests:\n* Fear of the Dark III' },
    ['Sedal-Godjal'] = { type = 'Mission NPC', zones = { 'Davoi' }, location = 'Davoi J-8', note = 'Involved in Quests:\n* Whence Blows the Wind\n\nInvolved in Missions:\n* Windurst Mission 8-1: Vain\n* Windurst Mission 8-2: The Jester Who\'d Be King\n\nNotes:\nThe former minister of the Aurastery. He is located on a platform only accessible through the Monastic Cavern.' },
