    ['Selele'] = { type = 'Tutorial NPC', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods K-10', note = 'Notes:\n* Provides tutorial information for newly created characters. *See Tutorial NPC for more information about the 7 mini quests.' },
    ['Selenana'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Windurst', 'Windurst Waters South at the Rhinostery' }, location = 'Windurst Waters South at the Rhinostery', note = 'Involved in Quests:\n* Healing Herbs' },
    ['Selh\'teus'] = { type = 'Cutscene NPC', zones = { 'Battle', 'Cutscene', 'Lumoria' }, note = 'Involved in Missions:\n* Promathia Mission 1-1: The Rites of Life\n* Promathia Mission 1-2: Below the Arks\n* Promathia Mission 1-3: The Mothercrystals\n* Promathia Mission 2-5: Ancient Vows\n* Promathia Mission 3-5: Darkness Named\n* Promathia Mission 4-3: The Secrets of Worship\n* Promathia Mission 5-1: The Enduring Tumult of War\n* Promathia Mission 5-2: Desires of Emptiness\n* Promathia Mission 5-3: Three Paths\n* Past Sins (Louverance Path)\n* Promathia Mission 6-2: A Place to Return\n* Promathia Mission 6-4: One to be Feared\n* Promathia Mission 7-5: The Warrior\'s Path\n* Promathia Mission 8-2: A Fate Decided\n* Promathia Mission 8-3: When Angels Fall\n* Promathia Mission 8-4: Dawn\n\nNotes:\n* A mysterious boy found in Delkfutt\'s Tower, seemingly at the center of the spreading Emptiness phenomenon.' },
    ['Selliste'] = { zones = { 'Bastok', 'Bastok Mines' }, location = 'Bastok Mines K-7', note = 'Starts Quests:\n* The Wondrous Whatchamacallit' },
    ['Selma'] = { zones = { 'Bastok', 'Bastok Markets (Patrols along Gold Street:' }, location = 'Bastok Markets (Patrols along Gold Street: I-9 J-9 K-9)', note = 'Notes:\n(Easy Witch) One of The Dark Lilies of the Harvest Festival event held each October since 2004. Follow Selma without being seen to receive, from the Exorcist, a Witch Hat.' },
    ['Selulu'] = { type = 'Item Deliverer', zones = { 'Windurst', 'Windurst Walls' }, location = 'Windurst Walls I-11', icon = 'Deliverer.png' },
    ['Semih Lafihna'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Cutscenes Only', 'Windurst' }, location = 'Cutscenes Only', note = 'Involved in Quests:\n* Sin Hunting\n* Fire and Brimstone\n* Unbridled Passion\n\nInvolved in Missions:\n* Bastok Mission 2-3: The Emissary\n* Windurst Mission 2-3: The Three Kingdoms\n* Windurst Mission 3-1: To Each His Own Right\n* Windurst Mission 5-1: The Final Seal\n* Windurst Mission 6-1: Full Moon Fountain\n* Windurst Mission 8-2: The Jester Who\'d Be King\n* Windurst Mission 9-1: Doll of the Dead\n* Windurst Mission 9-2: Moon Reading\n* A Crystalline Prophecy (Mission)\n\nNotes:\nSemih Lafihna is leader of the Sibyl Guards and the Star Sibyl\'s personal Patriarch Protector. There are rumors that Semih will become the next Tribal Chieftainess of the Windurst Mithra tribes.' },
    ['Seno Zarhin'] = { zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods G-10', note = 'Notes:\nDialog: Whenever you look around Windurst Woods you see Mithra, rrright? But just until a few decades ago, this whole arrrea was full of Tarutaru. That was until the warrr years when the Mithra chieftainess, Perih Vashai, came across the seas from the Mithran homeland with her army of fighters.' },
    ['Senvaleget'] = { type = 'Auction House Representative', zones = { 'Tavnazian Safehold' }, location = 'Tavnazian Safehold F-10 Middle Floor', note = 'Notes:\n* Auction House services will not be available until after completing Darkness Named.' },
    ['Serukoko'] = { zones = { 'Windurst', 'Windurst Waters map = North|F-7' }, location = 'Windurst Waters map = North|F-7' },
    ['Sevah Kummekihn'] = { type = 'Melody Minstrel', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods J-10', note = 'Notes:\nThis NPC will let you watch cut-scenes that you have seen in Heavens Tower in the past, for a small fee.' },
    ['Seven of Clubs'] = { zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst G-6' },
