    ['Seyaya'] = { zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno G-10' },
    ['Shadeeu'] = { zones = { 'Outland', 'Silver Sea route to Al Zahbi' }, location = 'Silver Sea route to Al Zahbi', note = 'Notes:\nWill report how long until the Ferry docks.' },
    ['Shadow Lord'] = { type = 'Cutscene NPC', zones = { 'Beastman Confederate', 'Cutscene', 'Throne Room' }, location = 'Throne Room', note = 'Involved in Quests:\n* Apocalypse Nigh\n\nInvolved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Bastok Mission 5-2: Xarcabard, Land of Truths\n* San d\'Oria Mission 5-2: The Shadow Lord\n* Windurst Mission 5-2: The Shadow Awaits\n* Zilart Mission 1: The New Frontier\n* Wings of the Goddess Mission 8: In the Name of the Father\n* The Battle of Xarcabard\n\nNotes:\n* The warlord that organized the Beastman Confederate into launching an all-out war against the Allied Forces of Altana, until he was defeated by Zeid at the Battle of Xarcabard. In recent years, rumors of his rebirth persist as the beastmen begin stirring and the Dark Kindred resurface in Castle Zvahl.' },
    ['Shadow Lord (S)'] = { type = 'Cutscene NPC', zones = { 'Beastman Confederate', 'Cutscene', 'Throne Room' }, location = 'Throne Room', note = 'Involved in Quests:\n* Bonds of Mythril\n\nInvolved in Missions:\n* Darkness Descends\n\nNotes:\n* The warlord that organized the Beastman Confederate into launching an all-out war against the Allied Forces of Altana.' },
    ['Shahau'] = { type = 'Alchemy Synthesis Image Support & recipe review NPC', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate F-5' },
    ['Shahayl'] = { type = 'Nyzul Isle Staging Point NPC', zones = { 'Al Zahbi', 'Alzadaal Undersea Ruins' }, location = 'Alzadaal Undersea Ruins J-8 (Nyzul Isle)', note = 'Notes:\n* Speak with him to receive an Assault Armband for Nyzul Isle Investigation. *He does not accept the Supplies Package for Aht Urhgan Mission 2: Immortal Sentries; you must use one of the other five staging points. *Not involved in the quest Beginnings.' },
    ['Shahbizu'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate I-6' },
    ['Shailham'] = { zones = { 'Leujaoam Sanctum', 'Outland' }, location = 'Leujaoam Sanctum', note = 'Involved in Missions:\n* Red Versus Blue\n\nNotes:\n* Squadron leader of the Inexorables' },
    ['Shajaf'] = { zones = { 'Aht Urhgan Whitegate Top Level', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate Top Level (F-8)', note = 'Notes:\nSells the key items necessary to start ISNM fights.' },
    ['Shakir'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria K-10, in Bastok Consul' },
    ['Shalott'] = { zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno G-7' },
    ['Shama Pikholo'] = { type = 'Auction House Representative', zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno G-9' },
    ['Shamarhaan'] = { type = 'Quest Starter', zones = { 'Bastok' }, location = '(F-9) Bastok Markets', note = 'Starts Quests:\n* No Strings Attached\n* Achieving True Power\n\nInvolved in Quests:\n* Puppetmaster Blues\n\nNotes:\nDialogue: Under level 30 chat ------------------- Shamarhaan : ... Valkeng : Dancing now. Please observe. Over level 30 chat ------------------- Valkeng : Would like to join in dance? Shamarhaan : Looks like he\'s taken a liking to you! Shamarhaan : This little guy\'s name is Valkeng. What do you say, Val? Valkeng : Nice to meet kind sir. Shamarhaan : Ha ha, isn\'t he just the cutest thing? Shamarhaan : But to tell the truth, it\'s only because I made him that way. I\'m not sure if you noticed, but I was controlling his every movement! Shamarhaan : \'Puppets\' like him are called automatons. They can do all sorts of things, but it all depends on the handler\'s skill. Shamarhaan : I make my living entertaining people this way. Shamarhaan : People who can control and customize automatons are referred to as \'puppetmasters\' in the Near East. Shamarhaan : You say you\'d like to give it a try yourself? Shamarhaan : Ha ha, I\'m afraid you\'ve got to be a puppetmaster for that. Shamarhaan : Eh? You want to be a puppetmaster, do you? Quite the hasty one, aren\'t we? Shamarhaan : Well, if I had time, I\'d be glad to teach you the ropes, but I can\'t make a living staying in the same town for months on end, now can I? Shamarhaan : Ah, I have the perfect solution! You should meet with my pupil, Iruki-Waraki. I\'ve taught him everything I know. Shamarhaan : Not only that, but he\'s currently the most acclaimed puppeteer in Vana\'diel! You should be able to find him entertaining the folk in Aht Urhgan Whitegate with his automaton. Shamarhaan : He has grown far better than I. You really must witness his expertise before learning how to control an automaton yourself. Followup chat ------------------- Shamarhaan : If you really want to become a puppetmaster, I advise speaking to Iruki-Waraki in Aht Urhgan Whitegate.' },
    ['Shami'] = { zones = { 'Jeuno', 'Port Jeuno' }, location = 'Port Jeuno H-8', note = 'Involved in Quests:\n* Lure of the Wildcat (Jeuno)\n\nInvolved in Missions:\n* Delkfutt the Great' },
    ['Shamonde'] = { zones = { 'Cut scenes only', 'Cutscene', 'San d\'Oria' }, location = 'Cut scenes only', note = 'Involved in Quests:\n* Her Majesty\'s Garden\n\nInvolved in Missions:\n* San d\'Oria Mission 1-3: Save the Childern\n* San d\'Oria Mission 2-2: The Davoi Report\n* San d\'Oria Mission 3-2: The Crystal Spring\n* San d\'Oria Mission 6-2: Ranperre\'s Final Rest\n* San d\'Oria Mission 7-1: Prestige of the Papsque\n* San d\'Oria Mission 8-1: Coming of Age\n* San d\'Oria Mission 8-2: Lightbringer\n* San d\'Oria Mission 9-1: Breaking Barriers\n* San d\'Oria Mission 9-2: The Heir to the Light\n\nNotes:\nThe Papsque is considered by many to be the most pure man in all of San d\'Oria. There are many would even like to see him as leader of the entire nation. |' },
    ['Shanana'] = { zones = { 'Windurst', 'Windurst Waters map = North|G-11' }, location = 'Windurst Waters map = North|G-11', note = 'Notes:\nOnce in several hundred years, a great wizard is born out of the Tarutaru in Windurst. This wizard is so powerful, he is called the Mastermind of the Millen[n]ium. Decades ago, a child formidable enough to carry that title graduated at the top of his class from the School of Magic. I\'m sure you\'ll hear his name mentioned as the hero who saved Windurst.' },
    ['Shanene'] = { zones = { 'Batallia Downs (S)', 'Outland' }, location = 'Batallia Downs (S) J-7', note = 'Involved in Quests:\n* *{{KeyItem\n\nNotes:\n* Speak to her with a {{KeyItem' },
    ['Shanruru'] = { zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst H-5', note = 'Involved in Quests:\n* Riding on the Clouds\n\nNotes:\nDescribed in Riding on the Clouds as, "A little girl sick of being left out all the time." * Member of the Star Onion Brigade' },
    ['Shante-Fante'] = { zones = { 'Windurst', 'Windurst Waters map = North|F-8' }, location = 'Windurst Waters map = North|F-8' },
    ['Shantotto'] = { type = 'Quest NPC', zones = { 'Windurst', 'Windurst Walls' }, location = 'Windurst Walls K-7', note = 'Starts Quests:\n* Curses, Foiled Again!\n* Curses, Foiled...Again!?\n* Curses, Foiled A-Golem!?\n* Blood and Glory\n\nInvolved in Quests:\n* Nothing Matters\n* Wonder Wands\n* SMN AF2: Class Reunion\n* BLM AF1: The Three Magi\n* BLM AF2: Recollections\n* BLM AF3: The Root of the Problem\n* Lure of the Wildcat (Windurst)\n\nStarts Missions:\n* Aht Urhgan Mission 20: Teahouse Tumult\n* Aht Urhgan Mission 23: Social Graces\n* Aht Urhgan Mission 25: Playing the Part\n* An Errand! The Professor\'s Price\n* The Voracious Resurgence: Koru-Moru\'s Hypothesis\n\nInvolved in Missions:\n* Windurst Mission 8-2 The Jester Who\'d Be King\n* Promathia Mission 3-3: The Road Forks\n* Promathia Mission 5-3: Three Paths\n* Where Messengers Gather (Ulmia Path)\n* Aht Urhgan Mission 19: Sweets for the Soul\n* Aht Urhgan Mission 20: Teahouse Tumult\n* Aht Urhgan Mission 21: Finders Keepers\n* Aht Urhgan Mission 22: Shield of Diplomacy\n* Aht Urhgan Mission 24: Foiled Ambition\n* Aht Urhgan Mission 39: Allied Rumblings\n* Aht Urhgan Mission 47: The Empress Crowned\n* A Crystalline Prophecy (Mission)\n* Curses! A Horrifically Harrowing Hex\n* A Shantotto Ascension\n* Project: Shantottofication\n* Kupipi\'s Dilemma (The Voracious Resurgence 2-1)\n\nNotes:\nSee also: Lady Shantotto Exposed! [http://finalfantasy.wikia.com/wiki/Dissidia_Final_Fantasy Dissidia Final Fantasy] / [http://finalfantasy.wikia.com/wiki/Dissidia_012_Final_Fantasy Dissidia 012] 110px|right [http://finalfantasy.wikia.com/wiki/Shantotto/Dissidia Shantotto Dissidia Profile] Shantotto appears as a playable secret character in Dissidia: Final Fantasy as well as its prequel Dissidia 012. She is allied with Cosmos, Goddess of Harmony and is voiced by Megumi Hayashibara in the Japanese version. In the English version, she is voiced by Candi Milo. On the character unlock screen it says that Shantotto is a "[Chainspeller] - Batters foes with incredibly powerful magical HP attacks." It is notable that [http://finalfantasy.wikia.com/wiki/Shantotto/Dissidia#HP_Attacks spell tiers for magical HP attacks] change once her Bravery reaches certain levels; the highest attacks being Ancient Magic. Character File Description from Dissidia: "A war hero with immeasurable magical power. Former minister of the Orastery, then head of the Parliament of Patriarchs, in the original game, Shantotto was one of the top minds in the Federation of Windurst. It\'s said her pride is higher than the pinnacles of the Gustaberg range, and her temper hotter than the magma flowing forth from the mighty Mount Yuhtunga. Her age is unknown, and having thus far neglected to marry seems to be her only regret in life."' },
    ['Shantotto (S)'] = { type = 'Quest NPC', zones = { 'Cutscene', 'Windurst (S)' }, note = 'Involved in Quests:\n* A Feast for Gnats\n* The Long March North\n\nNotes:\n* Currently is considered the "former" Minister of the Orastery. She\'s been sentenced to exile and stripped of all military authority. *She is currently traveling with the Leonian War Warlocks "forced" by Doron-Fulan to do his bidding. See also: Lady Shantotto Exposed!' },
    ['Sharin-Garin'] = { zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate L-8', note = 'Notes:\n:* Answers questions about the Chamber of Passage, Runic Portals and Staging Points. :* Sells Runic Portal Use Permits for 200 Imperial Standing. :** He will not sell Runic Portal Use Permits if the Astral Candescence is in the hands of the beastmen. If you already had a permit prior to the Astral Candescence being taken, you will still be able to use it.' },
    ['Shark Teeth'] = { zones = { 'Kazham' }, location = 'Kazham G-7' },
