    ['Sheia Pohrichamaha'] = { type = 'Regional Vendor NPC :*Fauregandi Region', zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst B-4' },
    ['Shelu-Mapelu'] = { zones = { 'Nashmau' }, location = 'Nashmau H-6. First level, staring into the corner.', note = 'Notes:\nGrants adventurers rewards in exchange for chunks of Guimauve Meat. *Gives Adamantite Armor in exchange for the first trade.' },
    ['Shemo'] = { zones = { 'Jeuno', 'Port Jeuno' }, location = 'Port Jeuno H-8', note = 'Notes:\nAllows adventurers to convert any 3 seals or crests (Beastmen\'s Seal, Kindred\'s Seal, etc) to any 1 seal or crest. *This is for orb-related seals only, not other types of seals, such as Empyrean Amor seals. *Shemo does not give you seals or crests; he just adds to your total amount. Talk to Shami, standing next to him, to actually put the seals back into your inventory. *As of the September 2019 update, now accepts all seal types in a single trade.' },
    ['Shenni'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)', 'Special Event' }, location = 'Bastok Markets (S) F-9', note = 'Notes:\n* Shenni only appears at ({{Location Tooltip|area=Bastok Markets (S)|pos=F-9' },
    ['Sheridan'] = { zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria H-10', note = 'Involved in Quests:\n* Riding on the Clouds\n\nNotes:\n* Dialogue: I heard that the Brugaire Consortium that runs these warehouses is looking for workers. They\'re one of San d\'Oria\'s biggest trading companies...but I hear they\'re a little rough with their staff. And people say they smuggl--ahem! Wouldn\'t want a prospective employer to hear me saying that, now would I! * Described in Riding on the Clouds as, "A young man looking for a job where they\'re not too rough with him."' },
    ['Shey Wayatih'] = { type = 'Adventurer\'s Assistant', zones = { 'Kazham' }, location = 'Kazham G-7' },
    ['Shidzue'] = { type = 'Weather Reporter', zones = { 'Norg' }, location = 'Norg H-9', note = 'Notes:\nReports weather for the following areas: *Yuhtunga Jungle *Yhoator Jungle *Ferry *Jeuno' },
    ['Shiftrix'] = { zones = { 'Reisenjima' }, location = 'Reisenjima', note = 'Notes:\nSells Various Items and Key Items for Escha Silt. See Geas Fete for more details.You must talk with him at least once before you can augment armor via Oseem.' },
    ['Shigezane, I.M.'] = { type = 'Conquest Overseer', zones = { 'Bastok', 'North Gustaberg', 'Outland' }, location = 'North Gustaberg D-10', note = 'Notes:\nAppears, when Gustaberg is under weekly conquest-control by Bastok. ;Notes for characters only with Bastok as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts Gustaberg Supplies for finishing Supply Quest :*Accepts Garrison starting item Darksteel Engraving ;Notes for characters only without Bastok as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Shih Tayuun'] = { type = 'Guild Merchant NPC: Bonecraft Guild', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods H-12', note = 'Notes:\nOpen: 8:00 - 23:00.No longer closed Windsday.' },
    ['Shihu-Danhu'] = { type = 'Warp NPC', zones = { 'Al Zahbi' }, location = 'Al Zahbi J-10', note = 'Notes:\nthumb|Oops... *He will warp you for free to an area near Jeuno. The actual destination is random: ** Ru\'Lude Gardens (H-9) ** Batallia Downs (K-8) ** Rolanberry Fields (J-6) ** Sauromugue Champaign (F-5) ** Qufim Island (I-9) *However, if the Astral Candescence is lost, his list expands to include the above and several, less desirable destinations: ** Batallia Downs (D-7) ** Rolanberry Fields (J-13) ** Sauromugue Champaign (L-7) ** Qufim Island (F-8) *This NPC, just like the other NPCs of Al Zahbi, can be taken prisoner after a Besieged event; he must then be rescued. This can be accomplished by going to the appropriate prison area of the beastmen who captured him, then unlocking him from his prison. *Shihu-Danhu\'s older brother is Kaduru-Haiduru and he will warp you to Ru\'Lude Gardens or your home nation for an Imperial Silver Piece. He is never taken as a prisoner, since he is located in the Whitegate area. Using Shihu-Danhu will make you "reek of amateur sorcery," preventing you from using his older brother\'s pay-based service for one game day.' },
    ['Shikaree G'] = { zones = { 'Cutscene', 'Outland' }, note = 'Involved in Quests:\n* When One Man Is Not Enough\n* A Feast for Gnats\n* Sins of the Mothers\n* Howl from the Heavens\n* Manifest Destiny\n* At Journey\'s End\n\nNotes:\n* One of the Mithran Trackers from Olzhirya, who is pursuing Lehko Habhoka for unknown reasons. *She is the mother of Shikaree X Shikaree Y and Shikaree Z according to Koh Lenbalalako' },
    ['Shikaree M'] = { type = 'Cutscene NPC', zones = { 'Cut Scenes Only', 'Cutscene', 'Outland' }, location = 'Cut Scenes Only', note = 'Involved in Quests:\n* Sin Hunting\n* Fire and Brimstone\n* Unbridled Passion\n\nNotes:\n* One of the Mithran Trackers from Olzhirya and is involved in the ranger af quests. *Is tracking down the daughter of Nhev Befrathi for her mother\'s sins.' },
    ['Shikaree X'] = { type = 'Cutscene NPC, Mission Boss', zones = { 'Cutscene', 'Outland', 'Various Cutscenes, Boneyard Gully' }, location = 'Various Cutscenes, Boneyard Gully', note = 'Involved in Quests:\n* Tango with a Tracker\n* Requiem of Sin\n* X Marks the Spot\n\nInvolved in Missions:\n* Promathia Mission 5-3: Three Paths\n* Where Messengers Gather (Ulmia\'s Path)\n* Promathia Mission 7-4: Calm Before the Storm\n* Promathia Mission 8-4: Dawn\n\nNotes:\n* One of the three Mithran Tracker sisters (a.k.a. "The Sin Hunters") from Olzhirya. *She and her sisters are the daughters of Shikaree G according to Koh Lenbalalako' },
    ['Shikaree Y'] = { type = 'Cutscene NPC, Mission Boss', zones = { 'Cutscene', 'Outland', 'Various Cutscenes, Boneyard Gully' }, location = 'Various Cutscenes, Boneyard Gully', note = 'Involved in Quests:\n* Tuning In\n* Tuning Out\n* Tango with a Tracker\n* Requiem of Sin\n\nInvolved in Missions:\n* Promathia Mission 5-3: Three Paths\n* Where Messengers Gather (Ulmia\'s Path)\n* Promathia Mission 7-4: Calm Before the Storm\n* Promathia Mission 8-4: Dawn\n\nNotes:\n* One of the three Mithran Tracker sisters (a.k.a. "The Sin Hunters") from Olzhirya. *She and her sisters are the daughters of Shikaree G according to Koh Lenbalalako' },
    ['Shikaree Z'] = { type = 'Mission Boss', zones = { 'Boneyard Gully', 'Cutscene', 'Outland' }, location = 'Boneyard Gully', note = 'Involved in Quests:\n* One Good Deed?\n* Requiem of Sin\n\nInvolved in Missions:\n* Promathia Mission 5-3: Three Paths\n* Where Messengers Gather (Ulmia\'s Path)\n* Promathia Mission 6-4: One to be Feared\n* Promathia Mission 7-1: Chains and Bonds\n* Promathia Mission 7-2: Flames in the Darkness\n* Promathia Mission 7-3: Fire in the Eyes of Men\n* Promathia Mission 7-4: Calm Before the Storm\n* Promathia Mission 7-5: The Warrior\'s Path\n* Promathia Mission 8-1: Garden of Antiquity\n* Promathia Mission 8-3: When Angels Fall\n* Promathia Mission 8-4: Dawn\n\nNotes:\n* One of the three Mithran Tracker sisters (a.k.a. "The Sin Hunters") from Olzhirya. *She and her sisters are the daughters of Shikaree G according to Koh Lenbalalako' },
    ['Shikoko, W.W.'] = { type = 'Conquest Overseer', zones = { 'Outland', 'Pashhow Marshlands', 'Windurst' }, location = 'Pashhow Marshlands K-4', note = 'Notes:\nAppears when Derfland is under control of Windurst. ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band or Chariot Band :*Accepts Derfland Supplies for finishing Supply Quest ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
