    ['Spriggan Crier (NPC)'] = { type = 'Special Event NPC', zones = { 'Available only during Final Fantasy XIV Crossover Events *Southern San d\'Oria', 'Outland', 'Special Event' }, location = 'Available only during Final Fantasy XIV Crossover Events *Southern San d\'Oria (G-9) *Port Bastok (K-7) *Windurst Waters (F-9) *West Ronfaure (I-6) *North Gustaberg (L-8) *West Sarutabaruta (J-8)', note = 'Notes:\nAfter unlocking one booby prize in the FINAL FANTASY XIV: A Realm Reborn Crossover, trade the Spriggan Crier one crystal of each of the 8 elements to obtain a Red Spriggan Spirit. Trade the Red Spriggan Spirit to Suibhne in the Feretory after completing Monstrosity (Quest) to unlock the playable Spriggan.C (MON) monster.' },
    ['Spriggan Graverobber (NPC)'] = { type = 'Special Event NPC', zones = { 'Available only during Final Fantasy XIV Crossover Events *Southern San d\'Oria', 'Outland', 'Special Event' }, location = 'Available only during Final Fantasy XIV Crossover Events *Southern San d\'Oria (G-9) *Port Bastok (K-7) *Windurst Waters (F-9) *West Ronfaure (I-6) *North Gustaberg (L-8) *West Sarutabaruta (J-8)', note = 'Notes:\nAfter unlocking one booby prize in the FINAL FANTASY XIV: A Realm Reborn Crossover, trade the Spriggan Graverobber one crystal of each of the 8 elements to obtain a Purple Spriggan Spirit. Trade the Purple Spriggan Spirit to Suibhne in the Feretory after completing Monstrosity (Quest) to unlock the playable Spriggan.G (MON) monster.' },
    ['Spriggan Sifter (NPC)'] = { type = 'Special Event NPC', zones = { 'Available only during a FINAL FANTASY XIV: A Realm Reborn Crossover event *Southern San d\'Oria', 'Outland', 'Special Event' }, location = 'Available only during a FINAL FANTASY XIV: A Realm Reborn Crossover event *Southern San d\'Oria (G-9) *Port Bastok (K-7) *Windurst Waters (F-9) *West Ronfaure (I-6) *North Gustaberg (L-8) *West Sarutabaruta (J-8)', note = 'Involved in Quests:\n* FINAL FANTASY XIV: A Realm Reborn Crossover\n* FINAL FANTASY XIV: A Realm Reborn Crossover II\n* Anniversary MMO Collaboration\n\nNotes:\nAfter unlocking one booby prize in the FINAL FANTASY XIV: A Realm Reborn Crossover, trade the Spriggan Sifter one crystal of each of the 8 elements to obtain a Spriggan Fetish. Trade the Spriggan Fetish to Suibhne in the Feretory after completing Monstrosity (Quest) to unlock the playable Spriggan (MON) monster.' },
