    ['Switchlox'] = { type = 'Moblin Maze Mongers NPC', zones = { 'Ruhotz Silvermines' }, location = 'Ruhotz Silvermines', note = 'Notes:\n* Will change the job of Chaperix to either "Walloper", "Spellslinger" or "Barrager". **"Walloper" requires the temp items Body Boost and Strength Potion. **"Spellsplinger" requires the temp items Wizard\'s Drink and Intelligence Potion. **"Barrager" requires the temp items Agility Potion and Dexterity Potion. *Provides the quest Ultimate Technique which can be activated after Chaperix has reached level 20 and the Maze Rune 102 has been placed on the Maze Tabula.' },
    ['Switchstix'] = { type = 'Relic Weapon Upgrader NPC', zones = { 'Castle Zvahl Baileys', 'Outland' }, location = 'Castle Zvahl Baileys J-8 Map 1', note = 'Notes:\nThis Goblin NPC can upgrade Relic Weapons to their second, third and fourth stages, given the requested items and commission in Ancient Currency. The fifth and final stage of each weapon is not handled directly by Switchstix, but by the Relic Weapon itself. Instructions detailing how to upgrade Relic Weapons to their final forms can be found on the Relic Weapon category page.' },
    ['Sylvie'] = { type = 'Quest Giver NPC', zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin I-5', note = 'Starts Quests:\n* Dances with Luopans\n* Elementary, My Dear Sylvie\n* For Whom the Bell Tolls\n* The Bloodline of Zacariah\n* The Communion\n* Geomancer Relic Armor Quests\n* Treasures of the Earth' },
