    ['Tahmasp'] = { type = 'Outpost Vendor', zones = { 'Outland', 'Pashhow Marshlands' }, location = 'Pashhow Marshlands K-6', note = 'Notes:\nAppears when Derfland is under weekly conquest-control by one of the three nations. :*Sells to and buys items from characters allied with the nation that has the weekly conquest-control of this region. :*All items which Standard Merchants normally buy, can be traded by all characters for regional influence points. The points are awarded to the trader\'s current Allegiance. :*Teleports players who have previously done a Supply Run for the specific region, to their Allegiance Teleport NPC in one of the three cities. For further information, see Outpost Vendor. ;Items sold: *Antidote 316gil *Echo Drops 800gil *Ether 4832gil *Eye Drops 2595gil *Potion 910gil' },
    ['Tahn Posbei'] = { type = 'Standard Merchant', zones = { 'Kazham', 'Posbei\'s Combat Gear in Kazham' }, location = 'Posbei\'s Combat Gear in Kazham, (H-9)' },
