    ['Tenacious Tirrod'] = { type = 'Cutscene NPC', zones = { 'Adoulin', 'Cutscene', 'Rala Waterways' }, location = 'Rala Waterways', note = 'Involved in Quests:\n* Raptor Rapture\n\nNotes:\nAfter completing Raptor Rapture, it\'s possible to watch Fearless Fismar, Tenacious Tirrod, and Vicious Vorahal fight in the Rala Waterways arena.' },
    ['Tenzen'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Far East' }, note = 'Involved in Missions:\n* Promathia Mission 3-2: Vessel Without a Captain\n* Promathia Mission 3-5: Darkness Named\n* Promathia Mission 4-1: Sheltering Doubt\n* Promathia Mission 4-2: The Savage\n* Promathia Mission 4-3: The Secrets of Worship\n* Promathia Mission 4-4: Slanderous Utterings\n* Promathia Mission 5-1: The Enduring Tumult of War\n* Promathia Mission 5-2: Desires of Emptiness\n* Promathia Mission 5-3: Three Paths\n* The Pursuit of Paradise (Tenzen\'s Path)\n* Promathia Mission 6-1: For Whom the Verse is Sung\n* Promathia Mission 6-4: One to be Feared\n* Promathia Mission 7-1: Chains and Bonds\n* Promathia Mission 7-2: Flames in the Darkness\n* Promathia Mission 7-3: Fire in the Eyes of Men\n* Promathia Mission 7-4: Calm Before the Storm\n* Promathia Mission 7-5: The Warrior\'s Path\n* Promathia Mission 8-3: When Angels Fall\n* Promathia Mission 8-4: Dawn\n\nNotes:\n* Tenzen has come from a mysterious nation in the Far East to fight the Emptiness, with the mystical Phoenix Blade at his side. He is one of your companions through most of the Chains of Promathia Missions; you first meet him in Chapter 3.' },
    ['Teodor'] = { zones = { 'Adoulin', 'Cutscenes only' }, location = 'Cutscenes only', note = 'Involved in Quests:\n* Flavors of Our Lives\n\nInvolved in Missions:\n* Budding Prospects\n* The Smallest of Favors\n* The Man in Black\n* To the Victor...\n* The Order\'s Treasures' },
