    ['Terude-Harude'] = { type = 'Advanced synthesis image support NPC :*Clothcraft Guild', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods G-12', note = 'Notes:\nTerude-Harude is an exceptional clothcrafter, who will provide you with advanced synthesis support for a small fee. Accepting his offer will raise your clothcrafting skill slightly, and will increase your chances of a successful synth more so than the free services provided by the other NPCs from the guild. However, you may only have one synthesis support image active at a time, and may not ask other Synthesis Support NPCs for assistance until the one you are currently using has worn off.' },
