    ['Tilala'] = { type = 'Guild Merchant NPC: Clothcraft Guild :Open: 6:00 - 21:00 :No longer shares stock with Gibol.', zones = { 'Selbina' }, location = 'Selbina H-9', note = 'Notes:\nDespite being a male Tarutaru, his name conforms to female Tarutaru naming conventions. This may be a subtle nod to the preponderance of feminine tendencies in the fashion industry.' },
