    ['Tsonga-Hoponga, W.W.'] = { type = 'Conquest Overseer - Windurst Outpost Conquest Guard', zones = { 'Outland', 'Qufim Island', 'Windurst' }, location = 'Qufim Island F-6', note = 'Notes:\nAppears, when Qufim is under weekly conquest-control by Windurst ;Notes for characters only with Windurst as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Empress Band, Chariot Band or Emperor Band :*Accepts Qufim Supplies for finishing Supply Quest :*Accepts Garrison starting item Ram Leather Missive ;Notes for characters only without Windurst as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
