    ['Tswe Panipahr'] = { type = 'Boat Ticket Vendor', zones = { 'Bibiki Bay', 'Outland' }, location = 'Bibiki Bay H-7 - Sunset Docks', note = 'Notes:\nSells a Manaclipper Ticket for 80 gil (1 ride) or a Manaclipper Multi-ticket (10 rides) for 500 gil. Informs you about the various routes.' },
    ['Tucker'] = { zones = { 'Crawlers\' Nest (S)', 'Windurst (S)' }, location = 'Crawlers\' Nest (S) K-8', note = 'Involved in Quests:\n* A Little Knowledge\n\nNotes:\n* Tucker will only trade with you if you have talked to Erlene first, and he will not take them if you have completed the quest. * Will trade one sheet of Vellum for a stack of 12 Rolanberries. A maximum of 12 sheets of Vellum is obtainable from Tucker. * You get 3 \'trade turns\' with Tucker - make use of them wisely by trading 4 stacks of Rolanberries at a time so that you can get all 12 Vellum sheets. He will not take more than 4 stacks per trade and he will refuse all Rolanberries after 3 trades. (This will cost you 17,280 gil if you buy the Rolanberries from NPC in Jeuno).' },
    ['Tuffle-Buffle'] = { type = 'Quest Giver NPC', zones = { 'Adoulin', 'Battle', 'Cutscene', 'Mischief Marker at Western Adoulin' }, location = 'Mischief Marker at Western Adoulin (J-11)', note = 'Starts Quests:\n* A Barrel of Laughs\n\nInvolved in Quests:\n* All the Way to the Bank\n* To Laugh Is to Love\n\nNotes:\n* In battle for A Barrel of Laughs, he spams AoE spells and generates massive amounts of enmity.' },
    ['Tuh Almobankha'] = { type = 'Traveling Bard', zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno I-8', note = 'Notes:\n* Will change your Title for a fee or can give you a random title for free. *For a full list of titles, which you can get with this NPC, see Titles.' },
