    ['Turumi-Byrumi'] = { type = 'VCS Chocobo Racing Associate', zones = { 'Removed from game', 'Windurst' }, location = 'Removed from game', note = 'Notes:\nProvided information about Chocobo Racing and recruited adventurers for the CRA Bastok team. He was removed from the game on 9/9/2010, along with Monteverle, Galienne, and Salvador.' },
    ['Twinkbrix'] = { type = 'ENM Quest Activator', zones = { 'Oldton Movalpolos' }, location = 'Oldton Movalpolos E-13', note = 'Notes:\nGambling: Twinkbrix likes to gamble, and if you play and win, he will reward you with a {{KeyItem' },
