    ['Udip Ferawoh'] = { zones = { 'Adoulin', 'Marjami Ravine' }, location = 'Marjami Ravine M-7', note = 'Starts Quests:\n* Did You Feel That?' },
    ['Ufanne'] = { zones = { 'Port San d\'Oria', 'San d\'Oria' }, location = 'Port San d\'Oria H-8', note = 'Involved in Quests:\n* The Rivalry - The Competition\n\nNotes:\nDialogue: Those two... I do wish they wouldn\'t carp so about who can catch more fish that whom. And why should I care either way? After trading carp to Joulet or Gallijaux, but before zoning: You\'ve collected [current #] carps for [Joulet/Gallijaux] so far. Those two--so feverish are they in their devotion to the art of fishing that they lose count of their haul of fish and have to start over from the beginning.' },
    ['Ufanne (A)'] = { zones = { 'Abyssea', 'Abyssea - La Theine' }, location = 'Abyssea - La Theine H-7' },
