    ['Ulaciont, R.K.'] = { type = 'Campaign NPC', zones = { 'Grauberg (S)', 'San d\'Oria (S)' }, location = 'Grauberg (S) I-8', note = 'Notes:\n* San d\'Oria affiliated Campaign Arbiter. Present when San d\'Oria (S) has control of Grauberg (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Ulamaal'] = { type = 'Quest Giver', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate K-12 - in the teahouse', note = 'Starts Quests:\n* Vanishing Act\n\nInvolved in Quests:\n* Delivering the Goods\n* A Taste of Honey' },
    ['Ulbrecht'] = { type = 'Cutscene NPC', zones = { 'Bastok (S)', 'Cutscene' }, note = 'Involved in Quests:\n* A Little Knowledge\n* On Sabbatical\n* Downward Helix\n* Seeing Blood-red\n\nNotes:\nProfessor Ulbrecht is an officer schooled in the Schultz School of Martial Theory. He is somewhat crass and uncivil, sometimes interrupting Professor Erlene with requests.' },
    ['Ulbuun'] = { zones = { 'Ilrusi Atoll', 'Outland' }, location = 'Ilrusi Atoll', note = 'Involved in Missions:\n* Desperately Seeking Cephalopods\n\nNotes:\n* Deliver the Ahtapot after defeating the Orobon to unlock the Rune of Release.' },
    ['Ulesa'] = { type = 'Auction House Representative', zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno H-7' },
    ['Uli Pehkowa'] = { type = 'Standard Merchant', zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst M-7, Airship Dock (requires an Airship pass)' },
    ['Ulla'] = { type = 'Campaign Freelance', zones = { 'Battle', 'Freelance', 'Varies {{Verification' }, location = 'Varies {{Verification' },
    ['Ullasa'] = { zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria B-6 in Count Caffaule\'s Manor', note = 'Involved in Quests:\n* Under Oath\n* Starlight Celebration 2008\n* Starlight Celebration 2010' },
    ['Ullegore'] = { type = 'Event NPC', zones = { 'Northern San d\'Oria', 'Special Event' }, location = 'Northern San d\'Oria F-5 / Bastok Markets (G-8) / Windurst Waters North (F-9)', note = 'Notes:\nleft|180px|thumb|Ullegore\'s Elvaan form A long, long time ago, on a starry night different from no other, a lone meteorite fell from the bejeweled sky unbeknownst to the slumbering denizens of Vana\'diel. From the superheated core of this extraterrestrial rock emerged an entity of unadulterated evil?the physical manifestation of darkness itself. The name of this twisted being was Ullegore. His sole purpose: the complete and utter eradication of joy and jubilance from the face of the world.' },
    ['Ulmer, C.A.'] = { type = 'Campaign NPC', zones = { 'Castle Oztroja (S),', 'Jeuno (S)' }, location = 'Castle Oztroja (S),', note = 'Notes:\n* Jeuno affiliated Campaign Arbiter. Present when Beastmen have control of Castle Oztroja (S). *Offers Campaign Information, Campaign Allied Tags, Teleportation *Campaign Sword in front of name during Campaign' },
    ['Ulmia'] = { type = 'Cutscene NPC', zones = { 'Cutscene', 'Tavnazian Safehold' }, location = 'Tavnazian Safehold', note = 'Involved in Quests:\n* Storms of Fate\n* Apocalypse Nigh\n\nInvolved in Missions:\n* Promathia Mission 2-3: Distant Beliefs\n* Promathia Mission 2-4: An Eternal Melody\n* Promathia Mission 2-5: Ancient Vows\n* The Road Forks: The Road Forks\n* Promathia Mission 3-4: Tending Aged Wounds\n* Promathia Mission 3-5: Darkness Named\n* Promathia Mission 4-1: Sheltering Doubt\n* Promathia Mission 4-2: The Savage\n* Promathia Mission 4-3: The Secrets of Worship\n* Promathia Mission 4-4: Slanderous Utterings\n* Promathia Mission 5-1: The Enduring Tumult of War\n* Promathia Mission 5-2: Desires of Emptiness\n* Promathia Mission 5-3: Three Paths\n* Past Sins (Louverance\'s Path)\n* The Pursuit of Paradise (Tenzen\'s Path)\n* Where Messengers Gather (Ulmia\'s Path)\n* Promathia Mission 6-1: For Whom the Verse is Sung\n* Promathia Mission 6-2: A Place to Return\n* Promathia Mission 6-3: More Questions Than Answers\n* Promathia Mission 6-4: One to be Feared\n* Promathia Mission 7-1: Chains and Bonds\n* Promathia Mission 7-2: Flames in the Darkness\n* Promathia Mission 7-3: Fire in the Eyes of Men\n* Promathia Mission 7-4: Calm Before the Storm\n* Promathia Mission 7-5: The Warrior\'s Path\n* Promathia Mission 8-1: The Garden of Antiquity\n* Promathia Mission 8-2: A Fate Decided\n* Promathia Mission 8-3: When Angels Fall\n* Promathia Mission 8-4: Dawn\n\nNotes:\nUlmia is the granddaughter of a Tavnazian elder, and personal friend of Prishe.' },
    ['Ulrich'] = { zones = { 'Bastok', 'Cutscene', 'Cutscenes' }, location = 'Cutscenes', note = 'Involved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Bastok Mission 9-2: Where Two Paths Converge\n\nNotes:\nThe former captain of the Mythril Musketeers and Uncle of Volker. Before the outbreak of the Crystal War he was sent along with two other Mythril Musketeers Raogrimm and Cornelia to investigate the northlands in co-operation with Francmage of San d\'Oria and Yow Rabntah and Iru-Kuiru of Windurst. Prior to the expedition Ulrich had been in conflict with Raogrimm because he was advocating peace with the Beastmen, and he was jealous of Raogrimm\'s relationship with Cornelia.' },
    ['Ulrike'] = { type = 'Recipe Giver', zones = { 'Bastok', 'Bastok Markets' }, location = 'Bastok Markets H-8' },
    ['Ultra Slime'] = { type = 'Special Event NPC', zones = { '*Windurst Woods', 'Outland', 'Special Event' }, location = '*Windurst Woods (H-11)', note = 'Starts Quests:\n* DRAGON QUEST X ONLINE Crossover' },
