    ['Ulzana'] = { type = 'Quest NPC', zones = { 'Cutscenes' }, location = 'Cutscenes', note = 'Starts Quests:\n* | involved in missions\n\nInvolved in Quests:\n* A Chocobo\'s Tale\n* Hitting the Marquisate' },
    ['Umarid'] = { zones = { 'Al Zahbi', 'Periqia' }, location = 'Periqia', note = 'Involved in Missions:\n* Operation: Snake Eyes' },
