    ['Vavegallet'] = { zones = { 'Northern San d\'Oria', 'San d\'Oria' }, location = 'Northern San d\'Oria F-8', note = 'Notes:\n"Hrmm... You look like another adventurer obsessed with shining swords and gleaming shields. Am I wrong?" "Well, the hallmark of an adventurer is a richly-decorated domicile. Really, you must visit the furniture shop!"' },
