    ['Verctissa'] = { type = 'Quest Starter', zones = { 'Norg' }, location = 'Norg H-9', note = 'Starts Quests:\n* Trial Size Trial by Water\n\nNotes:\nWill warp main-job Summoners to Cloister of Tides if traded the Mini Tuning Fork of Water while Trial Size Trial by Water is open. Most SMNs never complete this quest so that a permanent warp to Cloister of Tides is available. She will also provide a new mini fork at any time if the old one was dropped.' },
    ['Verena'] = { type = 'Mission NPC', zones = { 'Cut scenes only', 'Cutscene', 'Jeuno' }, location = 'Cut scenes only', note = 'Involved in Quests:\n* Shadows of the Departed\n\nInvolved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Zilart Mission 8: Return to Delkfutt\'s Tower\n* Zilart Mission 9: Ro\'Maeve\n* Zilart Mission 17: Awakening\n* A Crystalline Prophecy (Mission)\n\nNotes:\nThe younger sister of Aldo, head of the Tenshodo. She has an affinity for the beastmen races and is friends with local Goblins living in Jeuno, especially Fickblix, which creates tension with her brother. However, her natural affinity has also caught the attention of Lord Eald\'narche, who became interested in this trait......' },
    ['Vesca'] = { type = 'Peacekeepers\' Coalition Reward Bayld Vendor NPC', zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin F-7', note = 'Notes:\nHeemo-Weemo - Western Adoulin J-10 augments gear for 3000 Bayld. * Augment item required: Coalition Grease sold by Ugtoor - Western Adoulin J-9 for 5000 bayld. * Karieyh gear - Can be augmented with HP+ * Orvail gear - Can be augmented with MP+ * Thurandaut gear - Can be augmented with HP+ and MP+ Runje Desaali - Eastern Adoulin J-10 trades bayld for these items at 1/5 the purchase price. An update a couple years ago reduced prices to 1/10th their previous value.' },
    ['Vestavius'] = { type = 'Quest NPC', zones = { 'Adoulin', 'Cutscene', 'Morimar Basalt Fields Frontier Station' }, location = 'Morimar Basalt Fields Frontier Station', note = 'Involved in Quests:\n* For Whom the Bell Tolls' },
