    ['Vhana Ehgaklywha'] = { zones = { 'Jeuno', 'Lower Jeuno, walks from' }, location = 'Lower Jeuno, walks from (I-5) stairway from Upper Jeuno to (F-12) exit to Rolanberry Fields.', note = 'Involved in Quests:\n* Community Service\n\nNotes:\n* Only appears in Lower Jeuno if no one has started the Community Service Quest, and lights the Streetlamps.' },
    ['Vhino Delkahngo'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Windurst (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) K-5', note = 'Involved in Quests:\n* When One Man Is Not Enough\n\nNotes:\n:*Appears during Campaign Battles as the leader of the Crocodile Mercenaries. :*Vhino\'s mercenaries are only deployed to Sauromugue Champaign (S). :*Vhino uses her own special ranged weaponskill called Soulfetter Arrow. :*Vhino has relatively high evasion and uses Triple Attack, suggesting that she may also be a Thief. :*Talk: Back in my home, Ulbuka, I hear rumors of great riches in eastern lands. But now I am here, and where are riches? I see nothing but Tarus! Ahahahaha! :*Battle cry: Petty beastmen hordes are nothing compared to giant wildebeests of homeland! I swat you all down like fruit flies!' },
    ['Vichauxdat'] = { zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) I-8', note = 'Involved in Missions:\n* WOTG21: Proof of Valor' },
