    ['Vobo'] = { zones = { 'Selbina' }, location = 'Selbina I-7', note = 'Involved in Quests:\n* Riding on the Clouds\n\nNotes:\nDescribed in Riding on the Clouds as, "A Galkan child who is great at hiding."' },
    ['Voidwatch Officer'] = { zones = { '{{location|Bastok Markets|D-11', 'Jeuno' }, location = '{{location|Bastok Markets|D-11', note = 'Involved in Quests:\n* Drafted by the Duchy\n* Battle on a New Front\n* VW Op. #126: Qufim Incursion\n* The Truth Is Out There\n* A New Menace\n* No Rest for the Weary\n\nNotes:\nProvides players (level 75 minimum) with assistance with Voidwatch operations, with the following choices: *Ask a bunch of questions. *Participate in Voidwatch Ops. *Request debriefing. *Request Voidstone. *Check Voidstone stock. *Request reward issuance. Can purchase the following: *Cobalt Cell: 3,000 Cruor *Rubicund Cell: 3,000 Cruor *Xanthous Cell: 3,000 Cruor *Periapt of Emergence: 50,000 Cruor *Periapt of Guidance: 150,000 Cruor *Periapt of Percipience: 150,000 Cruor *Periapt of Sapience: 50,000 Cruor *Periapt of Clarity: 50,000 Cruor *Beguiling Petrifact: 330,000 Cruor *Seductive Petrifact: 330,000 Cruor *Maddening Petrifact: 330,000 Cruor Can also convert any Voiddust into a Voidstone as long as the player has no Voidstones in their possession. I just converted 3 Voiddust into Voidstones in one session.' },
    ['Voidwatch Purveyor'] = { zones = { 'Al Zahbi Aht Urhgan Whitegate (I-8, North Wall) Nashmau Southern San d\'Oria (S) Bastok Markets (S) (H-4, North Wall by Rye Bridge) Windurst Waters (S)', 'Jeuno' }, location = 'Al Zahbi Aht Urhgan Whitegate (I-8, North Wall) Nashmau Southern San d\'Oria (S) Bastok Markets (S) (H-4, North Wall by Rye Bridge) Windurst Waters (S) (G-5) Southern San d\'Oria (K-10) Northern San d\'Oria (C-8) Bastok Mines (H-10) Bastok Markets (D-11) Port Bastok Windurst Waters (F-5 near gate) Port Windurst Windurst Woods Ru\'Lude Gardens (H-10) Upper Jeuno (F-6) Lower Jeuno Port Jeuno', note = 'Notes:\nUsed to puchase Ascent Items for Voidwatch. Item will cost the player their regional credits and not cruor. Those wishing to use Cruor can purchase the cells at a Voidwatch Officer except for Jade Cells.' },
    ['Vola'] = { zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno J-8 in Neptune\'s Spire', note = 'Starts Quests:\n* Fistful of Fury\n* Beat Around the Bushin' },
