    ['Wau Kaatapoh'] = { zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst M-6' },
    ['Waudeen'] = { type = 'Assault Lebros Cavern NPC', zones = { 'Halvung Staging Point (Mount Zhayolm', 'Outland' }, location = 'Halvung Staging Point (Mount Zhayolm K-6)', note = 'Involved in Quests:\n* Beginnings\n\nInvolved in Missions:\n* Immortal Sentries\n\nNotes:\n* Speak with him to receive an Assault Armband for assault missions in Lebros Cavern. Quote: "The way is neither smooth nor easy, and you cannot turn from the road you have chosen." "Stay vigilant against the beast within." "That is all the wisdom I can give you."' },
