    ['Weldon'] = { type = 'Item Deliverer', zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) H-6', note = 'Notes:\n* Item Delivery services will not be available if the city is under attack. "I am here to help with all your parcel delivery needs."', icon = 'Deliverer.png' },
    ['Wenonah, C.A.'] = { type = 'Campaign NPC', zones = { 'Jeuno (S)', 'Windurst Waters (S)' }, location = 'Windurst Waters (S) G-10', note = 'Notes:\n* Jeuno affliated Campaign Arbiter in Windurst Waters (S) *Offers Campaign Information, Campaign , Teleportation *Campaign Sword in front of name during Campaign *She cannot teleport you to Beastman Strongholds (Castle Oztroja (S), La Vaule (S), Beadeaux (S), Castle Zvahl Baileys (S), Castle Zvahl Keep (S), Throne Room (S))' },
    ['Wenzel'] = { zones = { 'Selbina' }, location = 'Selbina I-7' },
    ['Werei'] = { type = 'Mission', zones = { 'Bastok' }, location = 'Bastok', note = 'Involved in Missions:\n* Enter the Talekeeper\n\nNotes:\nWerei is the oldest Galka living in Bastok, and has been a major leader within the Galka community and Bastok as a whole for several decades. His sudden disappearance has become a major crisis point for the nation. In one of the few cut scenes where he is physically witnessed, he tells a story about how the Galkas died while being attacked by the Antica.' },
    ['Werei (S)'] = { type = 'Cutscene NPC', zones = { 'Bastok (S)', 'Bastok Markets (S)', 'Cutscene' }, location = 'Bastok Markets (S)', note = 'Involved in Quests:\n* Fires of Discontent\n* Light in the Darkness\n* Storm on the Horizon\n* Fire in the Hole' },
    ['Werner'] = { type = 'Cutscene NPC', zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S)', note = 'Involved in Quests:\n* Better Part of Valor\n* Fires of Discontent\n* Light in the Darkness\n* Burden of Suspicion\n\nNotes:\n* Werner was the Senator of Defense for the Republican Army during the Crystal War.' },
    ['Wescolina'] = { type = 'Artifact NPC', zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin H-7', note = 'Notes:\n* You can commission Geomancer Artifact Armor from Wescolina by talking to her on Geomancer after flagging the quest The Bloodline of Zacariah. *You can choose the order in which you receive the armor. *You can commission a new piece one game day after the last piece was completed. (I was also required to zone between pieces) *Speak to her after the game day changes to exchange the received {{KeyItem' },
    ['Westerly Breeze'] = { zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin I-5', note = 'Starts Quests:\n* Hunger Strikes\n* The Starving\n* "Always more," Quoth the Ravenous' },
