    ['Wije Tiren'] = { type = 'Standard Merchant', zones = { 'Windurst', 'Windurst Woods' }, location = 'Windurst Woods I-8' },
    ['Wildcat Vanguard'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Belfry', 'Windurst (S)' }, location = 'Belfry', note = 'Notes:\n* Spawned by an Allied Belfry erected by the Federal Forces of Windurst. Participates in offensive Campaign Battles. A maximum of 6 reinforcements will appear, and they will continually respawn unless the belfry is demolished. *They will immediately charge to the Fortifications and attack any defenders they encounter. *The Wildcat Vanguards dual-wield daggers in battle, and will use various Dagger weaponskills up to Energy Drain, as well as Ninjutsu magic.' },
    ['Wildcat Volunteer'] = { type = 'Campaign Battle NPC', zones = { 'Battle', 'Varies', 'Windurst (S)' }, location = 'Varies', note = 'Notes:\n* Appears during Campaign Battles as part of the Wildcat Volunteer squadron led by Haja Zhwan.' },
    ['Wilfred'] = { zones = { 'Bastok', 'Batallia Downs (S)' }, location = 'Batallia Downs (S) G-7' },
    ['Wilhelm'] = { zones = { 'Mhaura' }, location = 'Mhaura G-10', note = 'Notes:\nWilhelm works for the The Brugaire Consortium, representing clients from the Near East. Trading him parts from Ultima and Omega (found in the chests that Proto-Ultima and Proto-Omega leave behind following their defeat) will cause his clients to reward you with parts of the Nashira and Homam armor sets, respectively. Both sets of armor are Level 75. Rewards are as follows: ;Nashira Set: Trade Items Obtained from Proto-Ultima Usable By WHM, BLM, RDM, SMN, BLU' },
    ['Wilhelmina'] = { zones = { 'Bastok (S)', 'Bastok Markets (S)' }, location = 'Bastok Markets (S) I-9', note = 'Involved in Quests:\n* Quelling The Storm\n\nNotes:\n"Have you heard the rumors? There have been several sightings of these so-called "maws" outside the city. People are saying they may have been unleashed by the beasthordes! All accounts claim that they float just above ground, wreathing about, with gaping mouths like great voids that never shut... It gives me the chills just to think about it."' },
    ['Willah Maratahya'] = { type = 'Traveling Bard', zones = { 'Mhaura' }, location = 'Mhaura I-8', note = 'Notes:\n* Will change your Title for a fee or can give you a random title for free. *For a full list of titles, which you can get with this NPC, see Titles. *Titles this NPC can give include these not listed in Titles **300 gil *** Heir of Great Lightning **400 gil ***Fodderchief Flayer ***Warchief Wrecker ***Dread Dragon Slayer ***Dark Dragon Slayer ***Black Dragon Slayer ***Behemoth\'s Bane ***Archmage Assassin ***Lich Banisher ***Jellybane ***Beakbender ***Goliath Killer ***Hellsbane ***Morbolbane ***Mary\'s Guide **500 gil ***Simurgh Poacher ***Roc Star ***Serket Breaker ***Cassienova ***The Hornsplitter ***Tortoise Torturer ***Mon Cherry ***Behemoth Dethroner ***Dragon Asher ***Expeditionary Trooper ***Shell Shocker ***Antica Hunter ***Amphibian Adulterator **600 gil ***Adamantking Usurper ***Deity Debunker ***Overlord Overthrower ***Fafnir Slayer ***Aspidochelone Sinker ***Nidhogg Slayer ***Maat Masher ***Kirin Captivator ***Lifter of Shadows ***Tiamat Trouncer ***Vrtra Vanquisher ***World Serpent Slayer ***Xolotl Xtrapolator ***Ouryu Overwhelmer ***Vinegar Evaporator ***Boroka Beleaguerer ***Virtuous Saint ***Temenos Liberator ***Apollyon Ravager ***Nightmare Awakener ***Wyrm Astonisher ***Cactrot Desacelarador ***Bye-bye Taisai' },
    ['Willis'] = { type = 'Abyssea Support', zones = { 'Abyssea', 'Port Windurst' }, location = 'Port Windurst L-6', note = 'Notes:\n* Allows you to view your cruor balance. *Unlike most Abyssea teleporters, he is unable to relay the status of resistance in Scars of Abyssea areas. *Can teleport you to any Abyssean Cavernous Maw for 200 Cruor. **He only gives you the option to teleport to a maw if you have watched the cutscene and flagged the associated quest after examining it for the first time. Note that you must talk to Joachim after receiving the cutscene at your first Scars of Abyssea maw to receive cutscenes from examining the other maws; you will simply be allowed into the other zones without a cutscene nor teleport access from Horst. You must also be in possession of at least one Traverser Stone to receive a cutscene at its corresponding Cavernous Maw. |' },
    ['Winrix'] = { type = 'Gobbie Mystery Box Vendor', zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin G-10', note = 'Notes:\n{{GobbieBox' },
    ['Wise Owl'] = { type = 'Synthesis Image Support', zones = { 'Bastok', 'Metalworks' }, location = 'Metalworks E-7', note = 'Notes:\nHis galkan name is Garbenn.' },
    ['Wise Turtle, I.M.'] = { type = 'Conquest Overseer', zones = { 'Bastok', 'Buburimu Peninsula', 'Outland' }, location = 'Buburimu Peninsula D-6', note = 'Notes:\nAppears, when Kolshushu is under weekly conquest-control by Bastok. ;Notes for characters only with Bastok as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts Kolshushu Supplies for finishing Supply Quest ;Notes for characters only without Bastok as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Wise Wolf'] = { type = 'Auction House Representative', zones = { 'Jeuno', 'Upper Jeuno' }, location = 'Upper Jeuno G-9' },
    ['Wistful Bison'] = { zones = { 'Adoulin', 'Norg' }, location = 'Norg G-7', note = 'Involved in Quests:\n* Researchers from the West' },
    ['Wobke'] = { zones = { 'Bastok', 'Bastok Mines' }, location = 'Bastok Mines I-9', note = 'Involved in Quests:\n* A Chocobo\'s Tale' },
    ['Wolden-Bolden'] = { type = 'Crafter Points Administrator', zones = { 'San d\'Oria', 'Southern San d\'Oria' }, location = 'Southern San d\'Oria D-9', note = 'Notes:\nAdministrates Crafter Points for items used to upgrade Escutcheons. Also sells Crafting Kits.' },
    ['Wolfgang'] = { zones = { 'Cutscene', 'Jeuno', 'Various cutscenes' }, location = 'Various cutscenes', note = 'Involved in Quests:\n* A Candlelight Vigil\n\nInvolved in Missions:\n* Bastok Mission 3-3: Jeuno\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n* Promathia Mission 1-1: The Rites of Life\n* Promathia Mission 1-3: The Mothercrystals\n* Promathia Mission 3-2: Vessel Without a Captain\n* Promathia Mission 3-4: Tending Aged Wounds\n* Promathia Mission 5-3: Three Paths\n* The Pursuit of Paradise (Tenzen\'s Path)\n* Promathia Mission 6-2: A Place to Return\n* Promathia Mission 6-3: More Questions than Answers\n* Promathia Mission 7-2: Flames in the Darkness\n* Promathia Mission 8-4: Dawn\n* Aht Urhgan Mission 6: Easterly Winds\n* Aht Urhgan Mission 39: Allied Rumblings\n* Aht Urhgan Mission 47: The Empress Crowned\n\nNotes:\n* Friend of Monberaux * His father was Brandolf the Captain of the Ducal Guard during the Crystal War' },
    ['Wolfgang (A)'] = { zones = { 'Abyssea', 'Abyssea - Grauberg' }, location = 'Abyssea - Grauberg L-6' },
    ['Wolfram'] = { zones = { 'Cutscene', 'North Gustaberg (S)' }, location = 'North Gustaberg (S)', note = 'Starts Quests:\n* Better Part of Valor' },
    ['Wondrix'] = { type = 'Gobbie Mystery Box Vendor', zones = { 'Aht Urhgan Whitegate', 'Al Zahbi' }, location = 'Aht Urhgan Whitegate F-11', note = 'Notes:\n* Bountibox has moved from Bhaflau Thickets to Aht Urhgan Whitegate (F-11). {{GobbieBox' },
    ['World Shifter'] = { type = 'Wold Transfer NPC', zones = { '*Ru\'Lude Gardens', 'Special Event' }, location = '*Ru\'Lude Gardens (I-10) *Port San d\'Oria (I-8) *Port Bastok (L-8) *Windurst Walls (G-6)', note = 'Notes:\nWhen Square Enix has decided that a server is over-populated, a World Shifter will appear, for a period of time, and offer to register characters for migration to a less-populated server. At a pre-defined time, registrations will be closed and the migration of all then-registered characters will occur. You can always cancel emigration during the application process by speaking with the World Shifter again, but once the period is over, you will no longer be able to cancel, and the only way back will be to use the paid character transfer service. The World Shifter will give you a choice when there is more than one World to pick to migrate to. *Be sure to remove all items you have listen on the Auction House and in your delivery box, as anything in them will be lost when the transfer takes place. *Emigration is done one character at a time. You must request other characters you wish to move separately. *Any linkshells, linkpearls, and pearl sacks will be destroyed at the time of emigration. However, linkshell owners will be given a new, unopened linkshell.' },
    ['Wortherton'] = { zones = { 'Adoulin', 'Western Adoulin' }, location = 'Western Adoulin J-10, Inventors\' Coalition' },
