    ['Yasin'] = { type = 'Cutscene NPC', zones = { 'Bastok', 'Cutscene' }, note = 'Involved in Quests:\n* The Doorman\n* The First Meeting\n\nNotes:\nAn adventurer who is commonly seen with his friend Raogrimm. He is Phara\'s son and Naji\'s father.' },
