    ['Yoram, I.M.'] = { type = 'Conquest Overseer - Bastok Outpost Conquest Guard', zones = { 'Bastok', 'Lufaise Meadows', 'Outland' }, location = 'Lufaise Meadows F-6', note = 'Notes:\nAppears, when Tavnazian Archipelago is under weekly conquest-control by Bastok ;Notes for characters only with Bastok as current Allegiance: :*Casts Signet :*Choice of setting Home Point for free :*Recharges Emperor Band, Empress Band or Chariot Band :*Accepts Tavnazian Archipelago Supplies for finishing Supply Quest ;Notes for characters only without Bastok as current Allegiance: :*Choice of setting Home Point for a fee - higher prices for higher Allegiance Ranks (Rank 10: 5600 gil) For further information see Conquest Overseer.' },
    ['Yoran-Oran'] = { zones = { 'Windurst', 'Windurst Walls' }, location = 'Windurst Walls E-5 (Yoran-Oran\'s Manor)', note = 'Starts Quests:\n* Mandragora-Mad\n\nInvolved in Quests:\n* Blast from the Past\n* The Lost Book\n* BLM AF1: The Three Magi\n* BLM AF2: Recollections\n* BLM AF3: The Root of the Problem\n\nInvolved in Missions:\n* Promathia Mission 3-3: The Road Forks\n* Promathia Mission 5-3: Three Paths\n* Past Sins (Louverance Path)\n* Where Messengers Gather (Ulmia Path)\n* A Shantotto Ascension\n* The Voracious Resurgence: Koru-Moru\'s Hypothesis\n\nNotes:\nYoran-Oran is the former Minister of the Rhinostery. He currently resides in his manor in Windurst Walls.' },
