    ['Yoskolo'] = { type = 'Standard Merchant', zones = { 'Jeuno', 'Merry Minstrel Meadhouse, Lower Jeuno' }, location = 'Merry Minstrel Meadhouse, Lower Jeuno H-8' },
    ['Young Aldo'] = { type = 'Mission NPC', zones = { 'Cutscenes only.' }, location = 'Cutscenes only.', note = 'Involved in Missions:\n* A Crystalline Prophecy (Mission)' },
    ['Yow Rabntah'] = { zones = { 'Cut Scenes Only', 'Cutscene', 'Kazham' }, location = 'Cut Scenes Only', note = 'Involved in Quests:\n* Sins of the Mothers\n\nInvolved in Missions:\n* San d\'Oria Mission 4-1: Magicite\n* Bastok Mission 4-1: Magicite\n* Windurst Mission 4-1: Magicite\n\nNotes:\n* Yow Rabntah was a Ranger from Kazham. Before the outbreak of the Crystal War, Iru-Kuiru, the minister for the Rhinostery, hired her to assist on the Multi-National Expedition to the Northlands. She was sent along with three Mythril Musketeers -- Ulrich, Raogrimm, and Cornelia -- to investigate the northlands in cooperation with Francmage of San d\'Oria.' },
    ['Yoyoroon'] = { type = 'Standard Merchant', zones = { 'Nashmau' }, location = 'Nashmau G-6, 2nd Floor', note = 'Involved in Quests:\n* The Rider ComethUnwavering ResolveA Stygian Pact\n\nNotes:\n*  Automaton parts stack to 12 * Automaton parts may be purchased in quantities of 1~12' },
    ['Yrvaulair S Cousseraux'] = { type = 'Campaign Hero NPC', zones = { 'Battle', 'San d\'Oria (S)', 'Spotted at: East Ronfaure (S), Jugner Forest (S), The Eldieme Necropolis (S), Batallia Downs (S), and Vunkerl Inlet (S).' }, location = 'Spotted at: East Ronfaure (S), Jugner Forest (S), The Eldieme Necropolis (S), Batallia Downs (S), and Vunkerl Inlet (S).', note = 'Involved in Quests:\n* Knot Quite There\n* A Manifest Problem\n\nNotes:\n*  Appears to be DRG/PLD. * Casts Protect IV, Shell IV and Cure IV on himself when needed. * Uses Invincible. * Has access to all Polearm WS\'s including Impulse Drive. * Yrvaulair throws special "Volant Angon" that inflict direct damage. * Will not engage an enemy with his weapon unless they come within melee range, will stand back and throw his Angons. * Talk: Not once in the four hundred years since the dawn of the Royal Knights has the kingdom found itself in such peril. Let us take up our pikes and stand our ground to ensure another four centuries of prosperity! * Battle cry: My spear is lightning...and your scream shall be the thunder which follows my mighty strike!' },
    ['Ysadel'] = { zones = { 'Adoulin', 'Eastern Adoulin' }, location = 'Eastern Adoulin G-6' },
    ['Ysayle'] = { zones = { 'San d\'Oria (S)', 'Southern San d\'Oria (S)' }, location = 'Southern San d\'Oria (S) L-6' },
    ['Yudi Yolhbi'] = { zones = { 'Al Zahbi' }, location = 'Al Zahbi G-10' },
    ['Yuhito-Kubhito'] = { type = 'Adventurer\'s Assistant NPC', zones = { 'Port Windurst', 'Windurst' }, location = 'Port Windurst E-7', note = 'Notes:\nthumb|100px|ElementsOffers Information on the Elemental Relationships: :W-what? You don\'t want to see my chart of elemental correlations, do you? \'Cause if you do, well, I\'m sorry, I don\'t know anything about such a thing. Eeew... Well, if you\'re going to be so pushy about it... Here, but only because you\'re begging me to show it to you... View the Chart of Elemental Correlations? :*"Yes.": [Displays a chart of elemental relationships] Okay, okay...hold your horses. This is strictly between you and me, all rightaru? Of course, you know about the prime elementals, rightaru? They are the eight elements or energies that control the universe. This chart shows their interrelationships. The six elements on the perimeter are in cyclical ascendancy over one another. Or, putting it simply-wimply: Water dominates fire, fire dominates ice, ice dominates wind...while wind dominates over earth, earth dominates lightning, and lightning dominates water. The two elements in the center, light and darkness, are in direct opposition to each other. Oh, and one other thing: these elements are also closely connected to your health condition! I can explain more about this if you\'re interested. ::*"Yes.": Then listen up... Disease is to fire as paralysis is to ice, silence is to wind as petrification is to earth, and stun is to lightning as poison is to water. Finally there is charm, which is related to light, while blind, curse, and sleep are infused with the power of darkness. What all this means is this: if your armor resists certain elements, then it will also help prevent the status ailments tied to those elements. And there you have it... But remember, this is our little secret, rightaru? Come back and ask to see it again whenever you need to jog your memory. ::*"No.": And there you have it... But remember, this is our little secret, rightaru? Come back and ask to see it again whenever you need to jog your memory. :*"No.": Well, that\'s your own choice. Just don\'t come crying to me when you try to put out a fire with powerful wind magic and end up creating a sea of flames instead!' },
