    ['Zauko'] = { type = 'Quest Giver', zones = { 'Jeuno', 'Lower Jeuno' }, location = 'Lower Jeuno I-6', note = 'Starts Quests:\n* Community Service\n\nInvolved in Quests:\n* Save the Clock Tower\n\nNotes:\n* Will notify you who last completed the Community Service quest. Quotes: :"I am Zauko. I patrol Lower Jeuno." :"We guards need more than muscle. We need the residents\' trust." :"Come see me if you\'re ever in trouble."' },
