    ['Zovriace'] = { zones = { 'San d\'Oria', 'West Ronfaure - Travels a route from La Theine Plateau' }, location = 'West Ronfaure - Travels a route from La Theine Plateau (F-12) to the Southern San d\'Oria gate (I-6).', note = 'Notes:\nWhen Spoken to says "Let me be! I return to Southgate with word on La Theine." When he gets back to the south gate he says to Colmaie ( A guard at Southgate) "Scout reporting! All is quiet on the roads to La Theine!" Then runs back to his starting posistion.' },
